pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual < 20 {
        // Tight but non-zero fit: mild reward scaled by tightness.
        score -= (20 - post_residual) as f64 * 1.5;
    }

    // Penalize leaving a gap that the lookahead item cannot use, but the gap
    // is large enough to be useful in general (soft dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward if the lookahead item exactly fills the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins; also penalize the new-bin candidate mildly.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when fits into open bins are poor.
    if bin_residual == bin_capacity {
        score += 70.0;
        // More open bins => new bin is more acceptable (spread load).
        score -= open_bins_count as f64 * 0.8;
        // Prefer opening a new bin early in the stream when residual spread is high.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If mean residual is large, existing bins are roomy; new bin less needed.
        score += mean_residual * 0.2;
    }

    // Mild scaling of raw post residual with progress: late in stream, waste
    // matters more (fewer future items to fill gaps).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * 0.3 * progress;

    // Penalize bins whose residual deviates strongly from mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps are risky if the next item cannot use them.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Reward placements that still fit the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Tight-fit coupling: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: with many open bins, avoid spreading; with few bins,
    // tolerate looser fits rather than opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 2.0 * bin_pressure;

    // Penalize bins whose residual deviates far above the mean (fragmented state).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using the only bin that can fit the item,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open a bin early when few bins are open.
        score -= 1.5 * open_bins_count as f64;
        // If the current bin would leave a large dead gap, new bin becomes viable.
        if post_residual >= 40 {
            score -= 45.0;
        }
        // If the item nearly fills a fresh bin, opening is excellent.
        if fill_ratio > 0.8 {
            score -= 30.0;
        }
        // Never open a new bin when a perfect fit exists elsewhere.
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small gaps that few future items can use.
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading.
    score += open_bins_count as f64 * 0.5;

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item cannot fit and post residual is wasted.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: mildly favor new bin only when current fit is terrible.
    if bin_residual == bin_capacity {
        score -= 5.0;
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // Stream progression: later in stream, tighten dead-space tolerance.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual), with quadratic pressure.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits into the residual left behind -> strong bonus.
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.4; // exact match (slack=0) gets -30
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to the overflow.
        let overflow = (next_item_size - post_residual) as f64;
        score += overflow * 0.35;
    }

    // Compare against mean residual: bins already tighter than average are
    // good targets; bins looser than average should be preserved.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.25;
    } else {
        score += (res - mean_residual) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline, penalized unless current
    // open bins would waste a lot of space.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: its full residual, discounted slightly
        // so it only wins when existing bins create large dead space.
        score = bin_capacity as f64 * 0.9;
        // If next item is small, a fresh bin is flexible.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 8.0;
        }
        // Fewer open bins -> opening one is cheaper.
        score -= open_bins_count as f64 * 1.5;
    }

    // Early stream: be slightly more willing to open bins to build a good spread.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size (1..10
    // are unusable for small items; treat small gaps relative to typical item sizes)
    // are pure waste and must be heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space: unusable gap
    } else if post_residual < 20 {
        score += 25.0; // nearly-dead gap
    } else if post_residual < 35 {
        score += 8.0;  // awkward gap
    }

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with next item lookahead: if the next item fits exactly in the
    // post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use the leftover gap: gap likely becomes dead space
        if post_residual < next_item_size && post_residual < 30 {
            score += 15.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless dead space penalty dominates).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open bins pressure: with many open bins, encourage consolidation into
    // existing bins rather than spreading; with few open bins, opening a new
    // bin is less costly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * (4.0 + 6.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from number of open bins.
        score = 45.0 + bin_pressure;
    } else {
        // Tighter fit (smaller post_residual) already favored via base score;
        // add mild bonus for filling bins more than mean residual.
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit core)
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: quantize into capacity-fraction buckets.
    // Residuals in the "dead zone" (1..10) are nearly useless -> heavy penalty.
    let dead = if post_residual > 0 && post_residual < 10 { 1 } else { 0 };
    score += dead as f64 * 40.0;

    // Perfect / near-perfect fit reward via modulo harmonic classes
    if post_residual == 0 {
        score -= 100.0; // exact closure
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Integer-division harmonic class: post_residual in coarse 10-wide classes.
    // Bins whose residual class matches the next item's size class get a bonus
    // (this bin is likely to serve the lookahead item too).
    let pr_class = post_residual / 10;
    let nx_class = (next_item_size as u32).saturating_sub(1) / 10;
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + (10 - (pr_class as i32 - nx_class as i32).abs()) as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // lookahead cannot use leftover: mildly penalize small leftovers
        if post_residual < 20 {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Crowding pressure: when many bins are open, prefer reusing tight bins
    // over spreading; when few bins, tolerate opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += crowd * 0.5 * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // Penalize opening a bin unless fitting is scarce or item is huge.
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 60.0 + 2.0 * fitting_bins_count as f64 };
        let big_item = if item_size > bin_capacity / 2 { -20.0 } else { 0.0 };
        score += scarcity + big_item + 5.0 * (1.0 - progress);
    } else {
        // Reward using existing bins, more for tighter fits relative to capacity.
        let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * tightness;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is an outlier-tight bin; using it consolidates waste.
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    } else {
        score += (-diff) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // dead space penalty
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact chain fit is excellent.
            if post_residual == next_item_size {
                score -= 15.0;
            } else {
                let slack = (post_residual - next_item_size) as f64;
                // Reward chain fit, decaying with leftover slack after next item.
                score -= 12.0 - slack.min(20.0) * 0.3;
            }
        } else {
            // Next item cannot follow here: penalize proportionally to wasted chain potential.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 5.0;
    }

    // Compare against mean residual: bins tighter than average are good targets.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - res_f) * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early
    // in the stream or when many bins are open (fragmentation risk management).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_bonus = 8.0 * (1.0 - progress) + (open_bins_count as f64) * 0.3;
        score -= new_bin_bonus;
    }

    // Mild preference to keep the number of open bins bounded late in the stream.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity as f64 - post_residual as f64) * (0.35 + 0.45 * progress);

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize wasting the lookahead opportunity.
            score += 8.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Fragmentation pressure: prefer bins below mean residual when many bins are open.
    let residual_f = bin_residual as f64;
    let diff = residual_f - mean_residual;
    score += 0.08 * diff * (open_bins_count as f64).sqrt();

    // New-bin candidate handling: make an empty bin attractive only when fits are poor
    // or the item is huge relative to typical residuals.
