    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= 40.0 * poly * (0.5 + t);

    // Reward tight fits more strongly as the stream progresses.
    let fit = 1.0 - norm_pr;
    score -= fit * fit * (10.0 + 20.0 * t * t);

    // Penalize leaving residuals that barely miss the lookahead item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) * (0.5 + t);
        } else {
            let slack = (pr - ni) / cap;
            score -= 15.0 * slack * (1.0 - slack) * (1.0 - t * 0.5);
        }
    }

    // Last-chance bonus: strongly favor this bin if it's the only fitting one.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr * 0.5);
    }

    // Mild penalty for opening a new bin when many bins are already open
    // and residual is still generous.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - t) + 0.5 * open_bins_count as f64;
    }

    // Coupling with mean residual: avoid making mean worse than needed.
    score += 0.1 * (mean_residual - pr) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: classify dead space into residue classes mod 10.
    let class = post_residual % 10;
    // Residues 1..9 are "awkward" dead space; 0 is perfectly packed; exact fill is best.
    match class {
        0 => {
            if post_residual == 0 {
                score -= 40.0; // perfect closure
            } else {
                score -= 12.0; // residual is a multiple of 10, reusable by small items
            }
        }
        1 | 2 | 3 => score += 6.0 + (class as f64) * 2.0, // tiny unusable slivers
        4 | 5 | 6 => score += 2.0,                        // medium: partially reusable
        _ => score -= 4.0,                                // 7..9: large enough for many items
    }

    // Integer-division thresholds: how many "average small items" (size 10) fit post-placement.
    let slots = post_residual / 10;
    score -= slots as f64 * 3.0;

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact next-item fit is gold.
            if next_item_size == post_residual {
                score -= 30.0;
            } else {
                score -= 8.0 + (next_item_size as f64) * 0.1;
            }
        } else {
            // Next item won't fit here; penalize proportionally to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer tighter bins among many candidates (best-fit flavor).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.2;

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Open a new bin if existing residuals are all too small or mean residual is low.
        let mean_gap = (mean_residual - item_size as f64).abs();
        let open_bonus = if open_bins_count > 0 { 8.0 } else { -20.0 };
        score = score.max(0.0) + 35.0 * (1.0 - pressure) + open_bonus - mean_gap * 0.1;
        // Late in the stream, avoid spreading across many bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: any post_residual that is too small to
    // plausibly hold a future item is "unusable". Penalize it heavily,
    // scaled by how dead it is (smaller gap = worse).
    let min_useful = if next_item_size > 0 { next_item_size.min(40) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        let deadness = (min_useful - post_residual) as f64 / min_useful as f64;
        score += deadness * 300.0;
    }

    // Moderate dead space (below typical mid item sizes) also penalized softly.
    if post_residual > 0 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 4.0;
    }

    // Reward leaving room for the lookahead item: a bin whose post_residual
    // can still fit the next item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * post_residual as f64;
    } else if next_item_size > 0 {
        // Gap just below next item size is a trap.
        score += 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes expensive.
    let pressure = open_bins_count as f64 / 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 80.0 + pressure * 50.0;
    } else {
        // Slight reward for filling existing bins, stronger under pressure.
        score -= 10.0 + pressure * 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, use it rather
    // than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Prefer bins below mean residual (tighter bins) mildly.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in the stream, be a bit more willing to open fresh bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= (1.0 - progress) * 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins whose post-residual exactly fits the next item (2-step lookahead match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= 60.0 / (1.0 + fit_gap); // perfect next-fit match gets big reward
        if fit_gap == 0.0 {
            score -= 40.0; // exact match: chain placement
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // This bin becomes dead space after placement if residual is small
        if post_residual < 10 {
            score += 15.0; // tiny unusable sliver penalty
        }
    }

    // Reward tight fits relative to mean residual
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 25.0 * (1.0 - tightness);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins with below-mean residual (fill the fullest bins first)
    let mr = mean_residual.max(1.0);
    score += 10.0 * ((post_residual as f64) - mr) / mr.max(10.0);

    // Early in the stream, be more willing to open new bins for large items
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless item is large or bins are few
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 40.0 * large_item - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize creating dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && (next_item_size as u32) > post_residual {
            // Dead space below next item's size; worse the smaller it is.
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        } else if next_item_size as u32 <= post_residual {
            // Next item could chain into this bin: reward.
            score -= 2.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Many open bins: prefer consolidating into existing bins, discourage new bins.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 6.0 * open_pressure;
        // Early in the stream, opening bins is cheaper; later, avoid it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
        // If next item is large, a fresh bin has value.
        if next_item_size as u32 > bin_capacity / 2 {
            score -= 3.0;
        }
    } else {
        // Existing bin: mild reward when many bins open.
        score -= 2.0 * open_pressure;
    }

    // Prefer bins whose residual deviates below the mean (more filled bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Slight preference for larger item share of bin.
    score -= 0.1 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: post residual (tighter fit -> lower score)
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, waste matters more per-unit; late, squeeze harder.
    let progress_warp = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= pr * pr / cap * (0.5 + progress_warp);

    // Penalty for leaving dead space that next item cannot use (smooth interaction)
    let usable = if nxt > 0.0 { (pr / nxt).min(1.0) } else { 1.0 };
    score -= usable * usable * 6.0 * (1.0 - progress_warp * 0.5);

    // Last-chance bonus: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 10.0 * progress_warp;
    }

    // Mild penalty for opening a new bin when many bins are open and mean residual is high
    let is_new = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += is_new * (8.0 + 0.05 * open_bins_count as f64 + mean_residual * 0.08);

    // Small reward for large items placed into large residuals (good pairing)
    let fit_ratio = item / cap;
    score -= fit_ratio * (bin_residual as f64 / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer-division buckets of 10.
    let post_class = post_residual / 10;
    // Dead space penalty grows super-linearly for small unusable remnants.
    if post_residual > 0 {
        // Small remnants (<10, the minimum item size) are pure dead space.
        if post_residual < 10 {
            score += 40.0;
        } else {
            // Reward post_residual that is a "harmonic" size: divisible cleanly
            // into common item classes (multiples of 10 or 25).
            let harmonic = (post_residual % 10 == 0) as f64 * 6.0
                + (post_residual % 25 == 0) as f64 * 4.0
                + (post_residual % 50 == 0) as f64 * 3.0;
            score -= harmonic;
        }
        // Penalize remnants in awkward mid-range classes (11..19, 31..39 style gaps)
        let awkward = (post_class % 2 == 1) as f64 * 3.0;
        score += awkward;
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves another remnant: mild reward scaled by fit tightness.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * tightness;
        } else {
            // Next item cannot use this bin's remnant: penalize proportionally.
            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size as f64 + 1.0)).max(0.0);
        }
        // Harmonic class match: post_residual / next_item_size integer ratio
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer tight fits generally: reward small post_residual relative to capacity.
    score -= 10.0 * (1.0 - post_residual as f64 / cap);

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early (many items remain) but costly late.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 20.0 * progress;
        // If current bin would leave a tiny dead remnant, opening a new bin looks better.
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
    }

    // Mild penalty for spreading across too many open bins relative to mean residual.
    if open_bins_count > 0 && (bin_residual as f64) > mean_residual * 1.5 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Pressure on number of open bins: discourage spreading across many bins,
    // but allow new bins when the current one would leave dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.35 + 0.25 * (1.0 - progress));

    // Mean residual coupling: prefer bins below mean residual (consolidation).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else {
            // Next item won't fit here: slight penalty for wasted potential.
            score += 3.0;
        }
    }

    // New-bin candidate: make it moderately attractive only when it avoids
    // creating dead space in an existing bin; otherwise less preferred.
    if bin_residual == bin_capacity {
        score += 6.0;
        if post_residual > 0 && post_residual < 10 {
            score += 15.0; // fresh bin leaving tiny gap for future items is fine later
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (post_residual close to 0)
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.5;

        // Perfect 2-step chain: next item exactly fills this bin afterward
        if post_residual == next_item_size {
            score -= 60.0;
        } else if gap <= 5.0 {
            score -= 15.0;
        }

        // Penalize leaving residual too small for the next item (dead space)
        if post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Penalize wasting a nearly-full bin on a small item
    if item_size < bin_residual / 3 && bin_residual < bin_capacity {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= bin_capacity * 3 / 4 {
            score -= 35.0;
        }
    }

    // Late in the stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for the next item: penalize proportionally.
            score += 4.0 * ((next_item_size - post_residual) as f64 / 20.0).min(3.0);
        }
    }

    // Prefer filling bins with low mean residual (consolidate waste) when many bins are open.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 5.0 * dev;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early on, opening bins is fine; later, discourage fragmentation.
        score = 45.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 20.0; // discourage new bin when something already fits
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // empty bin guarantees next-item fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, but with a non-linear (quadratic/cubic) coupling
    // so that very small residuals are disproportionately favored as the stream progresses.
    let mut score = pr
        - 40.0 * norm_pr * norm_pr * (1.0 + progress)
        + 15.0 * norm_pr * norm_pr * norm_pr * (1.0 - progress);

    // Smooth interaction: tight fits (small post_residual) matter more late in the stream,
    // while early on a moderate residual is acceptable.
    let tightness = (1.0 - norm_pr).clamp(0.0, 1.0);
    score -= 25.0 * tightness * tightness * progress;

    // Penalize creating dead space below the smallest plausible item (10) via a smooth bump.
    let dead = (10.0 - pr).max(0.0) / 10.0;
    score += 30.0 * dead * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it (smoothly).
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead coupling: reward leaving a residual that can still fit the next item,
    // with a smooth saturating form.
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let slack = ((pr - next_item_size as f64) / cap).clamp(0.0, 1.0);
        score -= 12.0 * fits_next * (1.0 - slack * slack);
    }

    // Mild dispersion pressure: bins far from the mean residual get a smooth penalty,
    // encouraging homogenization of open bins.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (multiples of 25 / 20) are reusable dead-space-wise.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward residuals that are harmonic anchors (0, 25, 50, 75, 100-ish).
    let anchor = (pr / 25.0).round() * 25.0;
    let anchor_dist = (pr - anchor).abs();
    score -= 6.0 * (1.0 - anchor_dist / 12.5).max(0.0);

    // Modulo-10 class of post_residual: multiples of 10 pair well with integer item sizes.
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Dead space penalty grows super-linearly for tiny unusable residuals.
    if post_residual < 10 {
        score += 20.0 * (10.0 - pr);
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item won't fit here; penalize leaving mid-range residuals
            // that block the next item while wasting space.
            score += 3.0 * frac;
        }
    }

    // Tightness coupling: prefer bins whose residual is close to the item size
    // (best-fit style), scaled by item size class.
    let waste = (bin_residual - item_size) as f64;
    score += 0.15 * waste;

    // Late in the stream, consolidate: penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline at ~capacity minus a consolidation pull.
        score += 15.0 * progress + 0.05 * open_bins_count as f64;
        // But if no open bin fits well, allow a fresh bin.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight pull toward bins deviating from mean residual (extreme-fill strategy).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Medium gaps that can't fit the smallest plausible item are also risky.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Reward tight fits (perfect or near-perful packing).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Penalize if next item cannot fit in post-residual but this bin could hold it otherwise.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: encourage filling existing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make it less attractive unless open bins are scarce or fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * -0.0; // base penalty for opening new bin
        if open_bins_count == 0 {
            score -= 25.0; // must open a bin
        }
        // If current fit is terrible, new bin becomes relatively better.
        if post_residual > 0 && post_residual < 10 && item_size < bin_capacity {
            score -= 35.0;
        }
    }

    // Slight phase pressure: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is an ideal chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly it will fit.
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * next_fit * next_fit;
        } else {
            // Next item will NOT fit in this bin afterwards: penalize dead space,
            // scaled by how much is wasted relative to the next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(40.0);
        }
    }

    // Compare post residual against mean residual: leaving more than average
    // residual is wasteful; leaving much less is good consolidation.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.3 * (mean_residual - pr).min(50.0);
    } else {
        score += 0.2 * (pr - mean_residual).min(50.0);
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: a fresh bin should only win when no open bin
    // offers a decent fit. Give it a neutral-to-slightly-high score that decays
    // as the stream progresses (late in the stream, prefer closing out bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 0.85 * bin_capacity as f64 - 10.0 * progress + 0.15 * next_item_size as f64;
        // Opening a new bin is fine if the next item is large and current bins are tight.
        if next_item_size >= 70 && mean_residual < 30.0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more strongly than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that cannot fit even a minimum-size item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item cannot fit here, slight penalty for blocking.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Encourage filling nearly-full bins: reward small bin_residual before placement.
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * fill_ratio;

    // Time horizon: early in stream, be more willing to open new bins (penalize
    // cramming into open bins slightly); late in stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus early-stream discount.
        score += 20.0 - 25.0 * (1.0 - progress);
        // Prefer opening a new bin when many open bins are fragmented.
        if (mean_residual < 20.0) && open_bins_count > 2 {
            score -= 15.0;
        }
    } else {
        // Late in the stream, favor using existing bins.
        score += 10.0 * progress;
    }

    // Fragmentation guard: penalize leaving residuals just above mid sizes.
    if post_residual > 40 && post_residual < 60 {
        score += 3.0;
    }

    // Slight preference for bins with above-average residual when consolidating.
    if (bin_residual as f64) > mean_residual && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual, with a convex (quadratic) penalty
    // so large dead space is punished super-linearly.
    let mut score = post + 0.9 * (post / cap) * (post / cap) * cap;

    // Smooth non-linear coupling with stream progress:
    // early in the stream, tolerate larger post-residuals (bins can still be filled);
    // late in the stream, demand tight fits since leftover space is likely wasted.
    let tightness_bias = (1.0 - progress) * 0.35 * post - progress * 0.45 * post;
    score += tightness_bias;

    // Cubic interaction: post_residual^3 scaled by progress — punishes
    // wasteful placements increasingly as the stream nears its end.
    score += progress * (post * post * post) / (cap * cap) * 0.02;

    // Reward filling a bin nearly exactly (post near 0) with a smooth bump.
    let fit_quality = 1.0 - (post / cap);
    score -= 2.5 * fit_quality * fit_quality * fit_quality * (item / cap);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin (smooth exponential reward).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: opening a fresh bin is attractive early in the stream
    // or when the item would leave a very poor residual in existing bins.
    if bin_residual == bin_capacity {
        let poor_fit = post / cap; // = 1.0 - item/cap for a fresh bin
        let waste_elsewhere = (mean_residual - item).max(0.0) / cap;
        let new_bin_cost = 3.0 - 2.0 * progress
            - 4.0 * (1.0 - poor_fit) * (1.0 - poor_fit)
            - 1.5 * waste_elsewhere;
        // If next item is large, a fresh bin helps it fit later.
        let lookahead_bonus = if next_item_size > 0 {
            1.5 * (next_item_size as f64 / cap)
        } else {
            0.0
        };
        score = 8.0 - new_bin_cost - lookahead_bonus;
    } else {
        // Slight penalty for using a bin when many bins fit, to preserve
        // flexibility (smooth in fitting_bins_count).
        score += 0.15 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual coupling: bins deviating from the mean residual get a
    // smooth quadratic penalty, encouraging residual homogenization.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.01 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "clean" the leftover is.
    // Residuals that are multiples of common item sizes (or near-zero) are valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, zero waste
    } else if pr <= 10 {
        score -= 30.0; // nearly perfect, dead space unusable anyway
    } else {
        // harmonic bonus: residual divisible by small common sizes
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 50 == 0 { score -= 8.0; }
        // awkward leftover: in the dead zone (11..=19) nothing typical fits
        if pr >= 11 && pr <= 19 { score += 15.0; }
    }

    // Lookahead coupling: if the next item fits the post residual exactly or nearly,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 45.0;
        } else if slack <= 10 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > pr {
        // next item cannot use this leftover; penalize proportionally
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fits naturally via post_residual already
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only open a new bin when it's early in the
    // stream or open bins are very full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // open new bin if existing bins are crowded or stream is early
        if avg_fullness > 0.85 || open_bins_count == 0 {
            score -= 25.0;
        } else if progress < 0.2 && open_bins_count < 4 {
            score -= 10.0;
        } else {
            score += 35.0; // default: reuse open bins
        }
        // large items waste less absolute space in a fresh bin
        if item_size >= 70 { score -= 10.0; }
        if item_size <= 20 { score += 8.0; }
    }

    // Mild preference for filling bins deeply as the stream progresses.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead space avoidance ---
    // Gaps that are too small for even the smallest plausible item are "dead space".
    // Penalize them harshly with a non-linear (quadratic) term.
    if post_residual > 0 {
        // Assume smallest item could be as small as 1; a gap < ~10 is risky.
        let dead_threshold: f64 = 10.0;
        let pr = post_residual as f64;
        if pr < dead_threshold {
            // Steep penalty for near-unusable slivers.
            score += (dead_threshold - pr) * (dead_threshold - pr) * 1.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward filling the bin tightly: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // --- Lookahead coupling ---
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx {
            // The next item also fits here: reward keeping this bin attractive.
            score -= 12.0;
        } else if post_residual > 0 && (post_residual as f64) < nx {
            // Post residual is useless for the known next item: mild penalty.
            score += 6.0;
        }
        // If next item fits exactly after this placement, big bonus.
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: strongly prefer closing bins out.
        score -= 15.0;
    }

    // --- Open bins pressure ---
    // Many open bins: prefer consolidating into existing ones (lower score for
    // existing bins relative to opening new ones when open_bins_count is high).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0).max(1.0);
    score += pressure * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }
    // If many bins fit, prefer the one that stays tightest (already via post_residual),
    // but add slight dispersion penalty based on mean residual mismatch.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // New-bin candidate: add a fixed opening cost that shrinks as stream progresses
    // (late in stream, opening a bin is fine since consolidation matters less).
    if bin_residual == bin_capacity {
        let open_cost = 45.0 * (1.0 - 0.5 * progress);
        score += open_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain fit: this bin becomes exactly full next step.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits, leftover remains but bounded.
            score -= 15.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // Dead space: next item cannot use the remainder -> penalize.
            let waste = post_residual as f64;
            score += 8.0 + 0.35 * waste;
        }
    } else {
        // Last item: just minimize leftover waste.
        score += 0.5 * post_residual as f64;
    }

    // Compare residual against mean residual across open bins.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 10.0; // leaving this bin unusually tight vs others
    } else if (post_residual as f64) > mean_residual {
        score -= 5.0; // keeps this bin's residual near/above average: fine
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing residuals are all poor fits for the current or next item.
    if is_new_bin {
        let poor_fits = if next_item_size > 0 {
            post_residual.min(next_item_size) == 0 || post_residual < next_item_size
        } else {
            false
        };
        let base_penalty = 30.0 + 10.0 * (open_bins_count as f64).sqrt();
        if poor_fits || fitting_bins_count == 0 {
            score -= 20.0; // nothing useful elsewhere: new bin is good
        } else {
            score += base_penalty * (0.5 + 0.5 * progress);
        }
    }

    // Mild late-stream tightening: reduce fragmentation as stream ends.
    if progress > 0.8 {
        score += 0.15 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits into the post-residual, reward this bin;
    // if the next item would be blocked, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            score += 2.5 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Penalize opening a brand-new bin unless it is genuinely necessary:
    // only attractive when no existing bin fits or existing residuals are poor.
    if bin_residual == bin_capacity {
        let necessity = if fitting_bins_count == 0 {
            0.0
        } else {
            (fitting_bins_count as f64).ln() + 1.0
        };
        score += 18.0 * necessity;
        // Late in the stream, opening new bins is more costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If mean residual is high, prefer using existing bins.
        score += 0.15 * mean_residual;
    } else {
        // Reward using the last-chance bin (only one fitting bin).
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
        // Mild bonus for keeping the number of open bins from exploding.
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is below the mean (consolidating fuller bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Dead-space penalty: residuals that are too small to fit typical items.
    if post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: quadratic penalty on wasted space (dead space grows quadratically).
    let mut score = pr * (1.0 + fit_norm * fit_norm);

    // Smooth cubic coupling of waste with stream progress:
    // early on, tolerate waste (bins will fill later); late, penalize heavily.
    score += pr * pr / cap * (progress * progress * (3.0 - 2.0 * progress));

    // Reward tight fits via smooth saturating term on post_residual smallness.
    let tight = 1.0 - fit_norm;
    score -= 12.0 * tight * tight * tight * (1.0 + progress);

    // Lookahead: if next item fits the post-residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            let g = gap / cap;
            score -= 8.0 * (1.0 - g) * (1.0 - g);
        } else {
            let g = (-gap) / cap;
            score += 4.0 * g / (1.0 + g);
        }
    }

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins when residuals are large.
    let mr = mean_residual / cap;
    score += 0.5 * open_bins_count as f64 * mr * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a bin for small items, allow for large ones.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = cap * (1.2 - fill) + 10.0 * progress * (1.0 - fill);
        if fitting_bins_count > 0 {
            score += 15.0 * (1.0 - fill) * (1.0 - fill);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the residual after placement ---
    // Residuals divisible by 10 are "harmonic" (likely to be filled by
    // common item sizes 10..80); odd / prime-ish residuals are dead space.
    let pr = post_residual;
    let harmonic = (pr % 10 == 0) as f64;
    score -= harmonic * 12.0;

    // Small post-residuals that cannot host the next item are dead weight.
    if next_item_size > 0 {
        if pr < next_item_size {
            // dead space for the lookahead: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.9;
        } else {
            // post residual exactly matches a modulo class of next item:
            // perfect pairing reward
            let pair = (pr % next_item_size.max(1) == 0) as f64;
            score -= pair * 8.0;
            // residual that fits next item snugly
            let snug = (pr - next_item_size) as f64;
            score -= (snug / bin_capacity as f64) * 10.0 * (snug <= 20.0) as u8 as f64 as f64;
        }
    }

    // --- Integer-division thresholds on post_residual ---
    // Classify residual into coarse buckets: 0..10 excellent, 10..25 ok,
    // 25..60 mediocre, >60 poor (wastes a big bin on a small item).
    let bucket = pr / 10; // integer division
    score += match bucket {
        0 => -6.0,
        1 => -2.0,
        2 => 0.0,
        3 | 4 | 5 => 4.0,
        _ => (bucket as f64) * 1.5,
    };

    // --- Last-chance bonus: only bin that fits the item ---
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early (stream is long) or when
        // the item fits a harmonic class leaving a round residual (e.g. 100-30=70).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let round_left = (pr % 10 == 0) as f64;
        score = 40.0 - round_left * 10.0 - (1.0 - progress) * 5.0;
        // discourage new bins when many open bins already have room
        score += (open_bins_count as f64) * 0.3;
        // strongly prefer new bin if existing bins would leave bad residuals
        if pr >= 60 {
            score -= 5.0;
        }
    }

    // --- Mean residual coupling: prefer bins below mean residual
    // (fill the emptier-relative bins, keep fuller ones for small items) ---
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 6.0;

    // --- Modulo coupling between item and residual capacity fractions ---
    // Items that are themselves harmonic (divisible by 10) pair well with
    // harmonic residuals; reward filling harmonic bins with harmonic items.
    if item_size % 10 == 0 && pr % 10 == 0 {
        score -= 5.0;
    }
    // Odd-sized items into odd-residual bins avoid compounding fractions
    if item_size % 2 == 1 && bin_residual % 2 == 1 && pr % 2 == 0 {
        score -= 2.0;
    }

    // Slight tie-break noise-free determinism: prefer earlier bins
    score += 0.01 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item are worthless "dead space" -> heavy penalty.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 5.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits: low post_residual relative to bin capacity.
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 15.0;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement (chains well).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size > post_residual {
            // next item can't use this bin anyway; residual more likely dead
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: only bin that fits the item -> strong bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of open bins unless
    // the new-bin candidate is genuinely better (empty-bin call gets relief).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin: penalize mildly, scaled by how many bins already open.
        score += 8.0 + open_bins_count as f64 * 1.5 + progress * 5.0;
    } else {
        // Reusing an open bin reduces bin count pressure: reward.
        score -= open_bins_count as f64 * 0.5;
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., using up a large residual) is efficient.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: leaving no residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item (chain packing).
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        if gap == 0.0 {
            score -= 500.0; // exact 2-step chain: place here, then next item fills perfectly
        } else if pr >= ni {
            // next item fits; prefer small gap, scaled by tightness of fit
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space proportional to leftover
            score += 0.5 * gap;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are worth filling.
    let tightness = mean_residual - post_residual as f64;
    score += 0.3 * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize the brand-new empty bin candidate unless nothing decent fits:
    // opening a bin is costly, so give it a baseline handicap that shrinks
    // late in the stream when consolidation matters less.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 - 50.0 * progress;
        // but if next item also fits perfectly after this one in a fresh bin,
        // soften the handicap slightly
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Mild pressure to reduce number of open bins when many are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual) with a non-linear term.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly encourage using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item could also fit in the leftover space,
    // reward leaving exactly enough room; penalize residuals that are
    // useless for the next item (dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: reward proportional to how perfectly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize.
            let dead = post_residual as f64;
            score += 0.10 * dead;
        }
    }

    // Penalize opening a new bin when good open bins exist, but allow it
    // when the current bin would leave a large unusable fragment.
    if bin_residual == bin_capacity {
        let fragment = post_residual as f64;
        let fragment_penalty = if fragment < 15.0 { 0.0 } else { 12.0 * (fragment / bin_capacity as f64) };
        score += 20.0 + fragment_penalty;
        // Late in the stream, opening fresh bins is cheaper (fewer wasted bins overall).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If many bins are open and fragmented, a new bin helps balance.
        score -= 0.5 * (open_bins_count as f64).min(10.0);
    } else {
        // Mild preference for filling bins with smaller residuals first
        // (best-fit flavor) beyond raw post_residual.
        score += 0.05 * (bin_residual as f64 - item_size as f64).max(0.0) * 0.0;
    }

    // Encourage balancing residuals toward the mean to keep options open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit = item_size as f64 / cap;

    // Base: quadratic penalty on wasted residual, scaled by stream progress
    let mut score = pr * (1.0 + 1.5 * t * pr / cap);

    // Smooth interaction: prefer tight fits more strongly as stream progresses
    score -= 8.0 * fit * (0.5 + t);

    // Non-linear coupling of post_residual with mean residual of open bins
    let norm_mean = mean_residual / cap;
    score += 3.0 * pr / cap * (norm_mean * norm_mean);

    // Reward the last-chance bin smoothly
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 10.0 * last_chance * (1.0 - pr / cap);

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 5.0 * (1.0 - slack * slack);
        } else {
            let gap = (nx - pr) / cap;
            score += 4.0 * gap * gap;
        }
    }

    // Penalize spreading across too many open bins (smooth in count)
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let progress = step_index as f64 / total_items as f64;

    // Class A: near-perfect fits (post_residual in low multiples of 10)
    if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // Integer division thresholds: post_residual bucketed by quarters of capacity
    let quarter = bin_capacity / 4;
    if post_residual > 3 * quarter {
        score += 25.0; // large dead space penalty
    } else if post_residual > quarter * 2 {
        score += 8.0;
    }

    // Modulo class coupling: does next item divide evenly into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = (post_residual - next_item_size) as f64;
        score -= 20.0 - 0.2 * fit_quality; // lookahead chains reward tight next fits
        // Harmonic residue: next item leaves a residual divisible by 10
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this residual: penalize proportionally to wasted capacity
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Prefer filling bins with small residuals relative to the mean
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: only attractive early or when nothing fits well
    if bin_residual == bin_capacity {
        let penalty = 30.0 + 60.0 * progress;
        if fitting_bins_count == 0 {
            score -= penalty + 50.0;
        } else {
            score += penalty;
        }
    }

    // Mild pressure to consolidate: fewer open bins -> prefer existing bins
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest future
    // item (min size 1, but practically items < 10 are rare) are dead space.
    // Penalize small non-zero post_residuals super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += 8.0 * tightness;

    // Perfect fit bonus: exact fill.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or
        // mean residual is still large (capacity to absorb items).
        score += 12.0 + 3.0 * pressure + 10.0 * (mean_residual / 100.0) + 15.0 * progress;
    } else {
        // Existing bin: reward slightly more when pressure is high.
        score -= 2.0 * pressure.min(10.0);
    }

    // Lookahead coupling: if the next item fits into the post_residual,
    // reward this placement (keeps chains going).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual that cannot host the next item is likely dead space.
        score += 6.0;
    }

    // Align with mean residual: bins whose post-residual is close to the mean
    // keep the pool of usable bins homogeneous.
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= next {
            // Perfect 2-step fill: post_residual equals next item size
            let gap = (pr - next).abs();
            if gap < 1.0 {
                score -= 60.0;
            } else {
                // Closer match gets more reward
                score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else if pr == 0.0 {
            // Bin exactly filled: perfect, no dead space
            score -= 50.0;
        } else {
            // Next item cannot fit: penalize dead space proportionally
            score += 15.0 * (pr / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual: leaving residuals near the mean
    // preserves flexibility across the fleet of open bins
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.25 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when decent fitting bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        score += 30.0 + 10.0 * progress + 5.0 * pressure.min(10.0);
        // Still allow new bin if this item is huge and nothing fits well
        if item_size as f64 > 0.8 * bin_capacity as f64 && fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for tighter fits overall
    score += 0.1 * (bin_residual - item_size) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize large dead space quadratically (unusable slivers).
    if post_residual < 10 {
        score -= 8.0; // perfect or near-perfect closure
    } else if post_residual < 20 {
        score -= 3.0;
    } else {
        score += 0.05 * (post_residual as f64 - 10.0);
    }

    // Last-chance bin: if this is the only bin that fits, use it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item could fit into this bin's post-residual,
    // reward the placement (keeps a useful cavity for the known successor).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else if next_item_size >= bin_residual {
            // Next item won't fit here anyway; slight penalty for wasting a large residual.
            score += 1.5;
        }
        // If next item fits post-residual almost exactly, big bonus.
        let gap = post_residual as i64 - next_item_size as i64;
        if gap >= 0 && gap < 8 {
            score -= 5.0;
        }
    }

    // Global pressure: many open bins with large mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual > 25.0 {
        score -= 2.0 * (mean_residual / 100.0) * (1.0 - progress);
    }

    // New-bin candidate handling: an empty bin should only win when existing bins fit badly.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin loses against any decent fit.
        score += 5.0;
        // But if no open bin fits well (this item barely fits anywhere), opening is fine.
        if fitting_bins_count == 0 {
            score -= 10.0;
        } else if fitting_bins_count == 1 {
            // Only one fitting bin and it's not a tight fit -> new bin becomes attractive.
            let worst_fit = fit_ratio < 0.7;
            if worst_fit && item_size >= 50 {
                score -= 4.0;
            }
        }
        // Late in the stream, prefer closing out existing bins.
        if progress > 0.8 {
            score += 3.0 * progress;
        }
    }

    // Mild preference for fuller bins overall (best-fit flavor with exploration).
    score -= 0.02 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: post residual, with non-linear polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.5 * progress * (1.0 - x)) + 30.0 * x * x * (1.0 - progress);

    // Penalize large dead space smoothly; reward tight fits more as stream progresses.
    score += 20.0 * x.powi(3) * (0.5 + progress);

    // Last-chance bonus: strong discount if this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 40.0 * progress;
    } else {
        // Mild penalty spread across many fitting bins.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward if next item fits the resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - snug) * (0.4 + 0.6 * progress);
        } else {
            score += 8.0 * ((nxt - pr) / cap);
        }
    }

    // Slight preference to fill bins when many are open (bin consolidation).
    score -= (open_bins_count as f64).ln() * (1.0 - x) * 3.0;

    // Nudge toward bins below mean residual (denser bins) with smooth coupling.
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: near-perfect fill (post_residual in {0,1,2,3}) -> strong reward
    if post_residual <= 3 {
        score -= 45.0;
    }
    // Class B: post_residual divisible by 8 (harmonic slot, many small items fit)
    else if post_residual % 8 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    // Class C: dead zone 4..=12 -> unusable sliver, heavy penalty
    else if post_residual < 13 {
        score += 18.0;
    }
    // Class D: post_residual divisible by 5 (mid harmonic class)
    else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Integer-division threshold classes on post_residual (quarters of capacity)
    let quarter = (post_residual / 25) as f64;
    score -= quarter * 4.0; // prefer bins leaving larger usable chunks among non-tight fits

    // Next-item lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual && (post_residual - next_item_size) <= 3 {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // next item cannot use this residual; penalize proportionally to wasted potential
            score += (next_item_size as f64 - pr).min(30.0) * 0.4;
        }
        // harmonic match: next item is a divisor-like chunk of residual
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a new bin
        score += 20.0;
        // if current item leaves a bad residual in ANY bin anyway, new bin is fine
        if item_size <= 30 {
            score -= 15.0; // small items: fresh bin keeps flexibility
        }
        // if many bins are open with high mean residual, prefer packing into them
        if open_bins_count > 0 {
            score += (mean_residual / cap) * 25.0;
        }
        // early stream: opening bins is cheaper (builds pool)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // if no bin can take a follow-up item of next size well, new bin helps
        if next_item_size > 40 {
            score -= 8.0;
        }
    } else {
        // reward filling existing bins deeper (tighter fits)
        let fill = 1.0 - (bin_residual as f64) / cap;
        score -= fill * 8.0;
    }

    // Coupling: large item into nearly-full bin is excellent (small post_residual)
    if item_size >= 50 && post_residual <= 20 {
        score -= 10.0;
    }

    // Mild penalty proportional to open bins count to discourage bin sprawl
    score += (open_bins_count as f64).sqrt() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // typical future items are heavily penalized (unusable gap).
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual as f64) * 6.0;
    }

    // Sweet-spot reward: leaving a residual that exactly fits the lookahead item
    // is excellent packing (chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // partial credit: gap remains usable by the next item
        score -= 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer tightening existing bins
    // rather than spreading; add pressure proportional to open bins count.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when the item would leave a
    // large usable residual there anyway, and when bin pressure is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_bonus = 20.0
            - (open_bins_count as f64) * 2.0
            - progress * 10.0
            + mean_residual * 0.15;
        score -= new_bin_bonus.max(-30.0).min(30.0);
        // penalize new bin if item is small (wasteful)
        if item_size < 40 {
            score += (40 - item_size) as f64 * 0.8;
        }
    }

    // Mild preference for bins tighter than average (good fits).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
