pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;

    // Core: quadratic waste penalty, smoothed by stream progress
    let mut score = post * post / cap;

    // Tight-fit bonus (small post_residual relative to item)
    score -= (item - post).max(0.0) * (1.0 + progress);

    // Lookahead: reward residuals that can host the next item exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = post - nxt;
            score -= 8.0 * (1.0 - slack / cap) * (1.0 - progress);
        } else {
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 15.0 * progress;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits
    let is_new = (bin_residual as u32 == bin_capacity) && bin_capacity > 0;
    if is_new {
        score = cap * 1.5 + mean_residual * (1.0 + progress) - item * 0.5;
        if fitting_bins_count == 0 {
            score = cap * 0.2;
        }
    } else {
        // Penalize bins far from mean residual (fragmentation)
        let dev = (res - mean_residual).abs() / cap;
        score += 4.0 * dev * dev * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of 10, small leftovers) are better targets.
    let class = post_residual / 10;
    match class {
        0 => score -= 25.0,                     // near-perfect fit
        1 => score -= 12.0,                     // leftover 10..19 (very reusable)
        2 => score -= 6.0,                      // leftover 20..29
        3 => score -= 2.0,
        4 | 5 => score += 3.0,                  // mid leftovers: dead-ish space
        6 | 7 => score += 8.0,
        _ => score += 15.0,                     // huge leftover: wasted capacity
    }

    // Exact harmonic bonus: post_residual that is a multiple of common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual > 0 && (post_residual % 20 == 0) {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size).min(15) as f64 * 0.8;
        } else {
            // next item won't fit here; penalize small leftovers that become dead space
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: keep it attractive only when current bins fit badly.
    if bin_residual == bin_capacity {
        // neutral-ish baseline: cost of a fresh bin
        score = 45.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0; // big next item may prefer a fresh bin
        }
    }

    // Stream progression: later in the stream, tighten up (avoid sprawl).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0;

    // Mild penalty proportional to mean residual (prefer bins below-average leftover,
    // i.e., tighter bins get relatively lower scores).
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * post_residual as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: dead space likely.
        score += 8.0;
    }

    // Last-chance bin: prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when current bins are nearly full on average.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let mean_fit = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 30.0 + 25.0 * mean_fit + 2.0 * open_f;
        if fitting_bins_count == 1 {
            score += 50.0; // never open a new bin when it's the last chance
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items into fresh bins is fine
        }
    }

    // Mild preference for bins whose residual is close to the item (tight fit).
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this placement sets up a perfect chain.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size && (post_residual - next_item_size) <= 10 {
            score -= 120.0;
        } else if post_residual < next_item_size {
            // Dead space the next item cannot use: penalize proportionally.
            score += 1.5 * (next_item_size - post_residual) as f64;
        }
        // If next item is huge, prefer leaving space in larger-residual bins.
        if next_item_size >= 60 && post_residual >= next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: reward filling as much as possible.
        score -= 50.0;
    }

    // Prefer bins whose residual is tighter than the mean (best-fit flavor).
    score += 0.8 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 80.0;
        // Opening a new bin is more acceptable early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 60.0 * (1.0 - progress);
    }

    // Mild penalty for accumulating many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: heavily reward tight fits.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how well it uses the leftover.
            let next_use = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * next_use;
        } else {
            // Next item cannot use the leftover: penalize leaving large dead space.
            score += (post_residual as f64) * 0.25;
        }
    } else {
        // Last item: prefer perfect closure of bins.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that can fit, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; shrinks if existing residuals are fragmented.
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 30.0 + item_size as f64 * 0.3;
        // If item is large, a fresh bin is more attractive (large items leave small residuals anyway).
        if item_size >= 60 {
            new_bin_score -= 25.0;
        }
        // If existing bins are highly fragmented (mean residual small), new bin penalty decreases.
        new_bin_score -= fragmentation * 20.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        new_bin_score -= (1.0 - progress) * 15.0;
        // If many bins already open, discourage proliferation.
        new_bin_score += open_bins_count as f64 * 2.0;
        score = score.max(new_bin_score.min(200.0));
        score = new_bin_score;
    } else {
        // Placing into an existing bin: slight preference for bins below mean residual
        // (concentrate space into fewer, larger leftovers).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Global waste pressure: as the stream progresses, punish sloppy placements harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.6;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear penalty on tiny dead space
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: post-residual value interacts with stream progress
    score += 0.5 * norm_pr * t * (1.0 - t) * 4.0;

    // Reward residual that matches the next item (smooth kernel around perfect fit)
    if next_item_size > 0 {
        let gap = (pr - nxt) / cap;
        score -= 0.6 * (-gap * gap * 40.0).exp();
    }

    // Penalize wasting a scarce fitting opportunity
    if fitting_bins_count == 1 {
        score -= 1.2;
    } else {
        score += 0.15 * (fitting_bins_count as f64).ln();
    }

    // Pull toward mean residual state: bins deviating from mean get smoothed preference
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // Mild preference for tighter packing early, opening bins later
    score -= 0.2 * item * (1.0 - t);

    // Slight bias against opening new bins when many already open
    score += 0.05 * (open_bins_count as f64).sqrt() * (1.0 - t);

    // Prefer filling bins more completely as stream progresses
    score -= 0.4 * (1.0 - norm_pr) * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Fractional capacity classes: harmonic reward for near-full packing
    let fill = (bin_capacity - post_residual) as f64 / cap; // fraction used after placement
    let fill_class = (fill * 4.0).floor() / 4.0; // quarter-capacity classes
    score -= 18.0 * fill_class;

    // Exact-fill / tiny-dead-space bonus via integer division classes
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Modulo arithmetic on post_residual: dead space divisible by small sizes is reusable
    let pr = post_residual;
    if pr > 0 {
        let reusable = (pr % 10 == 0) as i32 as f64 * 6.0
            + (pr % 5 == 0) as i32 as f64 * 3.0
            + (pr % 20 == 0) as i32 as f64 * 4.0;
        score -= reusable;
    }

    // Lookahead coupling: penalize if post_residual can't host next item but barely misses it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // chain-friendly bin
        } else if next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 8.0; // just misses the chain: dead space trap
        }
        // harmonic class of next item vs remaining space
        let next_class = (next_item_size as f64 / cap * 4.0).floor();
        let resid_class = (post_residual as f64 / cap * 4.0).floor();
        if resid_class >= next_class {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer fresh bin when current bin would waste a lot
    if bin_residual == bin_capacity {
        // baseline for empty bin: neutral-ish score
        score = cap * 0.55;
        if next_item_size > 0 && next_item_size <= item_size.saturating_mul(2).min(bin_capacity) {
            score -= 6.0;
        }
        if open_bins_count == 0 {
            score -= 40.0; // must open first bin
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Mean-residual coupling: when open bins are roomy on average, be pickier about waste
    if bin_residual < bin_capacity {
        score += 0.25 * (mean_residual - post_residual as f64).max(0.0);
    }

    // Mild preference to fill bins in order of tightness when many fit
    if fitting_bins_count > 2 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest possible item are pure loss.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Tight fit reward: near-perfect packing.
    if post_residual <= 2 {
        score -= 25.0;
    }

    // Penalize residual gaps that cannot serve the lookahead item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size as f64 {
            score += 15.0;
        }
        // Reward bins whose post_residual exactly accommodates the next item.
        if post_residual as f64 == next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // or all fits would leave bad dead space.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score -= 10.0 + 30.0 * fill_frac;
        if post_residual > 0 && post_residual < 10 {
            score += 80.0; // opening a bin for a near-full item is fine; but tiny dead space penalty offset
        }
    }

    // Mild residual homogenization: prefer bins near the mean residual (balanced loads).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late-stream tightening: as the stream progresses, be stricter about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
