    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this placement sets up a perfect follow-up; reward it heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64).ln().max(0.0) / (1.0 + (post_residual as f64 - next_item_size as f64)).ln();
        } else {
            // Next item won't fit here anyway; mild penalty for wasting space.
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Time horizon: late in the stream, prefer closing bins (avoid opening new ones).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize increasingly as stream progresses,
        // but less when open bins are fragmented (high mean residual).
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 40.0 + 60.0 * progress - 20.0 * fragmentation;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    } else {
        // Existing bin: mild bonus when its residual is below mean (already committed).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
        // Prefer filling more-fragmented bins early to consolidate open bins.
        score -= 0.15 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Small penalty for proliferating bins when many are open.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 18.0 * poly;

    // Tight fits rewarded more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // Penalize wasting a nearly-full bin on a small item
    let fill = item_size as f64 / bin_residual as f64;
    if fill < 0.35 {
        score += 15.0 * (0.35 - fill) * (1.0 + progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / cap);
    }

    // Prefer bins below mean residual (consolidate larger holes)
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 4.0 * (mean_residual - res_f) / cap;
    } else {
        score += 4.0 * (res_f - mean_residual) / cap;
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 0.15 * open_bins_count as f64;
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
            score += 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bucket by capacity fractions.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class: u32 = if post_residual == 0 {
        0 // perfect fit class
    } else if post_residual <= eighth {
        1 // tiny dead space
    } else if post_residual <= quarter {
        2
    } else if post_residual <= 2 * quarter {
        3
    } else {
        4 // mostly empty
    };

    match post_class {
        0 => { score -= 40.0; }                 // perfect fit: strong reward
        1 => { score -= 12.0; }                 // near-perfect fit
        2 => { score += 6.0; }                  // awkward leftover
        3 => { score += 3.0; }                  // half-full leftover
        _ => { score += 10.0; }                 // wasting a nearly empty bin
    }

    // Modulo-arithmetic compatibility: does the leftover pair well with the next item?
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 30.0; // next item makes a perfect fit here
        } else if gap > 0 && (gap as u32) <= eighth {
            score -= 15.0; // next item leaves a tiny residue again
        } else if gap > 0 && gap < 0 {
            score += 0.0;
        } else if gap < 0 {
            // next item cannot fit here; leftover's class determines penalty
            score += match post_residual % 10 {
                0 => 2.0,
                _ => 5.0,
            };
        }
        // Harmonic divisibility: leftover divisible by common small sizes is reusable
        if post_residual > 0 {
            if post_residual % 20 == 0 { score -= 6.0; }
            else if post_residual % 10 == 0 { score -= 3.0; }
            else if post_residual % 5 == 0 { score -= 1.5; }
        }
    } else {
        // last item: prefer tightest fit, no lookahead concerns
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // bins are crowded or the item is large and fits nowhere comfortably.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // penalty for opening new bin, reduced late in stream or when bins are full
        score += 55.0 - 25.0 * progress;
        if mean_residual < 15.0 { score -= 20.0; }
        if open_bins_count == 0 { score -= 100.0; }
    } else {
        // slight preference for tighter existing bins
        score += (bin_residual as f64 / bin_capacity as f64) * 4.0;
        // favor bins below mean residual (relatively emptier -> consolidate)
        if (bin_residual as f64) > mean_residual { score += 3.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 120.0;
    }

    // Reward tight fits relative to the item size.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent.
    score += 0.8 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward leaving that gap.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Gap that the next item cannot use: mild penalty scaled by stream progress.
        score += 10.0 + 15.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // New-bin candidate: only attractive when open bins are nearly full on average
    // or the item cannot fit well anywhere.
    if bin_residual == bin_capacity {
        let new_bin_base = 25.0 + 0.5 * open_bins_count as f64;
        let mean_pressure = mean_residual / bin_capacity as f64;
        score = new_bin_base + 40.0 * mean_pressure;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward proportional to how close post_residual is to next_item_size
        score -= 30.0 * (1.0 - diff / (next_item_size as f64 + 1.0)).max(0.0);
        // Perfect 2-step match: big bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // If next item cannot fit here anyway, slight penalty for tight leftover
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    } else {
        // Last item: prefer minimal waste
        score += 10.0 * post_residual as f64;
    }

    // Penalize bins whose residual deviates strongly from mean residual (avoid fragmentation)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline, penalize mildly so we prefer reusing well
    if bin_residual == bin_capacity {
        score += 15.0;
        // Open a new bin if no open bin offers a good 2-step match
        if next_item_size > 0 && post_residual == 0 {
            score -= 20.0;
        }
    }

    // Slight preference for tighter fits overall
    score += 0.05 * (bin_residual - item_size) as f64;

    // Progress-aware scaling: be greedier early, more conservative late
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post residual and apply superlinear penalty
    let tight = (post_residual as f64) / cap;
    score += 30.0 * tight * tight;

    // Lookahead: reward bins whose post-residual can still host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 8.0 + 10.0 * (1.0 - (nxt / cap));
        } else {
            // dead space for next item: penalize proportionally to wasted gap
            let gap = nxt - post_residual as f64;
            score += 0.25 * gap;
        }
    }

    // Last-chance bonus: only bin that fits; strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize placing small items into large-residual bins (save space for big items)
    let frac = item_size as f64 / cap;
    if frac < 0.4 && bin_residual > bin_capacity / 2 && bin_residual < bin_capacity {
        score += 12.0 * (1.0 - frac);
    }

    // Time horizon: early in stream, be more conservative (favor new bins less);
    // late in stream, consolidate into open bins
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * t * (mean_residual / cap);

    // New-bin candidate: make it costly unless residuals across open bins are all poor
    if bin_residual == bin_capacity {
        let avg_tight = mean_residual / cap;
        // open new bin only if mean residual is small (open bins nearly full)
        score = 60.0 - 40.0 * (1.0 - avg_tight.min(1.0)) + 20.0 * (1.0 - t);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    // Slight penalty for proliferating bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;
    // normalized post residual, smooth polynomial coupling with stream progress
    let r = pr / cap;
    // reward tight fits (small post_residual) more strongly as stream progresses
    score -= 30.0 * (1.0 - r) * (1.0 - r) * (0.5 + t);
    // penalize large residuals non-linearly, growing with progress
    score += 25.0 * r * r * r * (0.5 + t);
    // dead-space penalty: residual too small to be useful for typical items
    let dead = (pr as f64 / cap).powi(2);
    score += 15.0 * dead * (1.0 - t);
    // lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 / cap);
    }
    // last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (item_size as f64 / cap);
    }
    // mild pressure against proliferating bins when mean residual is high
    score += (open_bins_count as f64).ln() * mean_residual / cap * 2.0;
    // new-bin candidate: keep it available early, discourage late unless residual huge
    if bin_residual == bin_capacity {
        score += 8.0 * t * (1.0 - r);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual;
    let mut score = pr as f64;

    // Harmonic class of post_residual: dead space gets progressively worse
    // in discrete bands (0, (0,10], (10,20], (20,34], (34,50], (50,100]).
    let class = if pr == 0 { 0.0 }
        else if pr <= 10 { 1.0 }
        else if pr <= 20 { 2.0 }
        else if pr <= 34 { 3.0 }
        else if pr <= 50 { 4.0 }
        else { 5.0 };
    score += class * 4.0;

    // Reward near-exact packing.
    if pr == 0 {
        score -= 30.0;
    } else if pr <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: does the next item fit into the leftover space?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0; // chainable bin: keep using it
        } else {
            score += 3.0; // leftover likely wasted
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Congestion-aware tweak: with many open bins, prefer consolidating.
    score -= (open_bins_count as f64).sqrt() * 1.5;

    // New-bin candidate: base penalty so it is chosen only when open bins
    // would create large dead space (class >= 4) or none fit well.
    if bin_residual == bin_capacity {
        score = 40.0 + mean_residual * 0.25 - (open_bins_count as f64).sqrt() * 2.0;
        // Early stream: opening bins is cheap and useful for future flexibility.
        if progress < 0.15 {
            score -= 10.0;
        }
        // If the current item is large, a fresh bin is often the best host.
        if item_size > 60 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // hard penalty for creating a sub-minimum-size gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward closing the bin
    }

    // Penalize moderately small gaps that only fit very small items
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // exact lookahead match is a great outcome
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover can't serve the next item: mild extra penalty scaled by tightness
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only preferred when
    // no open bin gives a decent fit. Make the empty-bin baseline high but
    // beatable by good fits; it gets worse as open bins proliferate.
    if bin_residual == bin_capacity {
        score = 45.0 + 3.0 * open_bins_count as f64 + mean_residual * 0.2;
    }

    // Mean residual coupling: prefer bins whose residual deviates low
    // (tighter bins) when mean residual is high.
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Slight late-stream tightening: keep bins closed as stream matures
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Two-step lookahead: reward bins where the next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item fill
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 * (slack_after_next as f64 / bin_capacity as f64);
            if slack_after_next < 10 {
                score -= 15.0; // nearly perfect chain fill
            }
        } else {
            // next item won't fit here; penalize proportionally to the overshoot
            let overshoot = next_item_size - post_residual;
            score += 0.35 * overshoot as f64;
        }
    } else {
        // Last item: strongly prefer minimal final residual
        score += 0.5 * post_residual as f64;
    }

    // Prefer bins whose residual is below mean residual (tighter packing)
    score += 0.30 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline, mildly discouraged unless lookahead is bad
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && next_item_size == item_size {
            score += 8.0; // opening fresh bin fine if identical items will pair
        }
    }

    // Progression: be slightly more conservative (tighter fits) later in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Discourage spreading across many open bins when a tight fit exists
    if open_bins_count > 4 && post_residual < 15 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of capacity consumed by this placement
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: post_residual small relative to capacity.
    // Non-linear: quadratic penalty on wasted space, stronger late in the stream.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * (40.0 + 60.0 * progress);

    // Reward high fill ratio of the item itself.
    score -= fill * 25.0;

    // Perfect fit bonus: nothing left after placement.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Nearly-dead space is fine — it's unusable anyway for items >=10... but sizes go down to 1,
        // so scale the "dead space" threshold by remaining stream length.
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly into the resulting residual, big reward.
    if next_item_size > 0 {
        let nd = next_item_size as i64 - post_residual as i64;
        if nd == 0 {
            score -= 60.0;
        } else if nd > 0 {
            // Next item would NOT fit here: residual is dead weight for the horizon.
            score += (nd as f64 / bin_capacity as f64) * 30.0 * (0.5 + progress);
        } else {
            // Next item fits too: chain placement reward proportional to snugness.
            score -= 20.0 * (1.0 - (-nd as f64) / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0 + 25.0 * progress;
    }

    // Many open bins: prefer consolidating into existing bins rather than opening more.
    let openness = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += openness * 12.0;

    // New-bin candidate handling: penalize opening a new bin when the item could
    // reasonably fit somewhere with a decent fit; reward it when all fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: capacity-sized potential.
        score = bin_capacity as f64 * 0.9;
        // Early in the stream, opening bins is cheap (room to grow later).
        score -= 30.0 * (1.0 - progress);
        // If no existing bin fits, opening is mandatory-ish: reduce cost.
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            // Only one fitting bin — using it is usually better than a new bin.
            score += 20.0;
        }
        // If mean residual across open bins is small, existing bins are crowded:
        // a new bin becomes more attractive.
        if mean_residual < item_size as f64 * 1.5 {
            score -= 15.0;
        }
        // Lookahead: a fresh bin can host both this and the next item.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 25.0;
        }
    }

    // Coupling with global mean residual: prefer bins whose residual is below average
    // (tighter bins) when placing, to keep large residuals available for large items.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress = progress.clamp(0.0, 1.0);

    // Smooth polynomial coupling: post_residual normalized by capacity, warped by progress.
    let r = post_residual as f64 / bin_capacity as f64;
    let warp = 0.5 + 2.0 * progress * (1.0 - progress); // peaks mid-stream, smooth
    score += 40.0 * r * r * (1.0 + warp) - 25.0 * r * warp;

    // Penalize large dead space quadratically, more so late in the stream
    score += (post_residual as f64).powi(3) / (bin_capacity as f64 * bin_capacity as f64) * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth exponential bonus
    score -= 30.0 * (-post_residual as f64 / 15.0).exp();

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 8.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        // Slight penalty if the leftover can't host the next item
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Prefer the fullest fitting bin: compare residual against mean residual
        score += (mean_residual - bin_residual as f64) * 0.35;
    }

    // New-bin candidate: penalize opening a new bin, softly early and hard late
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 55.0 + 60.0 * progress + 5.0 * open_bins_count as f64;
        // But allow opening if the item is huge and few bins exist
        if item_size as f64 > 0.75 * bin_capacity as f64 && open_bins_count < 3 {
            score -= 70.0;
        }
    }

    // Mild global pressure to consolidate into fewer bins
    score += open_bins_count as f64 * 1.5;

    // Small smooth tie-breaker based on fill ratio
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction slot it lands in.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Integer-division thresholds: post_residual classes (dead space classes).
    let dead_class = post_residual / 10; // 0..10 harmonic slots
    // Penalize residuals that fall into "unusable" classes (too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space: nothing can ever fit
    }

    // Perfect fit reward: harmonic class 0
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residuals in classes that can host common item sizes (multiples of 10 style packing)
    // A residual is "harmonic" if it is divisible by common item classes (10, 20, 25, 50)
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    if post_residual % 50 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does the post residual still admit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Great: this bin can also host the next item; reward proportional to leftover
            score -= 12.0;
            let next_left = post_residual - next_item_size;
            if next_left % 10 == 0 {
                score -= 6.0; // double harmonic chain
            }
            if next_left == 0 {
                score -= 25.0; // chain of two perfect fits
            }
        } else if next_item_size > bin_capacity {
            // next item cannot fit anywhere; ignore
        } else {
            // next item will need another bin; mild penalty for wasting this residual
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity; make it costly
    // unless the current item is huge and no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: full residual is "wasted potential" but flexible.
        // Keep it moderately high so existing bins with decent fit win.
        score += 20.0;
        // If item is large (harmonic class >= 5 of 10), a fresh bin is more attractive.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        // If many bins are open and mean residual is small, opening fresh is fine.
        if open_bins_count > 3 && mean_residual < item_size as f64 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Prefer filling bins with small residuals (tight packing pressure)
    let tightness = 1.0 - frac;
    score -= 5.0 * tightness;

    // Nonlinear coupling: quadratic penalty on mid-range dead space
    if post_residual > 0 {
        let f = frac;
        score += 10.0 * f * (1.0 - f) * (f < 0.3 || f > 0.9) as i32 as f64;
    }

    // Mean residual steering: if this bin's residual is far below mean, filling it
    // harmonizes the residual distribution.
    let diff = mean_residual - post_residual as f64;
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item (<= 12) are essentially wasted capacity.
    if post_residual <= 12 {
        // Perfect or near-perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual <= 20 {
        // Small dead-space zone: penalize proportionally.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward leaving a gap that can exactly host the lookahead item (k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let gap_diff = post_residual - next_item_size;
        if gap_diff <= 5 {
            score -= 25.0;
        } else {
            score += gap_diff as f64 * 0.3;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual cannot host the next item: mild dead-space penalty.
        score += 8.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many
    // bins are open, to avoid bin proliferation.
    score += open_bins_count as f64 * 0.4;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: if this bin is much tighter than average,
    // using it preserves slack elsewhere.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.25;

    // New-bin candidate: make it unattractive unless it is the only option.
    // Base penalty plus a term that shrinks as the stream progresses
    // (early on, keeping bins tight matters less than avoiding sprawl).
    if bin_residual == bin_capacity {
        score += 60.0 - (step_index as f64 / total_items.max(1) as f64) * 15.0;
        // If no open bin fits, the new bin must win: remove the penalty.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
