pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect / near-perfect closure bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Penalize leaving dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Exact chain fit: post_residual == next_item_size closes the bin next step.
            if post_residual == next_item_size {
                score -= 18.0;
            }
        } else {
            // Post-residual too small for the next item: mild penalty scaled by waste.
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    } else {
        // Last item in stream: just minimize waste.
        score -= 5.0;
    }

    // Global state: many open bins with slack -> prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress * 0.5);
    }

    // Mean residual coupling: if this bin is tighter than average, favor it.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate handling: only attractive when no good existing fit exists.
    if bin_residual == bin_capacity {
        // Base penalty to prefer existing bins; reduced when many open bins are fragmented.
        score += 35.0;
        score -= 0.2 * mean_residual.max(0.0);
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits, new bin is fine
        }
        // Late in stream, opening bins is cheap since leftovers go unused anyway.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: late in the stream, residual waste matters more
    let progress_weight = 1.0 + 1.5 * progress * progress;
    score *= progress_weight;

    // Penalize post-residuals that are unusable relative to next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 20.0 * gap * gap;
        // Reward exact-ish fit for the lookahead item
        let fit_quality = 1.0 - (pr - nx).abs() / cap;
        score -= 6.0 * fit_quality.max(0.0) * fit_quality;
    } else {
        // Last item: strongly minimize waste
        score += 2.0 * pr;
    }

    // Last-chance bin bonus: only bin that fits -> smooth reward
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Prefer bins with residual far from mean when mean is high (avoid clustering waste)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * mean_residual / cap;

    // Mild penalty for spreading across many open bins late in stream
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: neutral-ish baseline with slight conservatism
    if bin_residual == bin_capacity {
        score = 0.55 * cap + 10.0 * progress - 8.0 * (item_size as f64 / cap);
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 4.0;
        }
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: buckets of 10 (capacity fractions).
    let post_class = post_residual / 10;
    let item_class = item_size / 10;
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / 10 };

    // Reward (subtract) when post_residual belongs to "useful" residue classes
    // that typical small items (10..30) can still fill.
    match post_class {
        0 => score -= 25.0,            // perfect fit — best possible outcome
        1 => score -= 18.0,            // next 10..20 item fits
        2 => score -= 12.0,            // next 20..30 item fits
        3 => score -= 7.0,             // next 30..40 item fits
        4 => score -= 3.0,             // moderate residue
        5 => score -= 0.0,
        _ => score += 4.0,             // large dead space — penalize
    }

    // Coupling: strongly reward exact lookahead match into the residual class.
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: reward proportional to how tightly it nests
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack * 0.15;
        // harmonic bonus if next item's class exactly matches residual class
        if next_class == post_class {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // lookahead item cannot use this residue — mild penalty scaled by gap
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.05;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless it would create large dead space.
    if fitting_bins_count == 1 {
        score -= 20.0;
        if post_class >= 5 {
            score += 10.0; // but not if it wastes half a bin
        }
    }

    // Exact-fit harmonic term via modulo: residues divisible by 10 are "clean".
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Odd leftover residues (not multiple of 5) are harder to fill later.
    if post_residual % 5 != 0 {
        score += 2.0;
    }

    // Prefer tighter bins when many bins are open (consolidation pressure).
    let tightness = (bin_residual as f64) / (bin_capacity as f64);
    score -= tightness * (open_bins_count as f64).ln().max(1.0) * 3.0;

    // Early in the stream, allow opening new bins more freely; late in the
    // stream, pack harder into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it more as the stream progresses,
        // unless current bin fits are all poor (large post_residual).
        score += 15.0 + 25.0 * progress;
        if mean_residual < 20.0 {
            score -= 12.0; // all open bins are tight -> new bin is fine
        }
    } else {
        score -= 5.0 * progress; // reward using open bins later in stream
    }

    // Mean-residual alignment: bins far below mean residual are "loose";
    // prefer filling bins whose residual is close to the item (tight fit).
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    score -= fit_ratio * 8.0;

    // Small tie-breaker on residual to keep deterministic preference for
    // fullest bins.
    score += (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 9.0; // gaps below smallest plausible item are dead
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear penalty for mid-range residuals that few items can use.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64).max(0.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading into many bins unless fit is great.
    score += 3.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (concentrate usage in fuller bins).
    score += 2.0 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: make empty bin attractive only when no
    // open bin offers a decent fit, otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            score += 35.0 + 2.0 * open_bins_count as f64; // prefer reusing bins
        }
    }

    // Late-stream consolidation: as stream progresses, tighten bins more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward closeness of post_residual to next_item_size (soft matching).
        score -= 30.0 * (-gap / 15.0).exp();
    }

    // Penalize dead space that no plausible item (>= 1) can use later in this bin:
    // small nonzero post_residual that doesn't match next item is wasteful.
    if post_residual > 0 && post_residual < 10 && !(next_item_size > 0 && post_residual == next_item_size) {
        score += 25.0;
    }

    // Compare post_residual against mean residual: leaving more than average
    // residual keeps the bin flexible; leaving far less may trap the bin.
    if post_residual as f64 >= mean_residual {
        score -= (post_residual as f64 - mean_residual).min(20.0) * 0.5;
    } else {
        score += (mean_residual - post_residual as f64).min(20.0) * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Early in the stream, encourage tight packing; late, prefer reusing bins
    // to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference to fill already-open bins rather than spawn new ones.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: discount proportional to fill fraction.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 3.0 * fill * post_residual as f64;

    // Penalize small unusable residuals (dead space below min plausible next size).
    if post_residual > 0 && post_residual < 12 {
        score += 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // residual too small for next item: penalize proportionally to wasted potential
            score += 2.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is attractive when open bins
    // have large residuals but the item fits none well, or when bin count is low.
    if bin_residual == bin_capacity {
        // Baseline attractiveness of a fresh bin grows with mean residual of open bins.
        score = 100.0 - 0.3 * mean_residual;
        if open_bins_count == 0 {
            score -= 50.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0; // big next item: fresh bin preserves large contiguous space
        }
    }

    // Time horizon: late in the stream, avoid opening new bins (waste at end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 3.0 * progress; // late stream: fill existing bins aggressively
    }

    // Prefer bins with residual close to item size (best-fit flavor).
    let gap = (bin_residual - item_size) as f64;
    score += 0.1 * gap;

    // Mild penalty for spreading across many open bins when residuals are large.
    if mean_residual > 40.0 && bin_residual < bin_capacity {
        score -= 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

