    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling: penalize residual more strongly as stream progresses
    let poly = norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress);
    score += 3.0 * poly;

    // Reward tight fits (small post_residual) with a smooth exponential-like term
    score -= 8.0 * (-norm_pr * 6.0).exp();

