    score -= progress * (1.0 - norm_pr) * 4.0;

    // Last-chance bin: strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving residual that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt && pr > 0.0 {
            score += 5.0 * (1.0 - pr / nxt);
        } else if pr >= nxt {
            score -= 2.0 * (nxt / cap);
        }
    }

    // Slight penalty for spreading across many open bins when residuals are large
    score += 0.05 * open_bins_count as f64 * mean_residual / cap;

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 12.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
