    // (dead-space classes). Small residuals are ideal (tight fit), large ones bad.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class penalty: quadratic in capacity fraction
    score += 40.0 * frac * frac;

    // Harmonic "perfect fit" classes: residual in {0, 5..10, 15..20, ...} are
    // commonly re-fillable by small items; reward divisible-by-10 residuals.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly
    // or with minimal waste.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - next_waste / cap);
            if next_item_size == post_residual {
                score -= 10.0; // chain of perfect fits
            }
        } else {
            // Next item won't fit here: penalize mildly unless this bin is nearly full
            score += 3.0 * (1.0 - (item_size as f64) / cap);
        }
    } else {
        // Last item: prefer any fit, penalize opening new bins heavily
        if bin_residual == bin_capacity {
            score += 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a new bin wastes bin_residual worth of space.
    if bin_residual == bin_capacity {
        // Attractive early when many bins open / mean residual is low;
        // discouraged when item is small (wastes capacity).
        score = (item_size as f64) * 0.5 + (open_bins_count as f64) * 0.3;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress; // later in stream, prefer consolidating
        if fitting_bins_count > 0 {
            score += 5.0; // some open bin fits: new bin less attractive
        }
        if item_size >= 60 {
            score -= 8.0; // big items justify fresh bins
        }
    }

    // Mild tie-break toward fuller bins via mean residual deviation
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 2.0 * (mean_residual - bin_residual as f64) / cap; // fuller-than-average rewarded

    // Integer-division threshold: residual class < item/2 means half-dead space
    if post_residual > 0 && post_residual < item_size / 2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual is "dead" if it is too small for the smallest plausible item (1),
    // but practically: residual < next_item_size and residual < some threshold.
    if post_residual > 0 {
        let next = next_item_size as f64;
        if next > 0.0 && (post_residual as f64) < next {
            // Gap cannot fit the lookahead item: harsh penalty proportional to gap.
            score += 40.0 + 0.5 * (post_residual as f64);
        }
        // Small unusable gaps below a floor threshold are dead space.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits: post_residual small relative to item size.
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (item_size as f64);
        score -= 15.0 * tightness;
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so it gets penalized).
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * (open_bins_count as f64);
        // But if mean residual across open bins is large, opening a new bin is fine.
        if mean_residual > 50.0 {
            score -= 25.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Stream progression: late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (small post_residual).
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // 2-step lookahead: reward if next item exactly fills the leftover space.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 50.0;
        } else if gap <= 3 {
            score -= 25.0;
        } else if gap <= 8 {
            score -= 10.0;
        }
        // Penalize leftover space that no plausible item can use.
        if post_residual < 10 && gap > 0 {
            score += 8.0;
        }
        // Penalize if next item would be forced to open a new bin anyway.
        if next_item_size > post_residual && post_residual < 10 {
            score += 6.0;
        }
    }

    // Compare against mean residual: prefer bins that stay near the mean,
    // penalize creating outliers.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev.abs();

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Late in stream: tighten packing, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let fit_tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_tightness;

    // Penalize leaving dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill bonus
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0; // moderately awkward gap
    } else if post_residual >= 50 {
        score += 10.0; // large gap: bin was barely used
    }

    // Lookahead: strongly reward if the next item fits exactly/ snugly in the leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_tightness = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * lookahead_tightness;
        if post_residual == next_item_size {
            score -= 25.0; // perfect chained fill
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover cannot host next item: penalize proportional to wasted potential.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 12.0 * progress;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Global pressure: many open bins -> prefer consolidation into existing bins.
    let pressure = (open_bins_count as f64 / 10.0).min(3.0);
    if bin_residual != bin_capacity {
        score -= 3.0 * pressure;
    } else {
        // New-bin candidate: only attractive when existing residuals are bloated
        // or this bin would be nearly the only sensible option.
        let mean_gap = (mean_residual - item_size as f64).abs();
        score += 12.0 + 2.0 * pressure - 0.5 * mean_gap;
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 10.0; // fresh bin can host item + lookahead comfortably
        }
    }

    // Time horizon: early in the stream, be pickier about waste; late, pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * fit_tightness;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is close to item size.
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * residual_gap;
    score -= 0.1 * (mean_residual - bin_residual as f64).abs().min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits (low post_residual) less aggressively;
    // later, tighten preference as bins become more valuable.
    let tightness = 0.5 + 1.5 * progress * progress;
    score -= tightness * (pr * pr) / cap;

    // Penalize dead space relative to mean residual (smooth quadratic coupling).
    let dev = pr - mean_residual;
    score += 0.25 * dev * dev / cap;

    // Lookahead: reward leaving exactly the space the next item needs (perfect chain),
    // penalize leaving residual slightly too small to fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff == 0.0 {
            score -= 12.0 + 8.0 * progress;
        } else if diff > 0.0 {
            // residual can still hold next item: mild reward decaying with slack
            score -= 6.0 * (1.0 - (diff / cap).min(1.0));
        } else {
            // residual is dead space w.r.t. next item: penalty grows with closeness of miss
            score += 4.0 * (1.0 - (-diff / nxt).min(1.0));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 15.0 * progress;
    }

    // Penalize opening a new bin: scaled by how many bins are already open,
    // and by how much residual would be wasted in the current stream context.
    if bin_residual == bin_capacity {
        let waste = pr / cap;
        score += 8.0 + 0.5 * open_bins_count as f64 + 20.0 * waste * (1.0 - progress);
        // Allow new bin late in the stream when open bins are nearly full on average.
        score -= 10.0 * progress * (1.0 - mean_residual / cap);
    }

    // Mild reward for using bins with low existing residual (best-fit flavor),
    // smoothed via a saturating polynomial.
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 3.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: quantize post_residual into 10-unit buckets.
    // Small post_residual = tight fit = reward (subtract), large = dead space.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold class 0..10
    match class {
        0 => score -= 12.0,                       // near-perfect fit
        1 => score -= 6.0,
        2 => score -= 2.0,
        3 => score -= 0.0,
        4 => score += 3.0,                        // awkward half-empty
        5 => score += 5.0,
        6 => score += 7.0,
        7 => score += 9.0,
        8 => score += 11.0,
        9 => score += 13.0,
        _ => score += 15.0,                       // nearly empty bin class
    }

    // Exact-fit harmonic bonus: post_residual divisible into capacity fractions.
    if pr == 0 {
        score -= 25.0;
    } else if cap / (pr as f64) > 3.0 && pr <= 25 {
        score -= 4.0; // leftover small enough to be re-fillable by typical items
    }

    // Lookahead coupling: if next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            // harmonic class of (pr - next): smaller final leftover is better
            let nxt_left = pr - next_item_size;
            score -= (nxt_left < 15) as i32 as f64 * 8.0;
            score -= (nxt_left < 5) as i32 as f64 * 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // if item is large, new bin is relatively attractive
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Prefer filling bins below mean residual (balancing toward fullness).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item (min size 1..100 unknown, but tiny gaps < 10 are near-useless).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // hard penalty for creating unusable slivers
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Penalize bins whose residual deviates far from mean (keep bin pool balanced).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Open-bin pressure: with many bins open, prefer filling existing ones
    // (subtract to favor this bin), discourage opening new ones implicitly
    // via the new-bin candidate baseline.
    score -= 1.5 * open_bins_count as f64 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if next item is large and this item leaves a gap that fits it,
        // opening a fresh bin can be good — soften penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0;
        }
    } else {
        // Reward chain placement: gap left behind fits the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > 0 {
            // leftover won't fit next item: mild penalty proportional to gap.
            score += 0.1 * (post_residual as f64 - next_item_size as f64);
        }
    }

    // Early in the stream, be more willing to consolidate (favor existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: residual after placement exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the post-residual: good chaining opportunity.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Reward proportionally to how tightly the next item nests.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot use what remains.
        score += 15.0;
    }

    // Compare post-residual against mean residual: prefer bins that end
    // closer to the average fill level (balanced consolidation).
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating tiny unusable fragments (< 10, the smallest item).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference for filling existing bins over opening new ones.
    if bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = item_size as f64 / bin_residual.max(1) as f64;

    // Reward tight fits (low post_residual already does this); amplify near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Penalize leaving residuals that are awkward relative to typical item sizes.
    let awkward = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * awkward;

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 2.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty proportional to wasted potential
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: prefer filling any bin as tightly as possible.
        score -= 20.0 * fit;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 10.0 * fit;
    }

    // Many open bins: encourage consolidation (prefer tighter fills), discourage bin proliferation.
    score += 0.5 * open_bins_count as f64 * (1.0 - fit);

    // New-bin candidate: opening a fresh bin is only attractive when no open bin fits well
    // or the stream is early and future items are large.
    if bin_residual == bin_capacity {
        let base_open_penalty = 40.0 + 3.0 * open_bins_count as f64;
        let early_bird = (1.0 - progress) * 10.0;
        let lookahead_pull = if next_item_size > item_size { 5.0 } else { 0.0 };
        // If this is the only option (fitting_bins_count == 0 among open bins), reduce penalty.
        let only_option = if fitting_bins_count == 0 { 45.0 } else { 0.0 };
        score += base_open_penalty + early_bird + lookahead_pull - only_option;
        // Perfect-fit potential for a fresh bin with a large item.
        if item_size >= bin_capacity * 9 / 10 {
            score -= 20.0;
        }
    }

    // Time horizon: late in the stream, be conservative — prefer reusing existing space.
    score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear coupling: as the stream progresses, tighten preference for small
    // post_residual (squares/cubes of normalized residual), reducing fragmentation.
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let tightness = (1.0 - norm_post).clamp(0.0, 1.0);
    let progress_coupling = progress * tightness * tightness * tightness;
    score -= 40.0 * progress_coupling * (item_size as f64 / bin_capacity as f64);

    // Reward near-perfect fits smoothly: quadratic decay of reward with residual size.
    let perfect = (1.0 - norm_post).clamp(0.0, 1.0);
    score -= 25.0 * perfect * perfect * perfect * perfect;

    // If the next item fits exactly into the post_residual, reward strongly (smooth gate).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let gate = (-gap / 8.0).exp();
        score -= 30.0 * gate;
        // Penalize leaving a residual just barely too small for the next item (dead space).
        if (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
            let dead = next_item_size as f64 - post_residual as f64;
            score += 10.0 * (1.0 - (-dead / 20.0).exp());
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0 + 15.0 * progress;
    }

    // When many bins are open, mild pressure to consolidate into existing bins.
    score += 1.5 * open_bins_count as f64 * norm_post;

    // New empty bin candidate: penalize unless the item is large or fits are poor.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let scarcity = if fitting_bins_count > 0 { 1.0 / fitting_bins_count as f64 } else { 1.0 };
        score += 20.0 - 25.0 * item_frac * item_frac - 15.0 * scarcity * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: enormous reward
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual via integer division thresholds
    let class = post_residual / 10; // 0..9 residual decade
    // Penalize residuals in "dead" classes that few item sizes can reuse
    let dead_penalty = match class {
        0 => 0.0,          // 1..9 : almost unusable, but unavoidable
        1 => 4.0,          // 10..19 : only tiny items fit
        2 => 1.0,          // 20..29
        3 => 0.5,
        4 => 0.0,
        5 => -1.0,         // 50..59 : very reusable
        6 => -1.5,
        7 => -1.0,
        8 => 0.5,
        _ => 2.0,          // 90..99 : nearly empty, wasteful split
    };
    score += dead_penalty;

    // Reward if next item fits exactly into the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 8.0 * (1.0 - gap as f64 / 50.0).max(0.0);
        } else {
            // next item won't fit here: mild penalty scaled by how much it overshoots
            score += 0.05 * ((next_item_size - post_residual) as f64).min(50.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // tie-break toward tighter fits when multiple bins fit
        score -= 2.0 / (1.0 + post_residual as f64);
    }

    // Progress-based pressure: later in stream, prefer consolidating (smaller post_residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Penalize bins far below mean residual (fragmentation avoidance)
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate logic: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a bin
        } else if fitting_bins_count == 1 {
            // prefer last-chance existing bin unless residual is tiny
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0;
    if post_residual > 0 && post_residual < 10 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        score -= 50.0; // perfect fit reward
    }

    // Favor tight fits generally.
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Open-bin pressure: discourage spreading across many bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are crowded.
        score += open_bins_count as f64 * 3.0;
        score -= mean_residual * 0.5;
    } else {
        score += open_bins_count as f64 * 0.3;
    }

    // Last-chance bin: strong reward to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Late in stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect 2-step match: next item fits with minimal slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space that no plausible item can use (items >= 1, but small
    // leftovers below typical minimum sizes are wasted).
    let dead = post_residual.min(9) as f64;
    score += 8.0 * dead;

    // Reward tight fits relative to current mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0; // fresh bin still allows perfect 2-step pairing
        }
    }

    // Slight preference to fill older bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity as f64 - post_residual as f64) * (0.35 + 0.45 * progress);

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize wasting the lookahead opportunity.
            score += 8.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Fragmentation pressure: prefer bins below mean residual when many bins are open.
    let residual_f = bin_residual as f64;
    let diff = residual_f - mean_residual;
    score += 0.08 * diff * (open_bins_count as f64).sqrt();

    // New-bin candidate handling: make an empty bin attractive only when fits are poor
    // or the item is huge relative to typical residuals.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 0 && post_residual < 15 { 1.0 } else { 0.0 };
        let big_item = (item_size as f64 / bin_capacity as f64) * 40.0;
        let crowd = (open_bins_count as f64).min(10.0);
        score += 18.0 - poor_fit * 25.0 - big_item * 0.3 - crowd * 0.5;
        // Early stream: slightly discourage hoarding new bins.
        score += 10.0 * (1.0 - progress);
    }

    // Mild preference for filling larger-residual bins when few are open.
    score -= 0.05 * residual_f * (2.0 - open_bins_count.min(2) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Normalize post_residual relative to capacity
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: post_residual penalty modulated by stream progress.
    // Early on (progress ~ 0), tolerate larger residuals to keep bins flexible;
    // later, strongly penalize residuals that waste capacity.
    let poly = pr * pr * (1.0 - progress) + pr * pr * pr * (1.0 + progress * 2.0);
    score += poly * bin_capacity as f64 * 0.5;

    // Reward tight fits (small post_residual) with a smooth quadratic bonus
    let tight = (1.0 - pr).powi(3);
    score -= tight * 12.0;

    // Last-chance bin: smooth exponential urgency reward
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement smoothly
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * fit_ratio * (1.0 - fit_ratio + 0.5);
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Penalize leaving residual too small for the next item (dead space)
        let waste = next_item_size as f64 - post_residual as f64;
        score += 4.0 * (waste / bin_capacity as f64) * (1.0 + progress);
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from the mean
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / (1.0 + mean_residual);

    // New-bin candidate: penalize opening a new bin smoothly, more when many bins exist
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 and 20
    let r = post_residual % 10;
    let r20 = post_residual % 20;

    // Dead-space penalty: residuals that cannot absorb typical small items
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable dead space
        } else if r == 1 || r == 2 || r == 3 {
            score += 12.0; // awkward residue class
        } else if r20 == 0 {
            score -= 15.0; // perfectly harmonic residual, likely reusable
        } else if r == 0 {
            score -= 8.0;
        }
    } else {
        score -= 30.0; // perfect fill
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward if next item exactly matches (harmonic match)
            let diff = post_residual - next_item_size;
            if diff == 0 {
                score -= 45.0;
            } else if diff % 10 == 0 {
                score -= 20.0;
            } else {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: penalize leaving a large stranded residual
            score += (post_residual as f64) * 0.35;
        }
    }

    // Tight fit reward
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 25.0;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: prefer it only when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            // opening a new bin wastes the mean residual of open bins
            score += 20.0 + mean_residual * 0.5 + (open_bins_count as f64) * 2.0;
        }
    }

    // Mild stream-progression pressure to consolidate early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum item size) are pure waste — penalize heavily.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0;
    }

    // Unusable gap threshold: residuals below ~10 (or below typical small items)
    // are hard to fill later. Non-linear penalty growing as gap shrinks.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += (10.0 - gap) * (10.0 - gap) * 2.0;
    }

    // Reward near-perfect fits (tight packing).
    if gap <= 5.0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement chains perfectly — reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; the gap is likely dead — penalize slightly.
        score += 3.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // bins that will be emptied of residual (lower post_residual already does
    // that), but penalize spreading across too many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin is only attractive when no open bin
    // offers a decent fit (post_residual here is large and item barely fits).
    if bin_residual == bin_capacity {
        // Prefer using existing bins unless this bin's fit is terrible.
        score += 12.0;
        // But if open bins are nearly full on average, a fresh bin is fine.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Progress coupling: late in the stream, waste matters slightly more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += gap * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: item leaves exactly the space the next item needs.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            score -= 12.0; // leaves room for next item, keep some preference
        } else {
            // dead space smaller than next item: penalize more as it becomes useless
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    } else {
        // last item: prefer tightest fill
        score -= 5.0;
    }

    // Favor bins whose residual is already below-average (tight bins close fast).
    let prog = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - post_residual as f64) * (0.25 + 0.3 * prog);

    // Last-chance bin: strongly encourage using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize leaving very small unusable slivers (<10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Empty new-bin candidate: neutral-ish baseline, slightly penalized so it's
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.15 * (open_bins_count as f64);
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no future item (min size 1) can plausibly use.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 6.0 * dead * dead;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for stranding space.
            score += 2.0;
        }
    } else {
        // Last item: prefer filling a bin as completely as possible.
        score -= 10.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + 0.05 * (open_bins_count as f64);
    }

    // New-bin candidate handling: opening a fresh bin is attractive early in the
    // stream or when many bins are open with large mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = mean_residual / bin_capacity as f64;
        // Open new bin when existing bins are fragmented or stream is early.
        score -= 4.0 + 10.0 * fragmentation + 8.0 * (1.0 - progress);
        // But discourage hoarding bins late in the stream with good fits available.
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 5.0;
        }
    }

    // Mild preference for bins below mean residual (balancing load across bins).
    score += 0.02 * (bin_residual as f64 - mean_residual);

    // Prefer using bins that are already partly filled (reduce bin count pressure).
    score -= 0.5 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post residual and item size
    let pr = post_residual as f64 / bin_capacity as f64;
    let isz = item_size as f64 / bin_capacity as f64;

    // Smooth non-linear penalty on dead space: quadratic coupling of residual with progress
    score += 30.0 * pr * pr * (0.5 + progress);

    // Reward tight fits: cubic decay of penalty as post_residual -> 0
    score -= 20.0 * (1.0 - pr).powi(3) * isz;

    // Interaction: small residuals matter more as stream progresses
    score -= 15.0 * (1.0 - pr) * progress * progress;

    // Penalize bins whose residual deviates from mean residual (fragmentation spread)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev * dev;

    // Lookahead coupling: penalize if post residual can't fit next item but nearly could
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx {
            let gap = (nx - post_residual as f64) / bin_capacity as f64;
            score += 10.0 * gap * (1.0 - progress);
        } else {
            // Reward bins that remain usable for the next item
            score -= 6.0 * (post_residual as f64 - nx) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: only fitting bin gets strong reward, smoothly scaled by progress
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    } else {
        // Mild penalty when many bins compete (prefer consolidation)
        score += 2.0 * (fitting_bins_count as f64).ln() * (1.0 - pr);
    }

    // Penalize opening new bins when open bins exist and residual is ample
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0 + 10.0 * mean_residual / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "usable"
    // residue class (multiples of 10) are favored; odd/dead classes penalized.
    let cls = (post_residual % 10) as f64;
    score += cls * 0.6;

    // Integer-division threshold: leftover >= next item is valuable (lookahead fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 {
        // Leftover cannot host next item: penalize proportionally to gap.
        score += (next_item_size - post_residual) as f64 * 0.1;
    }

    // Perfect/near-perfect closure reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Tight-fit bonus: item occupies a large fraction of residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 8.0;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln_1p() * 2.0;
        score = bin_capacity as f64 * 1.15 + pressure
            - if next_item_size > 0 && next_item_size <= bin_capacity {
                4.0
            } else {
                0.0
            };
        // Late in the stream, prefer closing out existing bins.
        score += (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Mild preference toward bins below mean residual (balance load).
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
