    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.15 + 0.35 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it instead of opening a fresh bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Mean-residual coupling: bins with residual below the mean are
    // "drying out"; packing into them preserves large gaps elsewhere.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // New-bin candidate: only attractive when the item is large relative
    // to what open bins can absorb and the stream is early/mid.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > 60 { 6.0 } else { 0.0 };
        let scarcity_bonus = if fitting_bins_count == 0 { 10.0 } else { 0.0 };
        score += 10.0 - large_item_bonus - scarcity_bonus
               + open_bins_count as f64 * 0.5
               + progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the residual after this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Next item fits with small leftover after it: strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        score -= 40.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
        if leftover_after_next == 0 {
            score -= 150.0;
        }
    }
    // Penalize placements that leave residual too small for the next item (dead space).
    if next_item_size > post_residual && post_residual > 0 {
        score += 30.0 + 0.5 * post_residual as f64;
    }
    // Penalize tiny dead residuals (< 10, unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tight" — prefer
    // filling them when the fit is good, penalize when it wastes space.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 20.0 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless residual would be wasted badly).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 60.0 - 25.0 * crowded.min(2.0);
        // If next item is huge and current mean residual is small, opening new bin is fine.
        if next_item_size as f64 > mean_residual {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else {
        // Penalize large dead space quadratically, scaled by how much of the bin it wastes.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, this placement
    // is very attractive; if the next item would NOT fit here but this bin could
    // otherwise hold it, slight penalty (reserve space wisely).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // placing here destroys the only space the next item could use in this bin
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when existing residuals are large
    // (poor fits everywhere) or many items remain to pack.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes nothing now, but costs later; penalize mildly,
        // more so late in the stream when few items remain.
        score += 15.0 + 25.0 * progress;

        // If the mean residual across open bins is large, open bins are sloppy:
        // a fresh bin is more attractive.
        if mean_residual > item_size as f64 + 10.0 {
            score -= 18.0;
        }
        // If this is the only option, it will win anyway via other scores.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight preference for filling bins with smaller residual (best-fit flavor)
    // when many bins are open; encourages consolidation early.
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0 * (1.0 - progress);

    // Mild consolidation pressure when the number of open bins grows large.
    if open_bins_count > 8 {
        score += (post_residual as f64) * 0.05 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = norm_pr;

    // Non-linear polynomial coupling: penalize small residuals more as stream progresses
    let tight = (1.0 - norm_pr).powi(3);
    score -= 2.0 * progress * tight;

    // Penalize exact-fit waste quadratically
    score += 0.5 * norm_pr * norm_pr * (1.0 - progress);

    // Reward using bins when few bins can fit the item
    if fitting_bins_count <= 1 {
        score -= 1.5 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        score -= 0.8 * fit_next * (1.0 - (pr - nxt).abs() / cap);
    }

    // Coupling with mean residual: prefer bins near mean
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // Mild penalty for opening new bins when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 0.6 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fill classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-exact fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= bin_capacity / 20 {
        score -= 300.0;
    } else if post_residual <= bin_capacity / 10 {
        score -= 120.0;
    }

    // Dead-space penalty: residuals in the "unusable" band (too small for
    // typical small items) are toxic; scale with how dead the space is.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }

    // Modulo arithmetic on post_residual: residuals that divide capacity
    // evenly (harmonic classes 50, 25, 20, 10, 5) leave reusable chunks.
    let harmonic = [50u32, 25, 20, 10, 5];
    if harmonic.iter().any(|&h| h != 0 && post_residual % h == 0 && post_residual > 0) {
        score -= 60.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // perfect chained fill
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here: leftover becomes dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Prefer packing into bins whose residual deviates below the mean
    // (tighten nearly-full bins first).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 80.0 };
        score = cap * 0.9 + pressure + mean_residual * 0.1;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 40.0; // big next item favors a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..100 stream,
    // but tiny slivers are practically unusable) can fill are heavily penalized.
    if post_residual > 0 {
        // Non-linear penalty growing as residual shrinks into the "dead zone".
        let dead_threshold = 12.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
        // Perfect fit bonus: near-zero waste is strongly rewarded.
        if post_residual <= 2 {
            score -= 25.0;
        } else if post_residual <= 6 {
            score -= 8.0;
        }
    } else {
        // Bin closed exactly: best possible outcome.
        score -= 40.0;
    }

    // Reward using a tight bin (small residual before placement) => compact packing.
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.15;

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins over spreading; when few bins, new-bin cost is lower.
    let pressure = (open_bins_count as f64).sqrt() * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, discounted when nothing fits well.
        score += 20.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 60.0; // forced new bin
        } else if post_residual >= bin_capacity - item_size {
            // fresh bin leaves huge residual; only attractive if item is large
            score -= (item_size as f64) * 0.1;
        }
    } else {
        // Existing bin: mild discount, stronger if it's the last chance bin.
        score -= 5.0;
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
    }

    // Lookahead: if next item fits the post-residual, this placement sets up a chain.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0; // leaves a gap the next item cannot use
    }

    // Stream progression: late in the stream, avoid opening new bins even harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 8.0;
    }

    // Slight preference for bins below mean residual (fill the emptier bins first
    // keeps tight bins available for tight items).
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        // Tight lookahead coupling: reward closeness of post_residual to next_item_size
        score -= 30.0 * (1.0 - diff as f64 / (bin_capacity as f64));

        if post_residual == next_item_size {
            score -= 25.0; // chainable pair, excellent
        } else if post_residual < next_item_size {
            // Dead space relative to lookahead item: penalize unusable remainder
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // post_residual can host next item too: reward proportional surplus fit
            score -= 0.3 * (post_residual - next_item_size) as f64;
        }
    } else {
        // Last item: just minimize leftover
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mean-residual alignment: bins with residual near the mean are "typical" targets;
    // prefer placing into bins whose residual is closest to mean (keeps distribution tight)
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // New-bin candidate: allow opening a fresh bin when it preserves large contiguous space,
    // but only if current bins are relatively full (mean residual small)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fullness = 1.0 - mean_residual / bin_capacity as f64;
        // New bin attractive when existing bins are nearly full and stream continues
        score -= 15.0 * fullness * (0.5 + 0.5 * progress);
        // But discourage opening new bins when the item fits poorly elsewhere anyway is fine:
        if item_size >= 70 {
            score -= 10.0; // big items fit best in fresh bins
        }
    }

    // Slight preference for tighter fits overall
    score += 0.1 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- New-bin candidate handling ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: prefer reusing open bins when the fit is decent.
        score += 25.0;
        // If this is the ONLY bin that can fit the item, opening a new bin
        // is unavoidable anyway; soften the penalty so ties resolve cleanly.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Early in the stream, allow more bins to stay open in parallel
        // (keeps flexibility for large items later).
        score -= (1.0 - progress) * 10.0;
        // If many bins are already open, discourage adding more.
        score += open_bins_count as f64 * 1.5;
        // If the item is huge relative to capacity, a fresh bin is fine.
        if (item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
        return score;
    }

    // --- Tightness reward: reward near-perfect fills ---
    let capacity_f = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / capacity_f;
    score -= tightness * tightness * 12.0;

    // --- Dead-space penalty: small post_residual that no typical item can use ---
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    }

    // --- Lookahead (k=2): does the next item fit in the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: next item can chain into this bin.
            score -= 6.0;
            // Extra reward if the chain nearly fills the bin.
            let combined = item_size + next_item_size;
            if combined >= bin_capacity - 5 {
                score -= 8.0;
            }
        } else if next_item_size <= bin_residual {
            // Next item fits only if we DON'T place here -> mild penalty
            // for consuming space the lookahead item needs.
            score += 4.0;
        }
    }

    // --- Last-chance bonus: this is the only open bin that fits ---
    if fitting_bins_count == 1 {
        score -= 7.0;
        // Stronger when late in the stream (consolidation phase).
        score -= progress * 5.0;
    }

    // --- Global residual coupling: prefer bins below the mean residual
    //     (fill the emptiest-but-fitting bins first keeps tight bins tight). ---
    let diff = mean_residual - bin_residual as f64;
    score -= diff * 0.05;

    // --- Late-stream consolidation: as stream ends, prefer minimal post residual ---
    score += progress * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize post residual, with smooth polynomial coupling to progress.
    // Early on, leftover space is less costly; late, tight packing matters more.
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Non-linear quadratic term: reward very small post residuals (good fits),
    // smoothly scaled by stream progress.
    let tightness = 1.0 - pr_norm;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Penalize large dead space with cubic term (unusable leftovers).
    score += 4.0 * pr_norm * pr_norm * pr_norm * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead coupling: reward if next item fits smoothly in post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 3.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Mean residual context: prefer bins whose residual deviates from mean
    // in the useful direction (smaller than mean residual = tighter bin).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev * (1.0 - progress) - 2.0 * dev;

    // Mild penalty for opening new bins when many bins already open.
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does the leftover fall in?
    let quarter = bin_capacity / 4;
    let post_class: u32 = if post_residual == 0 {
        0
    } else if post_residual < quarter / 2 {
        1 // tiny dead space (1..12)
    } else if post_residual < quarter {
        2 // small (13..24)
    } else if post_residual < 2 * quarter {
        3 // medium (25..49)
    } else if post_residual < 3 * quarter {
        4 // large (50..74)
    } else {
        5 // huge (75..100) — nearly a fresh bin anyway
    };

    // Reward exact fills and tiny leftovers; penalize the awkward small/medium bands.
    match post_class {
        0 => score -= 40.0,
        1 => score -= 12.0,
        2 => score += 18.0,
        3 => score += 8.0,
        4 => score -= 2.0,
        _ => {}
    }

    // Modulo arithmetic on post_residual: leftover divisible by small harmonics is more reusable
    // by typical item sizes drawn from coarse grids.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0; // leftover aligns with decade-sized items
        } else if pr % 5 == 0 {
            score -= 3.0;
        } else if pr % 3 == 0 {
            score -= 1.5;
        } else {
            score += 2.0; // coprime-ish leftover is hard to fill
        }
        // Integer-division harmonic: how many "typical" 10-unit items fit in the leftover
        let slots = pr / 10;
        score += (4 - slots.min(4)) as f64 * 2.5; // fewer usable slots => worse
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0; // perfect chain fill
        } else if gap <= quarter / 2 {
            score -= 10.0;
        } else {
            score -= 4.0;
        }
        // Harmonic match: next item size and leftover share a divisor
        let g = gcd(next_item_size, pr.max(1));
        if g >= 5 {
            score -= 2.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this bin's leftover: leftover is more likely dead space
        if post_class >= 2 && post_class <= 3 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the current item is large
    // and no good fit exists (i.e., this empty-bin call has huge post_residual anyway).
    if bin_residual == bin_capacity {
        // neutral baseline; slight penalty so we prefer decent existing fits
        score += 5.0;
        if item_size >= 3 * quarter {
            score -= 8.0; // large items start fresh bins more willingly
        }
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing fits elsewhere: must open
        }
    }

    // Stream progression: late in the stream, consolidate harder (avoid opening bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 4.0 * progress;
    }

    // Tie-break: prefer filling bins with less mean residual spread (keep bins homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild preference for tighter bins overall.
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=12) are almost unusable
    // for future items (sizes >= 1, typically >= 10), so penalize them hard.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (13.0 - post_residual as f64) / 13.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave a gap still usable by the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra reward if the next item exactly fills the resulting gap.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item: mild dead-space penalty.
        score += 8.0;
    }

    // Best-fit bias: prefer bins whose residual was already tight.
    let tightness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness;

    // Open-bin pressure: discourage opening new bins when many are open,
    // encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow.
        score += 25.0 + 3.0 * pressure;
        // Opening a fresh bin is fine early on or when nothing fits well.
        if open_bins_count == 0 {
            score -= 50.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Reward using existing bins, scaled by how many alternatives exist.
        score -= 2.0 * pressure;
        // Last-chance bin: strongly favor filling it to avoid waste.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Prefer bins below the mean residual (relatively emptier bins absorb
    // items, keeping tight bins available for small future items).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward leaving exactly the space the next item needs.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - nxt).abs();
        // Perfect match for next item: big bonus.
        if post == nxt {
            score -= 60.0;
        } else if post > nxt {
            // Leftover after next item would fit: penalize proportional to waste.
            score += gap * 0.5;
        } else {
            // Next item won't fit here; mild penalty scaled by shortfall.
            score += gap * 0.2;
        }
        // Coupling with mean residual: bins far from mean residual are less attractive
        // unless they match the next item perfectly.
        let dev = (post - mean_residual).abs();
        score += dev * 0.15;
    } else {
        // Last item: just minimize waste.
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter fits (already via post_residual).
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is large
    // and would leave a very usable residual, or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 >= 0.5 * bin_capacity as f64;
        let good_new_residual = post_residual as f64 >= 30.0;
        let mut new_bin_score = 15.0; // base cost of opening a new bin
        if large_item && good_new_residual {
            new_bin_score -= 20.0;
        }
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            new_bin_score -= 10.0; // new bin can also host next item
        }
        // As stream progresses, opening bins is less costly (more info known).
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score -= progress * 5.0;
        // More open bins -> slight extra penalty for adding another.
        new_bin_score += open_bins_count as f64 * 0.5;
        score += new_bin_score;
    }

    // Penalize creating tiny unusable dead space (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space that is too small for any plausible item (min size 1,
    // but small leftovers are hard to fill): dead space below ~20 is risky.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 20.0 {
            score += (20.0 - dead) * 0.8;
        }
    } else {
        // Perfect closure of a bin is excellent.
        score -= 25.0;
    }

    // Lookahead: if the next item fits into this bin's post-residual, reward;
    // if it would leave this bin stranded, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // Extra reward if next item nearly fills the remainder.
            let nxt_tight = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 8.0 * nxt_tight;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is discouraged unless current bins are crowded
        // or this is a large item that would fragment an open bin badly.
        let pressure = mean_residual / bin_capacity as f64;
        score += 15.0 + 20.0 * (1.0 - pressure);
        if item_size >= 70 {
            score -= 10.0; // big items are fine in a fresh bin
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0; // pairing potential with lookahead
        }
    }

    // Global state coupling: prefer bins whose residual is below the mean
    // (consolidate waste into few bins), penalize dipping into large-residual bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in the stream, keep bins flexible (mild penalty for
    // very small leftovers); late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty for proliferating open bins when many alternatives exist.
    if fitting_bins_count > 3 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = norm_pr + 1.5 * norm_pr * norm_pr + 2.0 * norm_pr * norm_pr * norm_pr;

    // Smooth coupling of residual tightness with stream progress:
    // early on, tolerate larger residuals; late, demand tight fits.
    let tightness = 0.5 + 2.0 * progress;
    score *= 0.5 + tightness * norm_pr;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 5.0;
    } else {
        // Reward residuals too small for the smallest plausible item (dead space is fine if tiny)
        score -= 2.0 * (1.0 - (pr / 10.0).min(1.0));
    }

    // Lookahead: penalize if post_residual exactly invites a wasteful next placement,
    // reward if next item fits snugly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let next_fit = (pr - ni) / cap;
            score += 0.8 * next_fit * next_fit - 0.5 * (1.0 - next_fit);
        } else {
            score -= 0.4; // next item won't fit anyway; closing this bin tightly is good
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0 + 2.0 * progress;
    }

    // Mild penalty when many bins are open relative to stream (encourage consolidation)
    score += 0.05 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual is near mean (balanced packing)
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate handling: make empty bin attractive only when it beats bad fits
    if bin_residual == bin_capacity {
        score = 8.0 + 3.0 * norm_pr - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions.
    let post_frac = post_residual as f64 / cap; // 0..1
    let class = (post_frac * 10.0).floor() as i64; // 0..9 harmonic decile

    // Reward tight fits: lower decile class is better (small residual).
    score -= (9 - class) as f64 * 4.0;

    // Penalize residual classes that are "dead space" (too small for typical items 1..100).
    // Residuals in (0, 10] are nearly unusable: heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: this placement keeps the bin useful for the next item.
            score -= 25.0;
            // Harmonic bonus: next item's own class of fit tightness.
            let next_tight = (post_residual - next_item_size) as f64;
            score -= (30.0 - next_tight.min(30.0)) * 0.5;
        } else {
            // Next item won't fit here; mildly penalize leaving mid-range dead space.
            if post_residual >= 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item fits poorly.
    if bin_residual == bin_capacity {
        let base = 15.0;
        // If the item is small relative to capacity, prefer existing bins.
        let item_frac = item_size as f64 / cap;
        // Opening new bin is attractive only if item is large and few bins fit it.
        let open_penalty = if item_frac > 0.5 && fitting_bins_count <= 2 {
            -10.0
        } else {
            20.0 + 5.0 * (open_bins_count as f64).sqrt()
        };
        score += base + open_penalty;
    }

    // Prefer filling bins with low residual relative to the mean (use "old" bins).
    let res_frac = bin_residual as f64 / cap;
    let mean_frac = mean_residual / cap;
    if mean_frac > 0.0 {
        // If this bin's residual is below mean, it's a good filler candidate.
        score += (res_frac - mean_frac) * 30.0;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - res_frac);

    // Modulo-based tie-breaking on residual to diversify harmonic classes:
    // prefer residuals divisible by common item sizes (10, 20, 25, 50).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Integer division thresholds: residual buckets via division by 33.
    let bucket = post_residual / 33;
    score += bucket as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // (items are 1..100, but small gaps rarely match future demand).
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable dead space: heavy penalty proportional to how "wasted" it is
            score += (11 - post_residual) as f64 * 25.0;
        } else if post_residual <= 20 {
            score += (21 - post_residual) as f64 * 6.0;
        } else if post_residual <= 35 {
            score += (36 - post_residual) as f64 * 2.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits generally (small relative slack)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 2.0 * (1.0 - tightness)) * (0.5 + progress);

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual as f64);
        } else {
            // next item won't fit here; leftover is truly dead unless reusable later
            score += 8.0;
        }
    }

    // New-bin candidate handling: an empty bin is attractive when this bin's fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, softened when many bins are open / mean residual low
        let mut nb = 30.0 + mean_residual * 0.15;
        // If the current bin would leave a tiny dead gap, opening fresh is better
        if post_residual > 0 && post_residual <= 10 {
            nb -= 70.0;
        }
        // Early stream: keep flexibility, cheaper to open bins
        nb -= 10.0 * (1.0 - progress);
        score += nb;
    }

    // Mild preference for bins below mean residual (balance load across bins)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit shaping: heavily reward small post_residual.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 60.0 / post_residual as f64;
    }

    // 2-step lookahead: strongly reward when the NEXT item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            if gap == 0.0 {
                score -= 400.0; // chain perfect fit: item then next item close this bin fully
            } else if gap <= 10.0 {
                score -= 150.0 - gap * 8.0;
            } else {
                score -= (20.0 * nxt / pr).min(40.0); // next item can still use most of the leftover
            }
        } else {
            // next item cannot fit in the leftover: leftover is likely dead space
            score += (nxt - pr).min(80.0) * 0.8;
        }
    } else {
        // Last item in stream: prefer fullest packing, ignore future.
        score -= 30.0;
    }

    // Relative-to-mean coupling: bins already tighter than average are good targets.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes the residual of existing bins.
    if bin_residual == bin_capacity {
        // Penalize new bins when good fitting bins exist; allow when item is large
        // (big items leave useful residuals anyway) or few bins are open.
        let waste_penalty = if next_item_size > 0 {
            45.0 + (open_bins_count as f64).min(20.0) * 2.0
        } else {
            100.0
        };
        let large_item_relief = (item_size as f64 / 100.0) * 60.0;
        score += waste_penalty - large_item_relief;
    }

    // Slight stream-progress term: early on, be a bit more willing to consolidate
    // (open fewer bins); later, tight fits matter more than bin count.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a quadratic term.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item leaves a very large dead space in every existing bin
    // (i.e., post_residual here is tiny because residual is full capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for fragmentation (opening new bins).
        score += 25.0;
        // If the item is huge relative to capacity, a fresh bin is fine.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // Late in the stream, prefer consolidating; early, allow expansion.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If many bins are open and mean residual is high, prefer existing bins.
        score += (open_bins_count as f64).ln().max(0.0) * 3.0 + mean_residual * 0.2;
    } else {
        // Reward using bins whose residual closely matches the item (good fill).
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fit_ratio * 10.0;

        // Lookahead: if the next item could exactly fill this bin's post_residual,
        // bonus; if next item can't fit post_residual anyway, slight penalty.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 30.0; // perfect chaining
            } else if next_item_size > post_residual {
                score += (next_item_size - post_residual) as f64 * 0.3;
            } else {
                score -= 5.0;
            }
        }

        // Slightly prefer bins below mean residual (balancing leftover space).
        score += (mean_residual - bin_residual as f64) * 0.1;

        // Penalize leaving tiny unusable slivers, unless next item may use them.
        if post_residual < 10 && (next_item_size == 0 || next_item_size > post_residual) {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: prefer small post_residual (tight packing), non-linearly amplified.
    let mut score = pr * (1.0 + 0.8 * pr / cap);

    // Smooth polynomial coupling of residual waste with stream progress:
    // later in the stream, dead space becomes more costly.
    let waste_coupling = (pr / cap).powi(2) * (0.5 + 2.0 * progress * progress);
    score += waste_coupling * cap * 0.3;

    // Reward near-perfect fits smoothly (bell-shaped around zero post-residual).
    let tightness = (-2.0 * pr / cap).exp();
    score -= tightness * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 * (0.5 + progress);
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = pr - next_item_size as f64;
        score -= 8.0 * (-2.0 * gap / cap).exp();
    } else if next_item_size > 0 {
        // Penalize leaving a residual that no plausible next item uses.
        score += 3.0 * (pr / cap);
    }

    // New-bin candidate: mild default penalty; opened only if fits are poor.
    if is_new_bin {
        score += 6.0 - 4.0 * progress;
        // More open bins -> slightly more willing to open another to keep slack.
        score -= (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // Slight preference for bins below mean residual (keep balance).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // post_residual divisible by common sizes => leftover reusable
        let harmonic_bonus = if pr % 10 == 0 { 12.0 }
            else if pr % 20 == 0 { 9.0 }
            else if pr % 25 == 0 { 8.0 }
            else if pr % 50 == 0 { 10.0 }
            else { 0.0 };
        score -= harmonic_bonus;

        // Dead-space penalty: tiny unusable leftovers
        if pr < 10 {
            score += 40.0 * (10 - pr) as f64;
        } else if pr < 20 {
            score += 8.0;
        }

        // Integer-division threshold classes on post_residual
        let class = pr / 10; // 0..10
        score += (class as f64) * 1.5;
    } else {
        score -= 25.0; // perfect fill
    }

    // Lookahead coupling: does post_residual admit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chainability reward, stronger if next item also fits snugly
            let slack = post_residual - next_item_size;
            score -= 10.0;
            if slack % 10 == 0 { score -= 5.0; }
            if slack < 10 && slack > 0 { score += 6.0; }
        } else {
            score += 15.0; // bin becomes dead after this placement
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins with high mean residual: encourage consolidation
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual >= item_size {
        score -= 4.0;
    }

    // New-bin candidate handling: only attractive when current bins are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (mean_residual / cap) * (open_bins_count as f64).sqrt();
        // penalize new bin unless mean residual is very low (nothing fits well)
        score += 45.0 - 35.0 * pressure - 10.0 * progress;
        if next_item_size > 0 && next_item_size > bin_capacity as u32 - item_size.min(bin_capacity as u32) {
            score += 5.0;
        }
    }

    // Fraction-of-capacity fit quality: reward tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual < 20 {
        // Tight but non-zero fit: mild reward scaled by tightness.
        score -= (20 - post_residual) as f64 * 1.5;
    }

    // Penalize leaving a gap that the lookahead item cannot use, but the gap
    // is large enough to be useful in general (soft dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward if the lookahead item exactly fills the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins; also penalize the new-bin candidate mildly.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when fits into open bins are poor.
    if bin_residual == bin_capacity {
        score += 70.0;
        // More open bins => new bin is more acceptable (spread load).
        score -= open_bins_count as f64 * 0.8;
        // Prefer opening a new bin early in the stream when residual spread is high.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If mean residual is large, existing bins are roomy; new bin less needed.
        score += mean_residual * 0.2;
    }

    // Mild scaling of raw post residual with progress: late in stream, waste
    // matters more (fewer future items to fill gaps).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * 0.3 * progress;

    // Penalize bins whose residual deviates strongly from mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: waste-free placement strongly favored.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 5 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item exactly fits the post-residual,
    // this is a chained perfect fit — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            let chain_waste = post_residual - next_item_size;
            if chain_waste < 10 {
                score -= 40.0;
            } else {
                score -= 15.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
            }
        } else {
            // Next item cannot fit in the leftover; penalize dead space.
            let dead = next_item_size - post_residual;
            score += 10.0 + dead as f64 * 0.3;
        }
    }

    // Compare post_residual against the mean residual: leaving this bin
    // below-average residual is good (tight packing), above-average is bad.
    let mr = mean_residual.max(0.0);
    score += (post_residual as f64 - mr) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 50.0;
        // But if next item would be stranded with tiny residual, soften.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer opening a new bin when the current fit creates large waste
    // relative to the item size.
    if bin_residual == bin_capacity {
        let waste = item_size as f64 / bin_capacity as f64;
        // Penalize new bins mildly by default; the lower the fill ratio, the
        // less attractive a new bin is.
        score = bin_capacity as f64 * 0.9 + waste * 20.0;
        // If lookahead chain fits perfectly in a fresh bin, make it competitive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 40.0;
        }
    }

    // Early in the stream, slightly discourage hoarding many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && progress < 0.3 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize dead space: small post_residual but not zero is bad only if
    // no future item can use it; reward post_residual that can host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0; // lookahead compatibility bonus
    } else if next_item_size > 0 {
        // post_residual too small for next item: penalize proportionally to wasted space
        let waste = post_residual as f64 / bin_capacity as f64;
        score += waste * 10.0;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Time horizon: early in the stream, be conservative (prefer new bins for large items);
    // late in the stream, fill existing bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let mean_res_norm = mean_residual / bin_capacity as f64;
    if bin_residual as f64 > mean_residual {
        score += 2.0 * mean_res_norm; // this bin is above-average residual: less attractive
    } else {
        score -= 2.0 * mean_res_norm;
    }

    // New-bin candidate handling: an empty bin should only win when the item fits
    // poorly everywhere else. Base penalty for opening a new bin, scaled by
    // how much residual would be left and stream position.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 15.0 + 10.0 * (post_residual as f64 / bin_capacity as f64) + 6.0 * (1.0 - progress);
        score += new_bin_penalty;
        // Large items (hard to place later) justify a new bin more readily.
        if item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
        // If no open bin can fit, opening is unavoidable; soften penalty.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild penalty for leaving post_residual in the awkward 1..=10 dead zone.
    if post_residual > 0 && post_residual <= 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let nb = open_bins_count as f64;
    let next = next_item_size as f64;
    let mean_r = mean_residual;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let prog_poly = 0.5 + 1.5 * progress * progress;
    score *= 1.0 + 0.3 * prog_poly * norm_pr;

    // Reward tight fits more strongly as the stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 20.0 * (0.5 + progress);

    // Penalize creating dead space that cannot fit the next item (smooth coupling)
    if next > 0.0 {
        let gap = (pr - next).max(0.0);
        let gap_frac = gap / cap;
        score += 15.0 * gap_frac * gap_frac * (1.0 + progress);
        // Reward leaving exactly room for the lookahead item
        let match_frac = 1.0 - ((pr - next).abs() / cap);
        score -= 10.0 * match_frac * match_frac * match_frac;
    }

    // Last-chance bonus: smooth in fitting_bins_count
    let last_chance = 1.0 / fit;
    score -= 25.0 * last_chance * (1.0 - norm_pr) * (0.6 + 0.4 * progress);

    // Mild penalty when many bins are open and residual is large (fragmentation)
    score += 0.05 * nb * norm_pr * norm_pr;

    // Coupling with mean residual: prefer bins near the mean (smoothness)
    let dev = (pr as f64 - mean_r).abs() / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score = cap + 40.0 * (1.0 - progress) - 30.0 * (1.0 - last_chance);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters: reward residuals
    // that fall into "usable" classes (>= half of the smallest item).
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);
    match class {
        0 => { score -= 6.0; }                    // very tight fit: excellent
        1 => { score += 2.0; }                    // quarter-class: mediocre
        2 => { score -= 1.0; }                    // half-class: decent
        _ => { score += 4.0; }                    // mostly empty bin used wastefully
    }

    // Dead-space penalty: residuals that no plausible item (1..=100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect-fill bonus via modulo arithmetic on capacity.
    if bin_capacity % (item_size.max(1)) == 0 && post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 { score -= 8.0; } else { score += slack as f64 * 0.3; }
        } else {
            // next item cannot follow here: slight penalty
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when open bins
    // would create large dead space or none fit well.
    if bin_residual == bin_capacity {
        // brand-new bin: baseline cost, adjusted by stream position and congestion
        score = 0.5 * bin_capacity as f64
            + 0.5 * mean_residual
            + (open_bins_count as f64) * 2.0
            - (step_index as f64 / (total_items.max(1) as f64)) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host next item too
        }
    } else {
        // slight preference to keep number of open bins low
        score += (open_bins_count as f64) * 0.05;
    }

    // Mean-residual coupling: penalize bins far below mean residual (fragmentation risk)
    let dev = mean_residual - post_residual as f64;
    if dev > 20.0 { score += dev * 0.2; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small gaps that few future items can use.
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading.
    score += open_bins_count as f64 * 0.5;

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item cannot fit and post residual is wasted.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: mildly favor new bin only when current fit is terrible.
    if bin_residual == bin_capacity {
        score -= 5.0;
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // Stream progression: later in stream, tighten dead-space tolerance.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // dead space penalty scaled by wasted amount
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // last item: prefer tightest fit
        score += 5.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening new bins when existing bins can fit
    if bin_residual == bin_capacity {
        score += 50.0 + open_bins_count as f64 * 2.0;
        // allow new bin if existing fit would create large dead space
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 60.0;
        }
    }

    // Late stream: be more conservative, fill bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover; mild penalty for squandering space
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Encourage consolidating into few bins when many are open.
    score += 0.6 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual far from the mean (specialized fits) slightly less.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: later in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // New empty bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual + item_size == bin_capacity {
            // this is the new-bin call; item will fill it if item is large
            score += item_size as f64 * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits, with non-linear polynomial coupling to stream progress
    let mut score = pr as f64;

    // Smooth interaction: post_residual weighted more heavily as stream progresses
    // (later in the stream, waste matters more, so tighten fits)
    let progress_weight = 0.5 + 1.5 * progress;
    score += progress_weight * 20.0 * (x * x - x); // negative for x in (0,1), strongest mid-range

    // Penalize large dead space with a cubic term coupled to progress
    score += progress * 15.0 * x * x * x;

    // Reward near-perfect fits smoothly: exp-like decay on post_residual
    score -= 8.0 * (-pr / 12.0).exp() * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr >= nx) {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack).max(0.0);
        } else {
            // penalize if next item cannot use leftover space, scaled by leftover size
            score += 4.0 * (pr / cap) * (nx / cap);
        }
    }

    // Mild preference for balancing residuals when many bins are open
    let dev = (mean_residual - pr).abs();
    score += 0.05 * dev * (1.0 + open_bins_count as f64).ln();

    // Slight preference for fuller bins when few bins are open (consolidation)
    score -= (open_bins_count as f64).recip() * 3.0 * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify by integer division into
    // capacity-fraction bands (dead-space quality classes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let cls = (post_residual / 10).min(9); // 0..9 harmonic class of leftover space

    // Reward small leftovers super-linearly; class 0 (0-9 leftover) is gold.
    match cls {
        0 => score -= 30.0,
        1 => score -= 18.0,
        2 => score -= 10.0,
        3 => score -= 4.0,
        _ => {}
    }

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize creating leftover space that no item class can plausibly use:
    // leftover in (0,10) is actually great (already rewarded); leftover in
    // (10,20) is awkward if it can't host the smallest class.
    if post_residual > 10 && post_residual < 20 {
        score += 6.0;
    }

    // Harmonic coupling with lookahead: if the next item fits exactly into the
    // post residual, strongly favor this bin (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after the chain matters
            let chain_left = post_residual - next_item_size;
            score -= 12.0 - (chain_left as f64) * 0.15;
        } else {
            // next item won't fit here: mild penalty scaled by how far off
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.08;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count <= 1 && post_residual <= bin_capacity / 2 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual, so its
    // raw score is already high. Add extra penalty so new bins are opened only
    // when no open bin gives a decent fit; relax slightly as stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 - 10.0 * progress;
        // opening a new bin is fine if the item is huge (little waste anyway)
        if item_size > bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    }

    // Prefer using bins whose residual deviates from the mean toward small
    // (consolidate fullness) when many bins are open.
    if open_bins_count > 3 {
        let dev = mean_residual - pr;
        if dev > 0.0 {
            score -= dev * 0.05;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold the minimum item size (1..=10) are pure waste — penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements leaving residual that can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize blocking the next item (creates near-dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> encourage consolidation,
    // mild reward for reusing existing bins.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64).sqrt();
    if bin_residual != bin_capacity {
        score -= pressure * 5.0;
    } else {
        // New-bin candidate: penalize mildly unless current bin fits badly.
        score += 15.0 + mean_residual * 0.1;
        // If no open bin fits well (only this new bin fits), allow opening.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Late in the stream, tighten packing: penalize wasted space more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step match: post_residual == next_item_size -> next item exactly fills bin
        score -= 40.0 * (1.0 - lookahead_gap / 60.0).max(0.0);
        // Bonus if next item fits exactly into the leftover (gap == 0)
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving space smaller than next item (dead space for next step)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fill
        score += 0.1 * post_residual as f64;
    }

    // Reward tight fits (small post_residual) nonlinearly
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Compare against mean residual: bins with residual below mean are "denser" -> prefer them
    score -= 0.6 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize new-bin candidate, unless current bins would leave excessive dead space
    if bin_residual == bin_capacity {
        let dead_space_penalty = if next_item_size > 0 && post_residual < next_item_size {
            0.0 // allow new bin if open bins would create unusable slivers
        } else {
            35.0
        };
        score += dead_space_penalty + 0.05 * open_bins_count as f64;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // This placement creates a sliver that next item cannot use; make new bin attractive
        score -= 5.0;
    }

    // Slight preference for consolidating into fewest bins early in stream
    if step_index as f64 / (total_items.max(1) as f64) < 0.3 {
        score += 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward low post-residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    } else if post_residual > 50 {
        score += 0.15 * (post_residual as f64 - 50.0); // large leftover is fine-ish
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item cannot use leftover: mild penalty proportional to gap
            score += 0.10 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer emptier bins slightly to consolidate
        score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // New-bin candidate handling: opening a new bin costs; only attractive when
    // no open bin fits well or residuals are globally fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Base cost of a fresh bin, discounted late in the stream or when
        // open bins are highly fragmented and item is large.
        let mut new_bin_cost = 30.0 - 15.0 * progress;
        if item_size > 60 && fragmentation < 0.4 {
            new_bin_cost -= 12.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            new_bin_cost -= 5.0; // fresh bin can host the pair
        }
        score += new_bin_cost.max(0.0);
    }

    // Slight bonus for packing into already-open bins vs. proliferation.
    if bin_residual < bin_capacity {
        score -= 1.0 + 0.02 * open_bins_count as f64;
    }

    // Small time-horizon modulation: early on, be conservative with tight fits
    // (future items may use the space); later, pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (0.5 + progress) - pr_norm * (1.0 - progress) * 0.6;
    score += poly * cap * 0.4;

    // Reward tight fits, stronger later in the stream
    score -= (1.0 - pr_norm).powi(3) * (10.0 + 40.0 * progress);

    // Penalize small dead space that cannot fit a typical next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.8 + 0.6 * progress);
        } else {
            score -= 3.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild pressure when many bins are open
    score += (open_bins_count as f64).sqrt() * 0.5 * pr_norm;

    // Bias toward using bins below mean residual (fill emptier bins less)
    score += (mean_residual - pr).abs() * -0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "usable" residue class (multiples of small denominators of capacity)
    // are favored because future items more likely fit exactly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Classify post_residual into harmonic classes via integer division.
    let class4 = post_residual / (bin_capacity / 4); // 0..=4
    let class5 = post_residual % 10;                 // last-digit residue class

    // Reward exact harmonic fits (residual is a clean fraction of capacity).
    let harmonic_bonus = match class4 {
        0 => 60.0, // perfect fit
        1 => 18.0, // residual <= 25%
        2 => 4.0,  // residual <= 50%
        3 => -6.0, // residual <= 75% (large leftover, likely still usable)
        _ => -10.0,
    };
    score -= harmonic_bonus;

    // Penalize "awkward" residues: leftover just above common item sizes
    // (items 1..100 unknown, but small odd residues are hard to fill).
    if post_residual > 0 && class5 != 0 && class5 < 3 {
        score += 8.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; mildly penalize tight fills that
            // strand the bin before the next item arrives.
            score += 6.0 * (1.0 - frac);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Early in the stream, prefer consolidating into few bins; later,
    // allow spreading (mean residual coupling).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - pr) * (0.3 + 0.4 * progress);

    // New-bin candidate: empty bin should only win when no open bin offers
    // a decent fit (post_residual == capacity means item_size == 0 there,
    // so score is capacity; anchor it with open-bin pressure).
    if bin_residual == bin_capacity {
        score = cap + open_bins_count as f64 * 0.5 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is correct
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (>=1..100 unknown distribution) become waste.
    // Penalize small nonzero post_residuals super-linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // dead-space severity: peaks for tiny gaps, fades for large gaps
        let dead = (1.0 - pr / bin_capacity as f64).max(0.0);
        score += dead * dead * 60.0;
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fills relative to bin capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    score += open_bins_count as f64 * 0.8;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (keeps bin states homogeneous), slight penalty otherwise.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 30.0 - gap * 2.0;
        } else {
            score -= 8.0;
        }
    }
    // If next item cannot fit in post_residual, this residual is likely dead space
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 20.0;
    }

    // New-bin candidate: neutral baseline, slightly below a badly wasted bin
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward closing a bin completely.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Chain fit: this placement enables a perfect follow-up.
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but imperfectly: reward proportionally to tightness.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * tightness;
        } else {
            // Next item cannot use the leftover: penalize dead space creation,
            // worse when the waste is large relative to mean residual.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(80.0);
            if post_residual < 10 {
                score += 50.0; // tiny unusable sliver
            }
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Prefer bins tighter than average (best-fit flavor relative to fleet state).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Penalize the brand-new empty bin candidate so we prefer reusing open bins,
    // unless the item is huge (little room for future pairing anyway).
    if bin_residual == bin_capacity {
        score += 300.0 - 2.0 * item_size as f64;
    }

    // Early in the stream, be slightly more willing to open bins (build diversity).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    if bin_residual == bin_capacity {
        score -= 100.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, especially near-exact.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    }

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small gaps are still usable by tiny items
    }
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.15; // wasteful large gap when item was small
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current open bins are crowded
    // or this bin's fit would be very poor.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < (item_size as f64 * 1.3);
        let poor_fit_elsewhere = post_residual as f64 > mean_residual * 0.9;
        if crowded && poor_fit_elsewhere {
            score -= 30.0;
        } else {
            score += 55.0; // default: prefer existing bins
        }
    }

    // Lookahead coupling: if the next item fits into this bin's post residual,
    // reward; if next item would exactly fill the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // next item won't fit here; mild penalty proportional to leftover waste
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Time horizon: early in stream, be more conservative with new bins
    // (many future items to fill them); late in stream, prefer closing out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    } else {
        score += progress * 5.0;
    }

    // Prefer filling bins with lower residual relative to the mean (reduce fragmentation).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Slight penalty for proliferating open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping over stream progress
    let mut score = pr;

    // Quadratic dead-space penalty: large residuals are fine, tiny residuals are wasted
    let dead = norm_pr * norm_pr;
    score += 40.0 * dead * (0.5 + 0.5 * progress);

    // Cubic coupling: penalize mid-range residuals more as stream progresses
    let mid = norm_pr * (1.0 - norm_pr);
    score += 25.0 * mid * mid * (1.0 - progress);

    // Exact-fit reward (smooth, not piecewise): strongly favor post_residual near 0
    let exact = (-norm_pr * 8.0).exp();
    score -= 30.0 * exact;

    // Lookahead: reward if next item fits the post-residual well
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_gap = (pr - n).abs() / cap;
        score -= 15.0 * (-fit_gap * 6.0).exp();
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (smooth coupling)
    score += 0.3 * (pr - mean_residual);

    // Slight preference for consolidating into fewer bins
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: penalize opening a new bin mildly, more early on
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: harmonic class 0 (post_residual % small divisors)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual % 10 == 0 {
        score -= 20.0;
    } else if post_residual % 5 == 0 {
        score -= 8.0;
    }

    // Dead-space penalty: tiny unusable residues
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly into this bin's leftover: strong reward
            let gap = post_residual - next_item_size;
            score -= 40.0;
            if gap == 0 {
                score -= 60.0; // chain of perfect fits
            } else if gap % 5 == 0 || gap % 10 == 0 {
                score -= 10.0;
            }
        } else if next_item_size <= bin_residual {
            // next item fits this bin only if we keep more room now
            score += 5.0;
        } else {
            // next item must go elsewhere regardless; mild reward for using space now
            score -= 5.0;
        }
    }

    // Integer-division thresholds on residual fraction of capacity
    let residual_class = post_residual / (bin_capacity / 4); // 0..=3
    match residual_class {
        0 => score += 10.0,  // nearly full bin: good
        1 => score -= 3.0,   // quarter left
        2 => score -= 1.0,
        _ => {}              // mostly empty
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when fit is poor
    if bin_residual == bin_capacity {
        // penalize new bin mildly; scale with how crowded open bins are
        score += 25.0 + 2.0 * open_bins_count as f64;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
        // if item is large relative to capacity, opening fresh bin is fine
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps are wasted unless next item fits.
    if post_residual > 0 {
        let usable = next_item_size > 0 && post_residual >= next_item_size;
        if !usable {
            // unusable gap: penalize proportionally to how "dead" it is
            let deadness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
            score += 60.0 * deadness * (post_residual as f64);
        } else {
            // gap that next item fits: reward
            score -= 25.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 80.0;
    }

    // Tight-fit reward: fraction of bin consumed
    let fill = (item_size as f64) / (bin_capacity as f64);
    score -= 40.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep neutral-ish baseline, penalize when open bins fit well
    if bin_residual == bin_capacity {
        score += 55.0;
        if open_bins_count == 0 {
            score -= 200.0;
        }
        // discourage opening new bins late in stream when mean residual is small
        if mean_residual > 0.0 && mean_residual < item_size as f64 + 15.0 {
            score += 20.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins
    if bin_residual != bin_capacity {
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item exactly matches post_residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: strongly favor bins whose post_residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // Next item could also fit here: reward tight chains.
            score -= 80.0 - gap.min(80.0);
        } else {
            // Next item won't fit; penalize leftover dead space relative to gap.
            score += gap * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let bad_fit = (post_residual as f64 - item_size as f64).abs();
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        // Penalize opening new bins normally; discount when residuals are large and fragmented.
        score += 220.0 - fragmentation * 180.0 - bad_fit * 0.3 - pressure * 40.0;
        // Early in stream, opening fresh bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
    }

    // Mild penalty for wasting a large bin on a small item.
    score += (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: penalize if the leftover space is too small for the next item (dead space),
    // reward if the next item could still fit afterwards.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when current open bins
    // are crowded (large mean residual is bad, small mean residual means bins are full).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Cheaper to open a new bin when existing bins are quite full.
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 25.0 * mean_fill * mean_fill;
        // If no open bin fits at all (fitting_bins_count == 0 means only this candidate), it's mandatory.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidating into open bins slightly less.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress;
    }

    // Mild penalty for leaving residuals in awkward mid-range zones (hard to fill later).
    if post_residual >= 10 && post_residual <= 20 {
        score += 3.0;
    }

    // Prefer bins with below-average residual (fuller bins) to consolidate waste.
    let residual_diff = mean_residual - bin_residual as f64;
    score += 0.05 * residual_diff;

    // Slight preference for bins that already carry the same-size load pattern.
    if bin_residual == item_size {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), non-linearly scaled.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: early on, keep bins flexible
    // (penalize tiny residuals more); late, pack tightly regardless.
    let flexibility = 1.0 - progress;
    score += 25.0 * flexibility * (1.0 - norm_pr).powi(3) * (pr / cap);

    // Dead-space penalty: residuals too small for any plausible item.
    let dead_threshold = 10.0;
    if pr < dead_threshold {
        score += (dead_threshold - pr) * (1.5 + 2.0 * progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let need = next_item_size as f64;
        if pr >= need {
            score -= 8.0 * (pr - need) / cap;
        } else {
            score += 6.0 * (need - pr) / cap;
        }
    }

    // Mild preference for bins with residuals above the mean (balance).
    score += 0.05 * (pr - mean_residual);

    // Slight bias against opening new bins when others fit.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual buckets by quarter-capacity
    let q = post_residual * 4 / bin_capacity; // 0..3
    match q {
        0 => score -= 25.0,               // near-perfect fit, reward strongly
        1 => score += 6.0,                // small dead space, mildly penalize
        2 => score -= 3.0,                // half-capacity residual is reusable
        _ => {}                           // large residual, neutral
    }

    // Reward post_residual that is an exact divisor-friendly class (multiple of 10)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 10 == 5 {
        score += 4.0;
    }

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect lookahead fit
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 12.0;
            }
            score -= (10.0 * next_item_size as f64) / (bin_capacity as f64);
            if slack < 10 {
                score += 15.0; // creates tiny dead space next step
            }
        } else {
            // next item won't fit here; prefer larger leftover unless huge
            if post_residual < 20 {
                score += 20.0; // dead space penalty
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / bin_capacity as f64);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + pressure * 5.0 + progress * 10.0;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0;
        }
        if item_size % 10 == 0 {
            score -= 4.0; // round item sizes pack well in fresh bins
        }
    }

    // Mild preference for tighter bins overall
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    // Gaps below 10 (min item size) are pure waste; gaps 10..30 are risky.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 30 {
        score += (30 - post_residual) as f64 * 1.8;
    } else {
        // Large leftover space is valuable; reward keeping it.
        score -= (post_residual as f64) * 0.25;
    }

    // Dead space that exactly fits the lookahead item is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap that can't fit the next item but is close in size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 30 {
        score += 12.0;
    }

    // Open bins pressure: discourage spreading across many bins; encourage
    // filling existing bins when the bin count is high.
    score += (open_bins_count as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: keep the empty-bin option neutral-to-slightly
    // costly so we only open new bins when fits are genuinely bad.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 0.2;
        // Late in the stream, opening fresh bins is less attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mean residual coupling: if open bins are already tight on average,
    // prefer bins with more room (diverge from mean).
    score += (mean_residual - bin_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            // Next item fits: reward exact match strongly, partial fit mildly.
            let gap = post - nxt;
            score -= 60.0 - gap.min(60.0);
            // Perfect chain (post_residual == next_item_size) is ideal.
            if gap == 0.0 { score -= 40.0; }
        } else {
            // Next item won't fit here: penalize wasted residual unless small.
            score += 0.5 * (nxt - post).min(50.0);
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 20.0;
    }

    // Reward tight fits relative to mean residual (below-average leftover is good).
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): only attractive when item is huge or no good fit exists.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if item_size >= 70 || next_item_size == 0 {
            score -= 10.0 + 20.0 * tightness;
        } else {
            // Discourage opening new bins for small/medium items when open bins exist.
            score += 45.0 - 30.0 * tightness;
        }
    }

    // Late in the stream, consolidate rather than open new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits with a nonlinear bonus.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio.powf(3.0);

    // Lookahead: if the next item fits into the post placement residual,
    // reward this bin (chain placement); otherwise penalize dead space
    // that the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_tight = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * chain_tight;
        } else {
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
        if fit_ratio > 0.5 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: brand-new empty bin. Only attractive if
    // existing bins are crowded or the fit would be poor everywhere.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let early = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 40.0 + 60.0 * (1.0 - crowding) * (1.0 - 0.5 * early);
        score += penalty;
        // If the item is large relative to capacity, a fresh bin gives a
        // clean layout for it and the lookahead item.
        if item_size as f64 / bin_capacity as f64 > 0.7 && fitting_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Prefer filling bins whose residual is already small relative to the
    // mean (compact the fleet, keep large residuals available).
    let res_frac = bin_residual as f64 / bin_capacity as f64;
    score += 20.0 * res_frac * res_frac;

    // Mild bonus for consolidating: fewer open bins is better late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * progress;

    // Discard micro-residuals that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = post + 0.015 * post * post / cap;

    // Non-linear polynomial coupling between post_residual and stream progress:
    // early on, tolerate slack; late in stream, punish leftover space quadratically.
    let slack_penalty = (post / cap).powi(2) * (1.0 + 3.0 * progress * progress) * 20.0;
    score += slack_penalty;

    // Cubic interaction: residual tightness vs progress
    let tightness = 1.0 - residual / cap;
    score += tightness.powi(3) * (10.0 + 30.0 * progress);

    // Dead-space avoidance: penalize post residuals too small for typical future items
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 2.5;
    }

    // Lookahead: reward if next item fits the post residual, scaled by progress
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= (1.0 - nxt / cap) * 8.0 * (1.0 + progress);
        } else {
            score += (nxt - post) / cap * 6.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // mild congestion reward for spreading load
        score -= (fitting_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // New-bin candidate: penalize unless the fit in existing bins is hopeless
    let is_new_bin = (bin_residual as u32 == bin_capacity) && (item_size as u32 <= bin_capacity);
    if is_new_bin {
        let waste = (cap - item_size as f64) / cap;
        score += 30.0 + 20.0 * waste * (1.0 + progress);
        // allow new bin late in stream when mean residual is low
        score -= progress * mean_residual * 0.3;
    }

    // Mean-residual alignment: prefer bins close to the average residual
    score -= (mean_residual - post).abs().powf(1.5) * -0.05;

    // Small open-bins regularization
    score -= (open_bins_count as f64).powf(0.5) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into residue classes
    // modulo 10 (capacity fractions). Small leftover classes are "dead space" -> penalize.
    let pr = post_residual;
    let class = pr % 10;
    // Penalize leftovers that are too small to ever be useful (1..=9 range classes)
    if pr > 0 && pr <= 9 {
        score += 12.0; // worst class: nearly-full bin with unusable sliver
    } else if pr <= 19 && pr >= 10 {
        score += 4.0;
    } else if pr >= 50 {
        // large leftover is fine, but only if it can host a future item
        score -= 2.0;
    }

    // Integer-division thresholds: can the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Chainability reward: stronger when leftover is "harmonically" compatible
            // (next item consumes most of the leftover)
            let fill = next_item_size as f64 / pr as f64;
            score -= 8.0 * fill;
            if pr % next_item_size.max(1) == 0 {
                score -= 3.0; // exact harmonic fit
            }
        } else {
            // Next item cannot use this leftover -> leftover likely becomes dead
            score += 5.0 + (next_item_size - pr) as f64 * 0.15;
        }
    } else {
        // Last item: prefer tightest fit overall
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin; reduced when open bins are congested
        let congestion = if open_bins_count > 0 {
            1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else { 1.0 };
        score += 20.0 - 10.0 * congestion;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 4.0; // fresh bin guarantees fit for next item
        }
    } else {
        // Reward tighter fits among existing bins (best-fit core)
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Progress-based mild preference to close out bins late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward filling a bin deeply relative to its capacity.
    score -= 15.0 * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 6.0 * progress);

    // New-bin candidate: penalize slightly by default so we only open when fits are poor,
    // but discount the penalty when the item is large or many bins are open.
    if bin_residual == bin_capacity {
        let next_bonus = if next_item_size > 0 && next_item_size <= post_residual { 8.0 } else { 0.0 };
        score += 12.0 + 0.15 * open_bins_count as f64 - next_bonus - 10.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual gap, reward keeping this bin viable.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 6.0;
    }

    // Slight preference for bins tighter than the mean residual.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect 2-step match: post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Penalize leftover dead space after the lookahead item.
            let dead = (post_residual - next_item_size) as f64;
            score += dead * (1.0 + dead / 50.0);
        } else {
