    // Late in the stream, prefer tightening existing bins even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0;

    // Prefer filling more crowded bins to consolidate.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that nearly fill the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    // (chained packing), penalize leaving a residual that is a near-miss
    // for the next item (dead space).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64) / (post_residual as f64).max(1.0);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * (1.0 - gap / (bin_capacity as f64));
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate logic: an empty bin gets a baseline penalty so it
    // only wins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 22.0 + 6.0 * (open_bins_count as f64).sqrt();
        // Late in the stream, be more reluctant to open new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    } else {
        // Mild preference for reusing bins as the stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress;
    }

    // Penalize bins with residuals far from the mean (keep residuals homogeneous
    // so future medium items fit somewhere).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Penalize very small unusable residuals only if next item cannot use them.
    if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize leftover space, with non-linear penalty on mid-range residuals
    let mut score = pr as f64;
    score += 30.0 * norm_pr * (1.0 - norm_pr) * (1.0 - progress);

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 25.0 * poly * (1.0 - norm_pr * norm_pr);

    // Reward tight fits (small post_residual) more strongly later in stream
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 8.0 * (gap / cap) * (1.0 + progress);
    }

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty proportional to number of open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Interaction with mean residual: prefer bins below mean residual (tighter)
    score += 5.0 * (norm_pr - mean_residual / cap).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0..10] is nearly unusable.
    if post_residual > 0 {
        let class = post_residual % 10;
        if class > 0 && class <= 3 {
            score += 12.0; // tiny unusable slivers are bad
        } else if class >= 8 {
            score -= 6.0; // near-multiple-of-10 residuals stay usable
        }
    } else {
        score -= 25.0; // perfect closure
    }

    // Integer-division thresholds: residual that still fits common sizes is valuable.
    if post_residual >= 40 {
        score -= 8.0;
    } else if post_residual >= 20 {
        score -= 3.0;
    } else if post_residual > 0 {
        score += 6.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 10.0;
            }
            score -= (slack.min(20)) as f64 * 0.3;
        } else {
            // next item can't use this bin's leftover; penalize proportional waste
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless open bins are badly fragmented
    // or this is a large item early in the stream.
    if bin_residual == bin_capacity {
        score += 30.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 50 {
            score -= 10.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 35.0; // open bins nearly full -> fresh bin is fine
        }
        if progress > 0.9 {
            score -= 5.0;
        }
    }

    // Mild preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item (1..100 range,
    // assume ~10 as effective floor) but nonzero.
    let dead_threshold = 9.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0; // heavy penalty for creating a tiny useless sliver
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Post-residual that can still fit the next item is valuable; penalize gaps
    // that cannot accommodate the lookahead item.
    if next_item_size > 0 {
        if (post_residual as f64) < next_item_size as f64 {
            score += 8.0; // gap too small for next item -> likely dead space
        } else {
            score -= 6.0; // gap remains useful for lookahead
        }
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing ones
    // (penalize the new-bin candidate which has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 20.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) + 10.0 * progress;
        // but if this bin is the last chance, opening new bin is fine
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than wasting it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins with lower residual relative to mean (tighter bins first).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Slight preference for large items into tight bins (best-fit flavor).
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item fits exactly or nearly exactly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack.min(60.0); // big reward, decaying with slack
            if slack < 1.0 {
                score -= 40.0; // exact match bonus
            }
        } else {
            // Next item cannot fit: penalize proportionally to wasted chain opportunity.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Penalize leaving tiny unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Reward tight fits relative to current residual (best-fit flavor).
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 25.0;

    // Coupling with mean residual: prefer bins whose residual is below mean (fill fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Progress-based pressure: later in stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (open_bins_count as f64) * 0.8;

    // New-bin candidate: keep it neutral-to-slightly-high unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.2;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space: residuals too small for the smallest possible item are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect closure is excellent
    }

    // Lookahead: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 8.0; // next item won't fit here; residual likely wasted
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate logic: an empty bin has perfect flexibility but costs a bin.
    if bin_residual == bin_capacity {
        // Encourage reusing open bins when they fit reasonably well.
        let waste = (bin_capacity - item_size) as f64;
        score = waste + 15.0;
        // Early in the stream, opening bins is cheap and useful for future flexibility.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If many open bins already exist, avoid opening yet another unless necessary.
        score += 0.8 * open_bins_count as f64;
    }

    // Global residual pressure: when mean residual across open bins is large,
    // prefer placing into bins (consolidate) rather than spreading.
    if bin_residual < bin_capacity {
        score += 0.15 * (mean_residual - post_residual as f64);
    }

    // Slight preference for larger residuals late in the stream (keep flexible bins alive).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Base: reward tight fits (small post_residual) with non-linear decay
    let tight = 1.0 - (pr / cap);
    score -= 40.0 * tight * tight;

    // Lookahead coupling: bonus if next item exactly fills post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let exact = 1.0 - ((pr - nxt).abs() / cap);
        score -= 25.0 * exact * exact * exact;
        // Penalize leaving residual that is awkwardly close-but-smaller than next item
        let waste_gap = (nxt - pr) / cap;
        if waste_gap > 0.0 {
            score += 18.0 * waste_gap * waste_gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - pr / cap);
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the fullest (smallest residual)
        score += 5.0 * (pr / cap) * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    if bin_residual == bin_capacity {
        score += 45.0 + 60.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
        // Allow new bin if mean residual is already fragmented
        score -= 20.0 * (mean_residual / cap) * (mean_residual / cap);
    }

    // Stream-progress coupling: later in stream, accept looser fits less willingly
    score += 10.0 * progress * (pr / cap);

    // Mild penalty for residual near half-capacity (dead space zone)
    let half_dev = (pr - cap * 0.5).abs() / cap;
    score += 6.0 * (1.0 - half_dev * half_dev);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets
    let r_mod = post_residual % 10;
    let r_class = (post_residual / 10) as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Penalize residuals that fall into "dead zone" classes (e.g. 1..9 mod 10 are hard to fill)
    if r_mod >= 1 && r_mod <= 4 {
        score += 6.0 + r_class * 0.5;
    } else if r_mod >= 6 && r_mod <= 9 {
        score += 2.0;
    } else if r_mod == 0 {
        // perfectly divisible residual is attractive
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this bin strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 12.0 + (slack as f64) * 0.3;
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space the next item can't use
        score += (post_residual as f64) * 0.25;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would be badly fragmented
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 15.0;
        // but if the item is large, a fresh bin is fine
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        // late in stream, prefer reusing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins with below-mean residual (keeps tight bins tight, empties big holes)
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.15;

    // Scale by number of open bins: many open bins -> discourage adding fragmentation
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }

    // Integer-division threshold: harmonic classes of item_size
    let item_class = item_size / 20;
    match item_class {
        0 => score -= 1.0,          // tiny item: flexible
        1 => {},                    // small
        2 => score += 1.0,          // medium
        _ => score -= 3.0,          // large: place it, avoid stranding
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // --- Strict dead-space avoidance ---
    // A leftover gap that the lookahead item cannot use is "dead space".
    // Penalize it progressively the more it falls short of next_item_size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        score += 10.0 + shortfall * 0.6;
    }

    // Gaps below the minimum conceivable item size (1..=4) are almost surely dead.
    if post_residual > 0 && post_residual <= 4 {
        score += 15.0;
    }

    // Reward near-perfect fills (tight packing) with a non-linear bonus.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill > 0.85 {
        score -= 6.0 * (fill - 0.85) / 0.15;
    }

    // Coupling with mean residual: leaving this bin far below the mean residual
    // concentrates space elsewhere; mildly reward balancing when it helps.
    if !is_new_bin {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // --- Open-bins pressure ---
    // With many open bins, strongly discourage opening yet another bin.
    if is_new_bin {
        let pressure = 2.0 + 1.5 * open_bins_count as f64 + 4.0 * progress;
        score += pressure;
        // Opening a new bin is only attractive if no open bin fits tightly.
        if fitting_bins_count > 0 {
            score += 5.0;
        }
    } else {
        // Last-chance bin: if this is the only bin that fits, use it.
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
        // Mild reward for consolidating when bin count is high.
        if open_bins_count > 3 {
            score -= 0.5 * open_bins_count.min(10) as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, strongly reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // Next item fits in post_residual: mild reward (chain continuation).
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 10.0;
    }
    // Next item would NOT fit here: dead space risk, penalize proportionally.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Relative-to-mean coupling: prefer bins with less residual than average
    // (pack tight bins first, keep roomier bins for future items).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when a decent fit exists among open bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from stream length.
        score += 20.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // If next item is large and this bin is fresh, opening is more attractive.
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 15.0;
        }
        // Many open bins with slack: discourage adding another.
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fill reward: leave nothing usable behind.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: reward residuals that exactly fit the next item,
    // penalize residuals that are just barely too small for it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            score -= 0.2 * next_item_size as f64;
        }
    }

    // Tightness reward: smaller relative waste gets priority.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tightness;

    // Penalize creating tiny unusable slivers (dead space < smallest item).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Many open bins: encourage consolidation into fuller bins.
    if open_bins_count > 4 {
        score -= 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Time horizon: early in the stream, be picky (penalize loose fits);
    // late in the stream, just fill anything.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.3 * post_residual as f64;
    score -= progress * 0.1 * item_size as f64;

    // New-bin candidate: only attractive when no open bin fits well
    // (fresh bin keeps full residual); otherwise discourage.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 300.0;
        } else {
            score += 150.0 + 0.5 * item_size as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling: waste matters more as the stream progresses
    let progress_coupling = progress * progress;
    score += progress_coupling * pr * norm_pr * 2.0;

    // Penalize residuals that are too large to be useful later, smoothly
    let dead_zone = (norm_pr - 0.35).powi(2);
    score += 12.0 * dead_zone * (0.5 + progress);

    // Lookahead: reward bins whose post residual accommodates the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = pr - nxt;
        if fit_next >= 0.0 {
            score -= 6.0 * (1.0 - (fit_next / cap).abs()) * (1.0 - progress);
        } else {
            score += 2.0 * (-fit_next / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // New-bin candidate handling: mildly penalize opening new bins early,
    // allow it late or when open bins are crowded
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 3.0 + 10.0 * (1.0 - progress) * (1.0 - crowding) - 4.0 * progress;
    }

    // Mild penalty tied to mean residual dispersion
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "friendly"
    // multiples / near-divisors of common item sizes (mod arithmetic).
    let class = post_residual % 10;
    let class_bonus = match class {
        0 => 12.0,           // residual exactly divisible: highly reusable
        5 => 6.0,            // half-class
        2 | 8 => 3.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division threshold: small leftovers are dead space.
    if post_residual < 10 {
        score += 30.0; // unusable sliver -> heavy penalty
    } else if post_residual <= 15 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained harmonic pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let rem2 = post_residual - next_item_size;
            // reward small leftover after the chain
            if rem2 % 10 == 0 { score -= 8.0; }
            score += rem2 as f64 * 0.3;
        } else {
            // next item cannot follow here; slight penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate handling: prefer new bin only when all open fits are bad.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 25.0;
        // discount when stream is early (room to consolidate later)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // discount if open bins are crowded (mean residual low)
        score -= (cap - mean_residual).max(0.0) * 0.1;
    } else {
        // prefer tighter fits among open bins: reward small post_residual
        score -= (cap - pr) * 0.05;
        // mild penalty for spreading across many bins
        score += open_bins_count as f64 * 0.3;
    }

    // Modulo coupling between item size and residual: items near half/quarter
    // capacity harmonize with residual classes.
    let h = item_size % 25;
    if h == 0 && post_residual % 25 == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are wasted.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Penalize unusable gaps more aggressively as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64) * 40.0 * (0.5 + progress);
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins below mean residual (fill emptier bins less).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 120.0;
        } else {
            score -= (1.0 - slack as f64 / post_residual as f64) * 40.0;
        }
    }

    // New-bin candidate: prefer it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 2.0;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Leftover after the next item would fit: penalize the excess dead space.
        let excess = (post_residual - next_item_size) as f64;
        score -= 30.0;
        score += excess * 0.9;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize small post_residual (dead space)
        // more strongly when it's far below the next item size.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.35;
    }

    // Reward bins whose residual is below the mean (tighter bins get filled first).
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.5;
    } else {
        score += (resid_f - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers (< 10) that likely become dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Late in the stream, tighten packing: prefer fuller placements.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * resid_f * 0.2;

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count >= 2 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasting residual.
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // Prefer bins with below-mean residual (concentrate waste in few bins).
    score += 3.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Time horizon: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, penalize more later.
        score += 15.0 + 30.0 * progress;
        // But allow new bin if item is huge and no tight open fit exists.
        if item_size > bin_capacity / 2 && post_residual < 20 {
            score -= 20.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Slight preference for bins with larger residual when many bins open.
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth polynomial coupling: post_residual weighted by a progress-dependent factor.
    // Early on, prefer filling bins tightly (small post_residual matters more);
    // later, tolerate leftovers slightly to keep bins balanced.
    let tightness = 1.0 + 0.6 * progress * progress - 0.2 * progress;
    score *= tightness;

    // Non-linear quadratic penalty on large post_residual relative to capacity.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    score += 8.0 * norm_pr * norm_pr * cap;

    // Reward near-perfect fits via a smooth bump: exp-like decay on post_residual.
    score -= 12.0 * (-(pr * pr) / (2.0 * 25.0)).exp();

    // Penalize bins whose residual is far from the mean residual (imbalance),
    // smoothly scaled by number of open bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // Last-chance bin: strongly favor using it (subtract), smooth in progress.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 6.0 * (-(gap * gap) / (2.0 * 36.0)).exp();
        // If next item won't fit here anyway, slight penalty for wasting big residuals.
        if post_residual < next_item_size {
            score += 2.0 * norm_pr;
        }
    }

    // New-bin candidate: make it moderately attractive when open bins are crowded,
    // but discourage needless proliferation early.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).ln().max(1.0);
        score = 5.0 + 8.0 * (1.0 - progress) - 4.0 * crowd * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 25.
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Dead-space penalty: residuals in awkward classes (1..9 mod 10 that can't
    // fit typical small items) are penalized; exact multiples of 10 are favored.
    if post_residual > 0 {
        if r10 == 0 {
            score -= 8.0; // clean class: likely reusable by 10-multiples
        } else if r10 >= 7 {
            score -= 3.0; // near-multiple class, moderately reusable
        } else {
            score += (9 - r10) as f64 * 0.8; // awkward dead space
        }
        if r25 == 0 && post_residual >= 25 {
            score -= 4.0; // quarter-capacity harmonic class
        }
    }

    // Perfect fit bonus: harmonic resonance with capacity.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let nr10 = next_item_size % 10;
            let pr10 = post_residual % 10;
            if nr10 == pr10 {
                score -= 6.0; // same harmonic class as next item
            }
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item cannot use this bin's remainder: penalize large remainders more
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless post_residual is huge).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty-bin call gets a baseline that scales with
    // stream progress and current bin count; discourage hoarding many open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * (0.9 + 0.3 * progress) + open_bins_count as f64 * 2.0;
        // still allow opening when the item is huge relative to capacity fraction
        let frac = item_size as f64 / bin_capacity as f64;
        let bucket = (frac * 4.0).floor() / 4.0; // integer-division-like threshold
        score -= bucket * 20.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // pair the next item into the fresh bin
        }
    }

    // Mild global pressure: prefer tightening mean residual usage.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (>=1) can
    // use well are punished super-linearly. A tiny gap (< 10) is essentially
    // wasted capacity; a moderate gap is fine if it can host a small item.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual <= 30 {
        // Mid-range gap: mild penalty scaled by how "unusable" it likely is
        // relative to the lookahead item.
        score += (30 - post_residual) as f64 * 0.8;
    } else {
        // Large gaps are healthy; reward them slightly.
        score -= (post_residual - 30) as f64 * 0.3;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward this placement (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 25.0;
        } else {
            score -= 10.0 / slack.sqrt().max(1.0);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item cannot follow here; penalize proportionally to the miss.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins, especially as bin count grows.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * 3.0;

    // Last-chance bonus: if this is the ONLY bin that fits, prefer using it
    // over opening a new bin unless the dead space is catastrophic.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when the
    // item would create severe dead space in every existing bin.
    if bin_residual == bin_capacity {
        // Fresh bin: post_residual == capacity - item_size, large gap is
        // natural early on. Slight penalty grows with stream progress so we
        // consolidate late rather than proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 5.0 + progress * 15.0;
        // But if opening a new bin gives a much better post-fit for the
        // lookahead item than any existing bin, that is already reflected
        // in the lookahead term above.
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small dead space, non-linear).
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // 2-step lookahead: reward when post_residual matches next item size well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let gap = post - nxt;
            // Perfect match (next item exactly fills leftover) -> big reward.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64).powi(3);
            // Extra reward if next item fits perfectly (gap small).
            if gap <= 10.0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit in the leftover: mild penalty scaled by wasted potential.
            score += (nxt - post).min(30.0) * 0.5;
        }
    }

    // Compare post_residual against mean residual: leaving residual far below
    // mean creates unusable fragmentation.
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score += diff * 0.3;
    } else {
        score -= (-diff) * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or many bins are open (avoid bin proliferation).
    if bin_residual == bin_capacity {
        let load_ratio = item_size as f64 / bin_capacity as f64;
        score += 45.0 - 40.0 * load_ratio;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Slight preference to fill older/bins when many are open (consolidation).
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Early in the stream, be more tolerant of opening bins; late, consolidate.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Penalize dead space: post_residual below a "useless threshold" is wasted.
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits with a nonlinear bonus.
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * fill_ratio * 12.0;

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 10.0 + (gap as f64).max(0.0) * -0.5;
    }
    // If next item does NOT fit here, mild penalty for chaining awkwardness.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: prefer bins where this item fits snugly anyway.
        score += 1.5;
    }

    // Global state coupling: if mean residual is high, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > item_size as f64 {
        score -= (mean_residual - item_size as f64) * 0.3 * (0.5 + progress);
    }

    // Time horizon: late in the stream, discourage opening new bins.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 20.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        score += new_bin_penalty;
        // Exception: allow new bin early when item is huge and nothing fits well.
        if item_size > 70 && progress < 0.2 {
            score -= 25.0;
        }
    }

    // Small dispersion-aware nudge: prefer bins deviating below mean residual
    // (they are "tighter" and better to consolidate into).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.2;
    } else {
        score += (res_f - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - pr / cap; // how full the bin becomes
    let tight_poly = tightness * tightness * (3.0 - 2.0 * tightness); // smoothstep
    // reward tight fits, amplified as stream progresses
    score -= 30.0 * tight_poly * (0.5 + x);
    // polynomial coupling: dead space penalty grows non-linearly with progress
    let dead = pr / cap;
    score += 40.0 * dead * dead * (0.3 + 0.7 * x);
    // last-chance bin: strong bonus to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // lookahead: if next item fits in post_residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 * (1.0 - (next_item_size as f64 / cap));
    }
    // new-bin candidate: prefer it when open bins are mostly full on average
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / cap;
        score -= 10.0 * mean_fill * mean_fill - 5.0 * x;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into modulo buckets.
    // Residuals that are "harmonically compatible" with common item sizes (divisible
    // by 10, or >= 2*next_item_size) are less dead than awkward small remainders.
    let harmonic_class = if post_residual == 0 {
        0 // perfect fit: best possible outcome
    } else if post_residual % 10 == 0 {
        1 // round residual: reusable by typical items
    } else if post_residual % 5 == 0 {
        2 // half-round: mildly reusable
    } else {
        3 // awkward remainder: likely dead space
    };
    score += harmonic_class as f64 * 2.5;

    // Perfect fit reward: strong subtraction so exact closures win.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item can fit into the post residual, reward
    // this placement (chaining). Scale reward by how well the next item divides
    // the remaining space (harmonic divisibility).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        let div = post_residual % next_item_size;
        if div == 0 {
            score -= 12.0; // next item exactly closes the bin afterwards
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize proportionally to wasted potential.
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.4;
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly favor it
    // over opening a new bin (unless the residual is huge, i.e. bin is nearly empty).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: empty bin has all its capacity as residual. Prefer using
    // existing bins unless this item is large and existing residuals are fragmented.
    if bin_residual == bin_capacity {
        // New bin penalty grows with number of open bins (avoid bin proliferation),
        // but shrinks if the item is big relative to mean residual (poor fits elsewhere).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        score += 18.0 + open_bins_count as f64 * 0.8 - fragmentation * 0.5 - progress * 5.0;
    }

    // Prefer packing into bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.15;

    // Mild penalty for leaving very small unusable residues (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - pr) * 8.0; // dead space of 1..=10 is nearly unusable
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit reward
    } else {
        // larger leftovers are reusable; mild diminishing penalty
        score += (pr / (bin_capacity as f64)).sqrt() * 4.0;
    }

    // Reward tight fits relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Open-bins pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean residual context: prefer bins far below mean residual (consolidate slack)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base cost of opening a bin, reduced late in stream
        score = 60.0 - progress * 10.0 + open_bins_count as f64 * 0.5;
        if post_residual >= item_size && post_residual <= 10 {
            score -= 5.0; // fresh bin leaves usable space for next item
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // discourage new bin if a last-chance bin exists
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * (1.0 + 0.01 * (post_residual as f64 / bin_capacity as f64));

    // 2-step lookahead: strongly reward bins where the NEXT item also fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: post_residual - next_item_size becomes the future dead space.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 15.0 + 0.8 * chain_waste;
            // Perfect chain (item exactly fills, then next fills rest) gets extra reward.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Next item cannot follow in this bin: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(40.0);
        }
    }

    // Relative to mean residual: bins with residuals far below mean are "tight" —
    // using them for large items is efficient; keep loose bins for small future items.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): only attractive when item is large relative
    // to capacity or no good open fit exists.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.6 {
            score -= 8.0 * fill_frac;
        } else {
            score += 10.0 * (1.0 - fill_frac);
        }
        // More open bins -> less eager to open another.
        score += 1.5 * open_bins_count as f64;
    }

    // Late in the stream: consolidate harder, avoid leaving fragmented residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space relative to lookahead: penalize proportionally to unusable gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.35 * gap;
    }

    // Tight fit bonus: near-perfect packing is always desirable.
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate handling.
    if is_new_bin {
        let base_penalty = 20.0 + 0.4 * open_bins_count as f64;
        // Late in the stream, prefer closing out existing bins over spawning new ones.
        let late_penalty = 30.0 * progress;
        // If the item is huge and would leave a tiny remainder, opening fresh is fine.
        let tight_open = if post_residual <= 10 { 25.0 } else { 0.0 };
        score += base_penalty + late_penalty - tight_open;
        // If current item would fill the fresh bin nearly exactly, reward it.
        if post_residual <= 2 {
            score -= 40.0;
        }
    } else {
        // Prefer bins below mean residual (consolidating waste into few bins).
        let dev = mean_residual - post_residual as f64;
        score += 0.10 * dev;
    }

    // Mild global pressure: many open bins -> tighten selection.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly favor small post_residual, super-linearly.
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness * tightness * tightness;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly (poly-quadratic growth).
    let prog_term = progress * progress * (1.0 - progress);
    score += 12.0 * (post / cap) * (1.0 - 4.0 * prog_term);

    // Penalize bins whose residual is far from the mean (fragmentation avoidance).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev.abs();

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate: penalize opening a new bin, less so early or when
    // post_residual would be too small to be useful for the next item.
    if bin_residual == bin_capacity {
        let waste = if next_item_size > 0 { (post - next_item_size as f64).max(0.0) } else { post };
        score += 14.0 + 10.0 * progress - 0.15 * waste;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 16.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here anyway; slight penalty for stranding space.
        score += 2.0 * (1.0 - post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 measure "wasted fraction"
    let r = post_residual % 10;
    score += (r as f64) * 0.35; // dead-space residue penalty

    // Perfect fits are golden
    if post_residual == 0 {
        score -= 60.0;
    }
    if post_residual <= 3 {
        score -= 20.0;
    }

    // Harmonic class of the residual: which capacity-fraction band does it land in?
    let cap_frac = post_residual as f64 / bin_capacity as f64;
    if cap_frac <= 0.05 {
        score -= 15.0; // near-full bin, excellent
    } else if cap_frac <= 0.15 {
        score -= 5.0;
    } else if cap_frac > 0.5 {
        score += 12.0; // leaving a half-empty bin wastes capacity
    }

    // Integer-division threshold on next_item_size vs post_residual: lookahead chaining
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // next item fills this bin exactly
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this residual: penalize by overshoot class
            let over = next_item_size - post_residual;
            score += (over % 10) as f64 * 0.3 + (over / 10) as f64 * 1.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when item is huge relative to capacity
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 {
            score -= 25.0;
        } else if frac > 0.5 {
            score -= 5.0;
        } else {
            score += 30.0 + 40.0 * (1.0 - frac); // small items should reuse open bins
        }
    }

    // Stream phase modulation: early on, be frugal with bins; late, consolidate
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += phase * 6.0 * (mean_residual / bin_capacity as f64 - 0.5).abs();

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild penalty when many bins already open (encourage consolidation)
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small nonzero gaps are nearly useless
    // (items are >= 1, but tiny gaps rarely get filled exactly).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0 + (10 - post_residual) as f64 * 20.0;
    }
    // Medium gaps (10..=20) are risky: only items <= gap can use them.
    if post_residual >= 10 && post_residual <= 20 {
        score += 40.0;
    }
    // Large comfortable gaps are mildly attractive.
    if post_residual > 40 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Open-bin pressure: discourage proliferation of bins, scaled by stream position.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
    }

    // Relative tightness: prefer bins that become tighter than the average.
    if mean_residual > 0.0 {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // New-bin candidate bias: make an empty bin slightly less attractive unless
    // the fit is poor (its post_residual is large, so base score already high).
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: reward bins where the next item fits the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // perfect chain fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize dead space relative to next item size
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.3 * gap;
        }
    }

    // Compare post_residual against mean residual: avoid making bin outliers
    let pr = post_residual as f64;
    if pr > mean_residual + 20.0 {
        score += 0.25 * (pr - mean_residual);
    } else if pr < mean_residual - 20.0 {
        score -= 0.15 * (mean_residual - pr);
    }

    // Last-chance bin bonus: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline slightly worse than a good existing fit
        score += 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin is attractive if item + next item pack well together
            let pair = (item_size + next_item_size) as f64;
            if pair <= bin_capacity as f64 {
                score -= 12.0 * (1.0 - pair / bin_capacity as f64);
            } else {
                score += 8.0;
            }
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // avoid bin proliferation
        score += 0.5 * open_bins_count as f64;
    }

    // Mild tightness reward: smaller relative leftover is better
    score += 0.05 * (post_residual as f64 / bin_capacity as f64) * 100.0 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Penalize leaving dead space that nothing small can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Post residual can't host next item: mild penalty scaled by wasted potential.
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 8.0 * waste;
            // If next item exactly fits this bin's residual, chain-packing is attractive.
            if next_item_size == bin_residual {
                score -= 10.0;
            }
        }
    }

    // Last-chance bin: strongly prefer when this is the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        // Penalize new bins early or when open bins still have slack.
        score += 40.0 + 30.0 * (1.0 - progress) + 25.0 * (1.0 - crowding);
        // Allow new bins late in the stream or when mean residual is small.
        if progress > 0.7 && mean_residual < item_size as f64 {
            score -= 45.0;
        }
    }

    // Prefer bins with residual near the item (best-fit flavor) via non-linear coupling.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Global state: when many bins are open, encourage consolidating into fuller bins.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fullness * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: as stream progresses, be more aggressive about tight packing.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: tight fit preferred (post_residual minimized), with non-linear sharpening.
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // as the stream progresses, dead space becomes increasingly costly.
    let coupling = norm_post.powi(2) * (0.5 + 3.0 * progress * progress) * cap * 0.5;
    score += coupling;

    // Cubic term: mid-stream, strongly penalize large residuals (wasted capacity).
    score += norm_post.powi(3) * cap * (1.0 - progress) * 0.3;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly, more so early/mid stream when open bins exist;
    // relax late in the stream where consolidating waste in a fresh bin can pay off.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 8.0 + 6.0 * (1.0 - progress) - 2.0 * (open_bins_count as f64).ln().max(0.0);
        score += new_bin_penalty.max(2.0);
        // If next item is small and would fit in leftover of a tight placement, discourage new bin.
        if next_item_size > 0 && (next_item_size as f64) <= (cap - item_size as f64) {
            score += 4.0;
        }
    }

    // Lookahead synergy: reward bins whose post_residual fits the next item.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 + 4.0 * (1.0 - (post - next_item_size as f64) / cap);
    }

    // Slight preference for bins with below-mean residual (denser bins).
    score += 0.5 * ((mean_residual - post) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit core)
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: quantize into capacity-fraction buckets.
    // Residuals in the "dead zone" (1..10) are nearly useless -> heavy penalty.
    let dead = if post_residual > 0 && post_residual < 10 { 1 } else { 0 };
    score += dead as f64 * 40.0;

    // Perfect / near-perfect fit reward via modulo harmonic classes
    if post_residual == 0 {
        score -= 100.0; // exact closure
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Integer-division harmonic class: post_residual in coarse 10-wide classes.
    // Bins whose residual class matches the next item's size class get a bonus
    // (this bin is likely to serve the lookahead item too).
    let pr_class = post_residual / 10;
    let nx_class = (next_item_size as u32).saturating_sub(1) / 10;
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + (10 - (pr_class as i32 - nx_class as i32).abs()) as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // lookahead cannot use leftover: mildly penalize small leftovers
        if post_residual < 20 {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Crowding pressure: when many bins are open, prefer reusing tight bins
    // over spreading; when few bins, tolerate opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += crowd * 0.5 * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // Penalize opening a bin unless fitting is scarce or item is huge.
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 60.0 + 2.0 * fitting_bins_count as f64 };
        let big_item = if item_size > bin_capacity / 2 { -20.0 } else { 0.0 };
        score += scarcity + big_item + 5.0 * (1.0 - progress);
    } else {
        // Reward using existing bins, more for tighter fits relative to capacity.
        let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * tightness;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is an outlier-tight bin; using it consolidates waste.
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    } else {
        score += (-diff) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear "dead zone").
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 6.0;
    }

    // Reward tight fits (post_residual near zero or large enough to be reusable).
    if dead == 0.0 {
        score -= 25.0;
    } else if dead >= 10.0 {
        score -= 5.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual as f64 && post_residual > 0 {
        score += 10.0;
    }

    // Mild preference for bins below mean residual (consolidate space).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New empty bin candidate: penalize unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect chaining: bin fully consumed by next item
        } else if next_item_size <= post_residual {
            // partial lookahead fit: reward proportional to how much of the residual is used
            let used_frac = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * used_frac;
            // bonus if the chain leaves a small, still-usable remainder
            let chain_rem = post_residual - next_item_size;
            if chain_rem <= 10 {
                score -= 10.0;
            } else {
                score += 0.3 * chain_rem as f64;
            }
        } else {
            // next item cannot use the residual: penalize dead space relative to next size
            let gap = (next_item_size - post_residual) as f64;
            score += 0.2 * gap.min(50.0);
        }
    }

    // Compare against mean residual: bins tighter than average are more valuable to fill now
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 15.0 * (1.0 - rel); // tighter-than-average bin: favor
        } else {
            score += 8.0 * (rel - 1.0).min(2.0); // looser-than-average: slight penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless nothing fits well
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 50.0;
        score += if bad_fit { 60.0 } else { 20.0 };
        // lookahead exception: if next item chains well with this item in a fresh bin, allow it
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 45.0;
        }
    }

    // Early stream: be slightly more willing to open bins for structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score -= 3.0;
    }

    // Penalize very small unusable post-residuals only if no lookahead use exists
    if post_residual > 0 && post_residual < 10 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Penalize large leftover space wasted on small items; reward tight fits.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 0.9 * tightness * (item_size as f64);

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Dead space relative to next item is worse late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 4.0 + 6.0 * progress;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: with many open bins, prefer consolidating into fuller bins.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.15 * mean_gap;

    // Penalize opening a new bin unless the item is large and stream is young.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        let openness = (1.0 - progress).max(0.0);
        score += 12.0 - 18.0 * item_frac * openness;
        // A new bin is attractive if the next item also fits well with this one.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear penalty growth
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = norm_pr * (t - 0.5) * (1.0 - t) * 2.0;
    score += 60.0 * coupling;

    // Reward tight fits more strongly as stream progresses (smooth ramp)
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 50.0 * t);

    // Last-chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins far below mean residual (wasteful choice) via smooth term
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.5 * gap;
        if gap < 1.0 {
            score -= 20.0;
        }
    } else {
        // Last item: strongly prefer minimal post_residual
        score -= 10.0 * tightness;
    }

    // Mild penalty on proliferation of open bins late in the stream
    score += 0.5 * (open_bins_count as f64) * t * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse integer division thresholds
    let item_class = item_size / 25;               // 0..3 (small, medium, large, huge)
    let next_class = (next_item_size / 25) as i64; // 0..3, or 0 for sentinel 0

    // Perfect fit is a gift: reward strongly
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Near-perfect fits in low harmonic classes
    if post_residual <= 3 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Dead-space penalty: residual that no item class can realistically use.
    // Items are >= 1, but usable chunk classes are ~25-wide; residual below
    // the next item's class threshold is likely waste.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
        // Harmonic pairing: post_residual exactly complements a future small item
        if post_residual >= next_item_size && post_residual <= next_item_size + 5 {
            score -= 60.0;
        }
        // Modulo arithmetic on capacity fractions: residual in [1,10] is a
        // "sliver" class — hard to fill; penalize proportionally to progress.
        let sliver = (post_residual % 25) < 10 && post_residual > 0;
        if sliver {
            let progress = step_index as f64 / (total_items.max(2) as f64);
            score += 40.0 * progress;
        }
        // If next item pairs perfectly with post_residual, big reward
        if post_residual == next_item_size {
            score -= 300.0;
        }
    } else {
        // Last item: only perfect fit matters
        if post_residual == 0 {
            score -= 500.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Prefer bins with residual close to mean (keep balance), slight pull
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Coupling: huge items (class 3) prefer the emptiest bin; small items
    // should go into tight bins (best-fit behavior).
    match item_class {
        0 => score += post_residual as f64 * 0.5,        // small item: best-fit
        1 => score += post_residual as f64 * 0.3,
        2 => score -= 10.0,
        _ => score -= (bin_capacity - bin_residual) as f64 * 0.2, // huge: emptiest bin
    }

    // New-bin candidate handling: it's a fresh empty bin (residual == capacity).
    // Only attractive if no open bin fits well (many fitting bins = prefer them).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Bias toward existing bins unless they're all bad fits
            score += 120.0 + (fitting_bins_count as f64) * 5.0;
        } else {
            score -= 50.0;
        }
        // Late in the stream, opening fresh bins is fine for huge items
        let progress = step_index as f64 / (total_items.max(2) as f64);
        if item_class == 3 && progress > 0.5 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are tiny are excellent
    // (near-perfect packing), reward them strongly.
    if post_residual == 0 {
        score -= 50.0; // perfect fit, best possible outcome
    } else if post_residual <= 5 {
        score -= 30.0; // practically dead space, very good
    } else if post_residual <= 15 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 3.0;
    } else {
        // Large leftover: penalize extra if it cannot host the lookahead item
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0; // dead space relative to the known future demand
        }
    }

    // If the residual after placement exactly accommodates the next item,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 - slack * 0.15; // tighter chain fits get bigger rewards
        if slack < 10.0 {
            score -= 4.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual <= 20 {
            score -= 10.0; // good fit in the only option: take it decisively
        }
    }

    // Open-bin pressure: mildly discourage proliferation of bins, but never
    // override a clearly good fit in an existing bin.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when item is large and no
        // tight fit exists; otherwise penalize so existing bins are preferred.
        let base_penalty = 18.0 + 10.0 * (1.0 - progress);
        score += base_penalty;
        if item_size >= 60 && post_residual <= 40 {
            score -= 10.0; // big items are fine to start a fresh bin with
        }
        if fitting_bins_count == 0 {
            score -= 25.0; // nothing else fits: new bin is mandatory
        }
    } else {
        score += (open_bins_count as f64) * 0.3 * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins whose residual is close to the mean
    // (keeps the fleet homogeneous), avoid outliers creating stranded space.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.5;
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step match
        }
        // Penalize residuals too small for the next item (dead space risk)
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    }

    // Reward tight fits relative to mean residual of open bins.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score -= (mean_residual - pr) * 0.3;
    }

    // Penalize very small unusable post-residuals (dead space).
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral baseline, slightly favored early when few bins open,
    // penalized when many bins are open and mean residual is large (use them first).
    if bin_residual == bin_capacity {
        score = 45.0 + 2.0 * open_bins_count as f64 - mean_residual * 0.4;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // next item may pair with current one in a fresh bin
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward low post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 20.0;

    // Penalize leaving awkward residuals that likely fit nothing (dead space).
    if post_residual < 10 {
        score -= 15.0; // near-perfect fill, excellent
    } else if post_residual < item_size {
        // residual smaller than the smallest plausible next item => mostly dead space
        score += 8.0;
    }

    // Lookahead coupling: if next item fits the post residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // extra bonus if next item fits very snugly
        let snug = post_residual as f64 - next_item_size as f64;
        score -= (10.0 / (snug + 1.0)).min(6.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when open bins are crowded or the fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 0.5;
        if crowded && fitting_bins_count <= 2 {
            score -= 6.0; // allow opening fresh bins when existing ones are tight
        } else {
            score += 18.0 + 10.0 * (1.0 - progress); // discourage early bin proliferation
        }
    }

    // Global state: many open bins with large mean residual -> consolidate.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score += mean_residual - (post_residual as f64);
    }

    // Time horizon: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // normalized post-residual fraction
    let x = pr / cap;
    // base: prefer tight fits (small post_residual)
    let mut score = pr as f64;

    // smooth non-linear coupling: quadratic waste penalty grows with stream progress
    score += 40.0 * x * x * (0.5 + progress);

    // cubic term: dead space increasingly bad late in stream
    score += 25.0 * x.powi(3) * progress;

    // reward filling bins nearly exactly (post_residual near zero) more strongly over time
    score -= 30.0 * (1.0 - x).powi(4) * (0.3 + 0.7 * progress);

    // last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // new-bin candidate: penalize mildly early, allow opening when post_residual of fits is large
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 - 8.0 * progress;
        // attractive if mean residual of open bins is small (they're all tight)
        score += (mean_residual / cap).powi(2) * 20.0;
    }

    // lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        // next item cannot use leftover: penalize proportionally to wasted residual
        score += 5.0 * x * (1.0 - progress);
    }

    // mild penalty for spreading across many open bins
    score += (open_bins_count as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near multiples of common
    // item sizes (10, 20, 25, 50) are more reusable than odd dead space.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fit: strongly reward
    } else if pr <= 5 {
        -12.0 // tiny dead space, nearly perfect
    } else if pr % 50 == 0 || pr % 25 == 0 {
        -15.0
    } else if pr % 20 == 0 {
        -10.0
    } else if pr % 10 == 0 {
        -6.0
    } else if pr % 5 == 0 {
        -2.0
    } else {
        4.0 // awkward residue
    };
    score += harmonic_bonus;

    // Pairing with lookahead: reward when next_item_size divides or nearly
    // divides the post residual (mod-classes align).
    if next_item_size > 0 && (next_item_size as u32) <= pr {
        let n = next_item_size as u32;
        if pr % n == 0 {
            score -= 14.0;
        } else if pr % n <= 5 {
            score -= 8.0;
        } else {
            score += 3.0;
        }
    } else if next_item_size > 0 {
        // next item can't fit here; mild penalty if we'd strand the space
        score += (pr as f64) * 0.05;
    }

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate: keep it neutral-to-slightly-poor; only attractive
    // when current fit is truly bad (large awkward residual).
    if bin_residual == bin_capacity {
        let badness = (post_residual as f64 / cap).max(0.0);
        score = 20.0 + badness * 10.0 - harmonic_bonus.min(0.0) as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Tight-fill preference: fraction of bin used by this item.
    score -= (item_size as f64 / cap) * 8.0;

    // Stream progression: late in stream, prefer consolidating into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize extremes.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size (1..10
    // are unusable for small items; treat small gaps relative to typical item sizes)
    // are pure waste and must be heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space: unusable gap
    } else if post_residual < 20 {
        score += 25.0; // nearly-dead gap
    } else if post_residual < 35 {
        score += 8.0;  // awkward gap
    }

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with next item lookahead: if the next item fits exactly in the
    // post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use the leftover gap: gap likely becomes dead space
        if post_residual < next_item_size && post_residual < 30 {
            score += 15.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless dead space penalty dominates).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open bins pressure: with many open bins, encourage consolidation into
    // existing bins rather than spreading; with few open bins, opening a new
    // bin is less costly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * (4.0 + 6.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from number of open bins.
        score = 45.0 + bin_pressure;
    } else {
        // Tighter fit (smaller post_residual) already favored via base score;
        // add mild bonus for filling bins more than mean residual.
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // dead space penalty
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact chain fit is excellent.
            if post_residual == next_item_size {
                score -= 15.0;
            } else {
                let slack = (post_residual - next_item_size) as f64;
                // Reward chain fit, decaying with leftover slack after next item.
                score -= 12.0 - slack.min(20.0) * 0.3;
            }
        } else {
            // Next item cannot follow here: penalize proportionally to wasted chain potential.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 5.0;
    }

    // Compare against mean residual: bins tighter than average are good targets.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - res_f) * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early
    // in the stream or when many bins are open (fragmentation risk management).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_bonus = 8.0 * (1.0 - progress) + (open_bins_count as f64) * 0.3;
        score -= new_bin_bonus;
    }

    // Mild preference to keep the number of open bins bounded late in the stream.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item nearly fills the residual.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_frac * fill_frac;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, use it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless the current fit is bad
    // AND the leftover here is too small to plausibly host future items.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 22.0;
        // Early in the stream, fewer open bins -> prefer consolidation less strongly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * (1.0 - progress);
        // If many bins are open, a fresh bin can be useful for future large items.
        score -= (open_bins_count.min(20) as f64) * 0.6;
        // If this bin's post placement would leave a large awkward gap anyway, new bin is fine.
        if post_residual > 0 && (bin_residual - item_size) > 60 {
            score -= 10.0;
        }
        // Lookahead: if next item is large and won't fit typical residuals, fresh bin helps.
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 9.0;
        }
    } else {
        // Placing into an existing bin: penalize if the leftover would be unusable for the
        // lookahead item while another bin could host it.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count > 1 {
            score += 4.0;
        }
        // Reward keeping residuals aligned with the fleet mean (balance usable space).
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Small global regularization: mild preference for bins with lower residual (denser bins)
    // scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (minimize post_residual strongly);
    // later, tolerate residual slack slightly but still reward tight fits.
    let progress_weight = 0.35 + 0.65 * progress * progress;
    score += progress_weight * (pr / cap) * pr * 0.02;

    // Smooth dead-space penalty: residual that is too small to fit typical
    // future items is wasted; use a smooth quadratic in pr/cap.
    let r = pr / cap;
    score += 3.0 * (1.0 - r) * (1.0 - r) * r;

    // Lookahead coupling: if the next item fits the post residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize mildly, scaled by progress.
        score += 1.5 * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using the only bin that can fit.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // Mildly discourage spreading across many fitting bins.
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: opening a new bin is penalized early,
    // but becomes attractive when open bins have poor mean residual fit.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        let spread = (mean_residual - pr).abs();
        let congestion = 1.0 / (1.0 + open_bins_count as f64);
        score += 8.0 * congestion + 4.0 * (1.0 - progress);
        // If mean residual across open bins is low (bins nearly full),
        // opening fresh space becomes cheaper.
        score -= 5.0 * (1.0 - mean_residual / cap).max(0.0) * progress;
        let _ = spread;
    } else {
        // Prefer bins whose residual is below mean (tighter bins fill first).
        let diff = mean_residual - bin_residual as f64;
        score += 0.03 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo small divisors.
    let r = post_residual;
    let m4 = (r % 4) as f64;
    let m5 = (r % 5) as f64;
    let m10 = (r % 10) as f64;

    // Reward residuals that fall into "reusable" harmonic classes:
    // multiples of 10 and 5 are easier to fill with typical item sizes.
    if r % 10 == 0 {
        score -= 6.0;
    } else if r % 5 == 0 {
        score -= 3.0;
    } else {
        // Penalize awkward classes, worst near mid-range dead zones.
        score += m10 * 0.15 + m4 * 0.1;
    }

    // Integer-division thresholds on post_residual: tiny leftovers are dead space.
    if r <= 10 {
        score += 8.0; // nearly unusable
    } else if r <= 20 {
        score += 3.0;
    } else if r > bin_capacity / 2 {
        // Large leftover: good if it can host the next item, bad otherwise.
        if next_item_size > 0 && (next_item_size as u32) <= r {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Coupling with next item: harmonic match between next_item_size and r.
    if next_item_size > 0 {
        let n = next_item_size as u32;
        if r >= n {
            if (r - n) % 10 == 0 {
                score -= 5.0; // placing next item would again leave a clean residual
            } else if (r - n) % 5 == 0 {
                score -= 2.5;
            }
        } else {
            // Next item cannot fit here; slight penalty since this bin closes soon.
            score += 1.0 + m5 * 0.1;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless residual is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
        if r % 10 == 0 {
            score -= 3.0;
        }
    }

    // New-bin candidate handling: only open a new bin early in the stream
    // or when the current fit is very poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = (item_size as f64 / bin_capacity as f64) > 0.7;
        let poor_fit = (post_residual as f64) < 15.0 && fitting_bins_count >= 1;
        if progress < 0.15 || (tight && poor_fit) {
            score -= 12.0; // prefer fresh bin
        } else {
            score += 9.0; // prefer existing bins
        }
    }

    // Mild pressure toward consolidation when many bins are open.
    score += open_bins_count as f64 * 0.02 * (mean_residual / bin_capacity as f64);

    // Slight normalization by capacity fraction.
    score *= 1.0 - 0.1 * (r as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to capacity.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Lookahead: if the next item fits in the resulting gap, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra reward if next item exactly fills the gap.
        if next_item_size == post_residual {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use.
        score += 8.0;
    }

    // Last-chance pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 1.5 * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize proportionally to wasted capacity vs mean residual.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * mean_residual;
        // Opening a new bin is only attractive if nothing fits well anywhere.
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 25.0;
        }
    }

    // Mild preference for bins whose residual deviates from mean (consolidate gaps).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: item exactly fills the bin
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // leftover after next item would be small => chain fits well
            let chain_left = post_residual - next_item_size;
            score -= (50.0_f64).min(chain_left as f64 * 2.0);
        } else {
            // next item cannot fit here; penalize proportionally to the gap
            let gap = next_item_size - post_residual;
            score += gap as f64 * 1.5;
        }
    }

    // Penalize dead space that is too small to ever be useful (min item size 1..100 unknown, assume small items exist)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Relative to mean residual: prefer bins that are already tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 { -100.0 } else { 150.0 + (open_bins_count as f64) * 5.0 };
        score += penalty;
    }

    // Slight stream-progression pressure: later in stream, prefer packing into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (dynamic time horizon).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin before placement.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 25.0 * fit_ratio * fit_ratio;

    // Reward high pre-fill usage of the bin (keeps bins dense).
    score -= 10.0 * fill * fill;

    // Penalize tiny dead space more than proportional waste (fragmentation is costly).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this leftover: penalize proportionally to waste.
            score += 0.05 * post_residual as f64 * (0.5 + 0.5 * t);
        }
    } else {
        // Last item: only the residual matters, tighten hard.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidation
    // into fuller bins, discourage opening new bins.
    if open_bins_count > 0 {
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        score -= 5.0 * mean_fill * (open_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin starts from pure post_residual = capacity - item.
    // Make it unattractive unless no open bin fits well or the fit is genuinely better.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, decaying early in the stream.
        score += 20.0 * (1.0 - 0.5 * t) + 2.0 * open_bins_count as f64;
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 25.0;
        }
        // If next item is large and this bin would be nearly full, fresh bin is good.
        if next_item_size > 0 && next_item_size >= post_residual && item_size >= post_residual {
            score -= 10.0;
        }
    } else {
        // Existing bin: slight preference for bins with residual close to item size.
        let slack = (bin_residual - item_size) as f64;
        score += 0.02 * slack * slack / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Non-linear penalty on unusable residual (quartic coupling with progress)
    let dead = pr_norm * pr_norm;
    score += 40.0 * dead * dead * (0.5 + progress);

    // Reward tight fits: subtract for small post_residual (smooth quadratic)
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - progress * 0.3);

    // Lookahead: penalize if post_residual can't fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 12.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 15.0 * (nx - pr) / cap * (1.0 + progress);
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Crowd penalty: many open bins with low mean residual -> prefer filling
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap);
    score += 0.5 * crowd * progress;

    // New-bin candidate: penalize opening a fresh bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * mean_residual / cap - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
