    } else if r % 5 == 0 {
        score -= 5.0;
    }

    // Integer-division thresholds: how many "typical" items of cap/8 fit in leftover
    let slots = (post_residual as u64) / ((bin_capacity as u64) / 8);
    score -= (slots.min(6) as f64) * 12.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        }
        // Penalize leaving residual in the awkward class that next item cannot use
        if next_item_size > post_residual && post_residual > 0 {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive early in the stream or when mean residual
    // across open bins is already low (all bins tight)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap + 90.0 * (1.0 - openness) + 40.0 * progress - 60.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
        // Never open a new bin when this is a trivially good fit elsewhere
        if item_size >= bin_capacity / 2 && fitting_bins_count >= 1 {
            score += 200.0;
        }
    }

    // Band-based final adjustment: prefer leaving residuals in reusable harmonic bands
    score -= band * 10.0;

    // Late stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps
    // A post_residual that is too small to fit even the smallest plausible item is waste.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Penalize residuals that cannot fit the lookahead item (dead space relative to next need)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
        score -= 8.0; // can still serve the next item
    }

    // Tight fit reward: prefer bins where the item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Open bins pressure: discourage spreading across too many bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 1.5 * pressure * (0.5 + progress);

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: default mild penalty unless residual is very tight elsewhere
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-step packing
        }
        // penalize leaving residual that can't hold the next item
        if post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Relative to mean residual: prefer bins whose post residual is near/below mean
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize large dead space that nothing (min size 1..10) can use
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = bin_capacity as f64 - 20.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin good for a chain of large items
        }
    }

    // Late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual was barely enough.
    let tightness = 1.0 - (post_residual as f64) / (bin_residual.max(1) as f64);
    score -= 6.0 * tightness * (item_size as f64);

    // Perfect-fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize small dead space that few future items can use.
    if post_residual > 0 {
        let small_hole = (post_residual as f64 / bin_capacity as f64).powf(2.0);
        score += 10.0 * small_hole * (1.0 - tightness);
    }

    // Lookahead: if the next item can fit into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual >= next_item_size / 2 {
            score -= 3.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: only one bin can fit this item; strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + item_size as f64 * 0.2;
    }

    // Prefer using existing bins over opening new ones when bins are scarce.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly, more when many bins are open or late in stream.
        score += 5.0 + 6.0 * scarcity + 4.0 * progress;
        // Allow opening a new bin if all existing fits would leave large holes.
        if fitting_bins_count > 0 {
            let avg_waste = mean_residual / (open_bins_count.max(1) as f64);
            if post_residual as f64 > avg_waste {
                score -= 3.0;
            }
        }
    } else {
        // Reward filling bins that are already substantially loaded.
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 5.0 * fill;
        // Slight preference for bins with residuals below the mean (consolidate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.5;
        }
    }

    // Mild noise-free regularization toward the best-fit baseline.
    score += 0.01 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let poly = prn * prn * (1.0 - progress) + prn * progress * (1.0 - prn);
    score += poly * 20.0;

    // Reward tight fits, stronger late in the stream
    score -= item_size as f64 / bin_capacity as f64 * (1.0 + progress) * 10.0;

    // Penalize dead space growth relative to mean residual
    score += (pr - mean_residual).abs() * 0.3;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: prefer bins whose post-residual can't fit next item (keeps big slots free)
    if next_item_size > 0 && post_residual >= next_item_size {
        score += 5.0;
    }

    // New-bin candidate: mildly discourage unless residuals are tight
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: residual falls into a "useful" class if it can host
    // common small item sizes (10..=30). Penalize residuals that are dead space.
    let small_hostable = post_residual >= 10 && post_residual <= 30;
    if !small_hostable {
        // Dead space: residual too small to host anything useful.
        if post_residual < 10 && post_residual > 0 {
            score += 60.0;
        }
        // Large residual is fine only if we expect future demand.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are more reusable.
    let r = post_residual;
    let harmonic_bonus = if r % 10 == 0 {
        25.0
    } else if r % 25 == 0 {
        20.0
    } else if r % 5 == 0 {
        10.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Integer-division thresholds: classify residual into capacity fractions.
    let frac = (r as f64) / (bin_capacity as f64);
    if frac > 0.5 {
        // Half-full or more: still valuable, mild reward.
        score -= 12.0;
    } else if frac < 0.1 && r > 0 {
        // Nearly dead bin.
        score += 25.0;
    }

    // Lookahead coupling: if next item fits the post residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Exact harmonic match for the next item.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this residual; penalize proportionally.
        score += 10.0 * (1.0 - (next_item_size.min(post_residual + 1) as f64) / (next_item_size.max(1) as f64));
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge
    // and no good fit exists.
    if bin_residual == bin_capacity {
        let base_penalty = 70.0;
        let size_pressure = (item_size as f64 / bin_capacity as f64) * 30.0;
        score += base_penalty - size_pressure;
        // If many bins already fit the item, opening new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 40.0;
        }
    }

    // Mild diversity pressure: prefer bins whose residual deviates from mean
    // in a way that consolidates space (keep mean residual low).
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold typical items
    // (1..=100 unknown distribution; treat gaps < 10 as nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward perfect and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual is well matched to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item is close to fitting, small penalty for wasting the chance.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins exist,
    // but slightly encourage consolidation when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses / bins accumulate.
        score += 25.0 + 10.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * progress;
    } else {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins with residual above the mean (keeps big gaps available).
    if (bin_residual as f64) < mean_residual - 15.0 {
        score += 6.0;
    } else if (bin_residual as f64) > mean_residual + 15.0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small waste
    if next_item_size > 0 && post_residual >= next_item_size {
        let waste = (post_residual - next_item_size) as f64;
        score -= 30.0 - waste.min(30.0);
    }

    // Penalize post_residual that is too small for any plausible next item
    if post_residual < 10 {
        score += 25.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Prefer bins whose residual is below the mean (tighter packing)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Discourage opening new bins early in the stream or when many bins are open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 25.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual shrinks (non-linearly).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize small dead space that is hard to reuse (post_residual in 1..=9).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily; if next item almost fits, mild reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64) / 100.0;
        } else {
            // next item won't fit here; penalize large leftover residual slightly
            score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.05;
        }
    }

    // New-bin candidate handling: empty bin should usually lose unless
    // open bins are very fragmented or this is a bad-fit situation.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with number of open bins.
        score += 20.0 + 1.5 * open_bins_count as f64;
        // If no open bin fits well (post residual of best fit unknown; use mean residual),
        // discount the new bin when mean residual is small (open bins are full-ish).
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
        // Late in the stream, prefer closing out bins rather than hoarding.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Global fragmentation pressure: when mean residual is high and many bins open,
    // prefer placements that reduce variance (tight fits already favored).
    score += 0.02 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    // Non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Tight fits are rewarded more strongly as the stream progresses.
    let tightness = 1.0 - (pr / cap);
    score -= (1.0 + 3.0 * progress + 4.0 * p2 + 2.0 * p3) * tightness * 8.0;
    // Penalize dead space that is too small for typical items, scaled by progress.
    let dead = if pr > 0.0 && pr < 10.0 { 10.0 - pr } else { 0.0 };
    score += dead * (1.0 + 2.0 * p2) * 2.0;
    // Last-chance bin bonus (avoid opening new bins when only one fits).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 10.0 * progress;
    }
    // Lookahead: reward bins whose post-residual accommodates next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 4.0 + 4.0 * progress;
    }
    // Slight penalty for very full bins early on to keep flexibility.
    score += (mean_residual - pr).abs() * 0.05;
    // New-bin candidate: mildly penalize early, reward late when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 8.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: tiny leftovers are dead space.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap_f;

    // Penalize leftovers in "unusable" classes (small residues).
    if post_residual == 0 {
        score -= 40.0; // perfect fill is excellent
    } else if post_residual <= 5 {
        score += 25.0; // dead space
    } else if post_residual <= 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Reward bins whose leftover matches a useful harmonic class
    // (multiples of 10 / 25 are more likely to fit future items).
    let class_bonus = match post_residual % 25 {
        0 => 8.0,
        _ => match post_residual % 10 {
            0 => 5.0,
            _ => 0.0,
        },
    };
    score -= class_bonus;

    // Tight fit reward: fraction of capacity consumed by this item.
    let tightness = item_size as f64 / cap_f;
    score -= 10.0 * tightness;

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // partial fit quality
            let q = next_item_size as f64 / post.max(1.0);
            score -= 8.0 * q;
        } else {
            // leftover cannot host next item: mild penalty scaled by leftover size
            score += 3.0 * frac;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).max(1.0);
        let mean_frac = mean_residual / cap_f;
        // Prefer new bin when open bins are nearly full on average.
        score += 15.0 - 30.0 * mean_frac + 2.0 * pressure.ln();
        if post_residual == bin_capacity as u32 {
            score += 5.0; // slight nudge against opening bins early
        }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..10)
    // can realistically use are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable gap
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward exact match with lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize leaving a gap that the next item nearly fits but wastes.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // (avoid bin proliferation).
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual < bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: only attractive when few bins exist or mean residual
        // across open bins is very low (all bins nearly full).
        score += pressure;
        let mean_fullness = 1.0 - (mean_residual / bin_capacity as f64);
        if mean_fullness > 0.85 || open_bins_count <= 1 {
            score -= 15.0;
        }
        // Late in stream, opening new bins is less costly than dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Prefer bins with tighter fit overall (closeness of residual to item).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: next item closes this bin exactly
        } else if next_item_size <= post_residual {
            // next item fits: reward tight coupling, penalize large leftover after chain
            let chain_left = post_residual - next_item_size;
            score -= 12.0 - (chain_left as f64) * 0.15;
        } else {
            // next item won't fit here: penalize dead space proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
        // compare post_residual against mean residual: prefer bins whose remaining
        // space is close to what the stream typically leaves behind
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.08;
    } else {
        // last item: just minimize waste
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable fragments (dead space < typical min item)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference for tighter existing bins (avoid wasting large residuals on small items)
    score += (item_size as f64) / (bin_residual as f64 + 1.0) * 3.0;

    // Mild penalty for opening a new bin when several open bins already fit the item
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 8.0;
        }
        // but opening a new bin is fine late in the stream or when open bins are crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 4.0;
        // new bin looks attractive if next item is large and open bins are fragmented
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/tight fits: dead space is the enemy.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize residuals too small to hold the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: reward bins whose leftover can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 8.0 + 0.10 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin starts at full residual; make it
    // attractive only when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Cheaper to open a new bin when many bins are already open and
        // fragmented (high mean residual spread) or late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
        // If mean residual of open bins is large, fragmentation is low; prefer
        // reusing bins, so new bin is more expensive.
        score += 0.10 * mean_residual;
        // If the item is large relative to capacity, opening fresh space is fine.
        score -= 0.10 * item_size as f64;
    }

    // Prefer bins with smaller residual overall (best-fit flavor), scaled by
    // how many alternatives exist.
    score += 0.05 * (bin_residual as f64 - post_residual as f64) * (fitting_bins_count as f64).sqrt();

    // Mild penalty for spreading across too many open bins early on.
    if open_bins_count > 4 {
        score += 0.02 * open_bins_count as f64;
    }

    // Time horizon: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: post residual (prefer tight fits), with smooth non-linear shaping
    let mut score = post;

    // Quadratic/cubic coupling with stream progress: early on, tolerate slack;
    // later, punish leftover space more strongly (dead space matters more as stream ends).
    let poly = x * x * (1.0 - x) * (1.0 - progress) + x * x * x * progress;
    score += 60.0 * poly;

    // Smooth reward for filling a bin nearly full, amplified late in the stream
    let fill = 1.0 - x;
    score -= 25.0 * fill * fill * fill * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Penalize opening new bins when many bins are already open and mean residual is high
    let mean_x = mean_residual / cap;
    score += 0.15 * (open_bins_count as f64) * mean_x * mean_x * (0.5 + progress);

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let gap = (post - nx) / cap;
            score -= 20.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 10.0 * ((nx - post) / cap);
        }
    }

    // Slight penalty for very small post residual that wastes capacity unusably
    score += 8.0 * (1.0 - x) * x * x * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    if post_residual > 0 {
        score -= 40.0 / (post_residual as f64).sqrt();
    } else {
        score -= 25.0; // perfect fill
    }

    // Harmonic classes: classify post_residual into dead-space classes.
    // Residuals in 1..=10 are usually unusable dead space; penalize unless perfect.
    if post_residual > 0 && post_residual <= 10 {
        score += 30.0;
    }
    // Mid residuals (11..=20) are risky: only next items <= residual can use them.
    if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    // Integer division thresholds: quarter classes of capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 12.0; // bin still flexible
    } else if post_residual >= quarter {
        score -= 4.0;
    } else {
        score += 6.0; // low quarter: fragmented space
    }

    // Lookahead compatibility: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next item exactly fills leftover.
            if next_item_size == post_residual {
                score -= 35.0;
            } else {
                score -= 10.0;
                // penalize leaving residual that next item only barely exceeds
            }
        } else {
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 12.0; // next item nearly fits: this creates near-dead space
            } else {
                score += 3.0;
            }
        }
        // modulo coupling between next_item_size and post_residual
        if post_residual > 0 && (next_item_size % post_residual.max(1)) == 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: empty bin should only win when current fits are poor.
    if bin_residual == bin_capacity {
        // Neutral base; add pressure so a new bin is chosen only with bad fits.
        score += 15.0;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 10.0; // next item pairs well with current item in a fresh bin
        }
        // Early stream: opening bins is cheap; late stream: consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        score += (open_bins_count as f64) * 0.5;
    }

    // Mean residual coupling: prefer bins below mean residual (larger holes get used).
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the minimum item are pure waste — penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 30.0;
    } else if post_residual < 40 {
        score += 10.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Open-bin pressure: penalize choosing bins when many bins are open,
    // favoring consolidation into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 25.0;
    }

    // Mild attraction toward bins with residuals below the mean
    // (prefer filling the emptiest-feeling bins consistently).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fill is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            // reward, scaled by how well next item uses leftover
            let leftover_after_next = post_residual - next_item_size;
            score -= 200.0 - (leftover_after_next as f64) * 2.0;
        } else {
            // next item won't fit here; penalize wasted potential slightly
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strong bonus to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize leaving tiny unusable slivers (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer filling nearly-full bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * (0.1 + 0.2 * progress);

    // New-bin candidate: make it moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-perfect fills.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize very small post-residuals that become dead space unless perfectly zero.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer the tightest (post_residual already does that).
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state coupling: penalize placing into bins already looser than average
    // (keeps slack spread evenly), more so early in the stream.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * (1.5 - progress);

    // New-bin candidate logic: an empty bin is attractive only when the item is large
    // or no good fit exists; otherwise discourage wasting fresh bins.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 25.0;
        } else if large > 0.6 {
            score -= 6.0 * large;
        } else {
            score += 10.0 + 10.0 * (1.0 - progress);
        }
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    score += 0.3 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize very small post residuals (dead space) more aggressively over time
    score += 60.0 * norm_pr * norm_pr * (1.0 - norm_pr) * (0.5 + progress);

    // Reward tight fits
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    // Divergence from mean residual: prefer bins near the mean
    score += 0.2 * (pr - mean_residual).abs();

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (capacity/10 granularity)
    let res = post_residual % 10;
    let dead_penalty = match res {
        0 => -40.0, // perfect fill class
        1 | 2 => 30.0, // near-dead slivers
        9 => 5.0,
        _ => 10.0 + (res as f64) * 0.5,
    };
    score += dead_penalty;

    // Integer division thresholds on post_residual (capacity fraction classes)
    let cap_frac = post_residual as f64 / bin_capacity as f64;
    if cap_frac < 0.1 {
        score -= 25.0; // bin essentially full, great
    } else if cap_frac < 0.25 {
        score -= 5.0;
    } else if cap_frac > 0.5 {
        score += 20.0 * cap_frac; // leaving big holes
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 12.0; // next item won't reuse this residual
            if next_item_size % 10 == 0 {
                score += 8.0; // round next items pair well with round residuals
            }
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Many open bins: prefer closing existing ones over spreading
    score += 2.0 * open_bins_count as f64 * cap_frac;

    // Mean residual alignment: bins far from mean residual get normalized
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Stream progression: early on be picky, late accept decent fits
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * t * (1.0 - cap_frac);

    // New-bin candidate: only attractive when no good harmonic fit exists
    if bin_residual == bin_capacity {
        score = 55.0 + 10.0 * cap_frac - 15.0 * t;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot fit the next item are worthless.
    let dead = if next_item_size > 0 {
        post_residual < next_item_size
    } else {
        post_residual > 0 && post_residual < 10
    };
    if dead {
        score += (post_residual as f64) * 2.5 + 30.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Reward fits that leave room for the lookahead item (harmonious pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.4;
        // Perfect lookahead fit is gold.
        if post_residual == next_item_size {
            score -= 70.0;
        }
    }

    // Tight fit relative to residual: prefer bins where item consumes most of the gap.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Open-bin pressure: when many bins are open, avoid spreading; prefer filling existing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 6.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter than average).
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Penalize the new-bin candidate mildly so it only wins on genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: minimize post_residual (best-fit component)
    // Perfect-fit reward: strong bonus when item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly matches the post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
