            score += 1.5 * post_residual as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins that are already tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strong preference to use the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin unless the item fits poorly everywhere.
    // New-bin candidate has bin_residual == bin_capacity (post_residual = C - item).
    if bin_residual == bin_capacity {
        // Base penalty to prefer existing bins with decent fits
        score += 150.0;
        // If the item is large, filling a fresh bin is more acceptable
        score -= (item_size as f64 - 50.0).max(0.0) * 2.0;
        // Late in the stream, keep consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 50.0;
        // Many open bins: discourage adding more
        score += open_bins_count as f64 * 5.0;
    }

    // Small tie-breaker: slight preference for bins with less residual overall
    score += bin_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted fraction of the bin more than linearly.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac;

    // Reward filling the bin deeply relative to its current residual.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fill_frac;

    // Lookahead: if the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further residue: mild bonus proportional to use
            score -= 3.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover space: penalize small dead gaps
            if post_residual < 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be more selective (prefer tight fits);
    // late in the stream, just close out bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * fill_frac;

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins below the mean residual (i.e., fuller bins) to reduce bin count.
    if open_bins_count > 1 {
        let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 5.0 * rel; // bins fuller than average (lower residual) get lower score
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive only
    // if this item would leave a large awkward gap in any existing bin, or when the
    // item is large relative to residual in all bins (approximated via post_residual).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how poorly the item fits elsewhere.
        let mut new_bin_score = 55.0;
        if post_residual == bin_capacity {
            // This IS the new-bin call (item fits empty bin trivially).
            // Attractive when item is large (hard to place later) or few fitting bins.
            if item_size >= 50 {
                new_bin_score -= 10.0;
            }
            if fitting_bins_count == 0 {
                new_bin_score -= 30.0;
            }
            // Late in the stream, avoid proliferating bins.
            new_bin_score += 20.0 * progress;
            // Many open bins already: discourage opening yet another.
            new_bin_score += 1.5 * open_bins_count as f64;
            // If the next item is small and could share, opening fresh is fine.
            if next_item_size > 0 && next_item_size <= 30 {
                new_bin_score -= 5.0;
            }
        }
        score += new_bin_score;
    }

    // Exact-fit bonus: perfectly filling the bin is always great.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling: small post-residuals are rewarded super-linearly,
    // large ones (wasted space) penalized super-linearly.
    let x = pr / cap; // normalized post residual in [0,1)
    score += 40.0 * x * x * (1.0 - x);

    // Progress-dependent dead-space penalty: later in the stream, tiny residuals matter more.
    let tightness = (1.0 - x).powi(3);
    score -= 25.0 * progress * tightness;

    // Reward using bins whose residual closely matches the item (smooth fit term).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // Lookahead coupling: if next item fits in post-residual, reward this placement smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 12.0 * (1.0 - slack) * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    // Penalize opening a brand-new bin (bin_residual == bin_capacity) unless residual
    // pressure across open bins is high.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 20.0 * (1.0 - pressure) + 10.0 * (1.0 - progress);
    }

    // Mild preference for consolidating among many open bins.
    score += 0.05 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction slot does it fall in?
    let q = (post_residual * 10) / bin_capacity; // 0..10 decile class
    match q {
        0 => score -= 60.0,            // near-perfect fill: reward strongly
        1 => score -= 45.0,            // excellent fill
        2 => score -= 30.0,            // good fill
        3 => score -= 18.0,            // decent fill
        4 => score -= 8.0,             // fair fill
        5 => score += 0.0,             // half-full: neutral
        6 => score += 6.0,             // poor fill
        7 => score += 12.0,            // poor fill
        8 => score += 20.0,            // wasteful
        _ => score += 30.0,            // nearly empty bin used: very wasteful
    }

    // Integer-division threshold on post_residual: small dead space classes
    let dead_class = post_residual / 10;
    score += match dead_class {
        0 => -25.0, // residual < 10: unusable but bin is "closed" effectively
        1 => -15.0,
        2 => -8.0,
        3 => -2.0,
        _ => 0.0,
    };

    // Modulo-10 coupling: residuals divisible by 10 pair well with many item sizes
    if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Lookahead: does next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0; // perfect lookahead match
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap); // tighter lookahead fit is better
        } else {
            // next item cannot use the residual: penalize leaving large residuals
            score += 8.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // competition among fitting bins: prefer tighter fits
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let best_open = if fitting_bins_count == 0 {
            0.0
        } else {
            (bin_residual - item_size) as f64
        };
        // Opening a new bin gives residual = cap - item_size; reward it if
        // mean residual of open bins is large (they're all fragmented)
        score = cap - item_size as f64;
        score -= 35.0 * (mean_residual / cap); // open bins are fragmented -> prefer new bin
        score -= 10.0 * progress;              // early stream: keep bins open
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        let _ = best_open;
    }

    // Mild preference for filling bins with high residual (large item into roomy bin)
    score += 0.05 * (bin_residual as f64 - post_residual as f64).signum() * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (1..100 range, but small items are cheap to fit) are
    // heavily penalized as unusable gaps.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2).
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 45.0;
        } else if gap > 0 && gap < dead_threshold as i64 {
            // placing here would strand a tiny gap before the next item
            score += gap as f64 * 4.0;
        } else if gap < 0 {
            // next item can't use leftover anyway; mild penalty
            score += 3.0;
        }
    }

    // Tightness reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 25.0;

    // Open-bin pressure: when many bins are open, discourage opening new
    // ones and encourage consolidating into existing residual mass.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, modulated by pressure.
        score = 35.0 + pressure * 40.0;
        // If only this candidate fits, opening is forced-ish: reduce cost.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Late in stream with large mean residual, prefer reusing bins.
        score += mean_residual * 0.2;
        // Lookahead can still be absorbed by a fresh bin.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    } else {
        // Last-chance bin: strong reward to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Prefer bins whose residual is close to mean (balanced packing).
        score += (bin_residual as f64 - mean_residual).abs() * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild nonlinearity.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // 2-step lookahead: strongly reward when next item exactly fills the new residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            let gap = post_residual as f64 - next;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving awkward residual
            score += 6.0 * (next - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // last item: pure tightness
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are more precious.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: only fitting bin available -> strong reward to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline so it wins only when all fits are bad.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 {
            score -= 2.0;
        }
        // late in the stream, prefer consolidating into open bins
        if total_items > 0 {
            let t = step_index as f64 / total_items as f64;
            score += 20.0 * t;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream consumed (dynamic time horizon).
    let t = step_index as f64 / (total_items.max(1) as f64);

    // Relative tightness of the resulting placement.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Reward tight fits (small post_residual relative to item size).
    score -= fit_ratio * 12.0;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny sliver: nearly unusable
    } else if post_residual >= 10 && post_residual < 25 {
        score += 2.0; // awkward gap
    } else if post_residual >= 40 {
        score -= 3.0; // still flexible space
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained placements).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves another residual: mild reward
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 8.0 - chain_waste * 0.15;
        } else {
            // next item will NOT fit here: mild penalty, stronger late in stream
            score += 3.0 + 4.0 * t;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0 + 5.0 * (1.0 - t);
    }

    // Global state: many open bins with high mean residual → prefer reusing
    // existing space rather than spreading out.
    if open_bins_count > 2 {
        let reuse_bonus = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= reuse_bonus * 4.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a fresh bin wastes (capacity - item).
    // Only attractive when the item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += waste * 0.55;             // base penalty for wasted capacity
        if fitting_bins_count > 1 {
            score += 10.0;                 // an existing bin could host it: discourage
        }
        if next_item_size > 0 && next_item_size as f64 <= waste * 0.9 {
            score -= 10.0;                 // fresh bin can chain with next item
        }
        // Early in the stream, allow exploration with new bins; late, hoard space.
        score += 8.0 * (1.0 - t) - 6.0 * t;
    }

    // Mild noise-free exploration nudge tied to stream position.
    score += (step_index % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let progress_poly = t * t * (3.0 - 2.0 * t); // smoothstep-like, no piecewise constants
    score += progress_poly * (x * x) * 40.0;

    // Reward tight fits more strongly as stream progresses (non-linear in x and t)
    score -= (1.0 - x) * (1.0 - x) * (0.5 + t) * 30.0;

    // Penalize large residual with cubic term, weighted by mean residual context
    let mean_gap = (mean_residual - pr) / cap;
    score += x * x * x * 15.0 - mean_gap * 10.0;

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Lookahead coupling: penalize wasting space needed by next item (smooth in post_residual vs next)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let diff = nx - x;
        score += diff * diff * 20.0;
        // Reward exact-ish compatibility for the next item
        score -= (1.0 - (nx - x).abs().min(1.0)) * 15.0;
    }

    // Mild penalty for many open bins with large residuals (fragmentation pressure)
    score += (open_bins_count as f64).ln().max(0.0) * x * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: which quarter of capacity it lands in.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4
    match class {
        0 => score -= 30.0,                       // near-perfect fit: residual < C/4
        1 => score += 4.0,                        // awkward dead space (C/4..C/2)
        2 => score -= 10.0,                       // residual can hold mid-size items
        3 => score += 6.0,                        // large but lumpy residual
        _ => score -= 2.0,                        // essentially untouched bin
    }

    // Fine harmonic residue: reward residuals that are "clean" fractions of capacity.
    let mod16 = post_residual % 16;
    if mod16 == 0 { score -= 3.0; }
    else if mod16 <= 4 { score -= 1.5; }
    else if mod16 >= 12 { score += 1.0; }

    // Next-item lookahead: does the post residual still admit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // bonus scaled by how snugly the next item would fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 - (slack / 10.0).min(6.0);
        } else {
            // next item won't fit here: penalize proportionally to wasted potential
            score += 5.0 + (next_item_size - post_residual) as f64 / 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        score += 2.0; // plenty of alternatives; be pickier
    }

    // New-bin candidate handling: only attractive when open bins are crowded or
    // the current fit is poor (large post residual relative to capacity).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let poor_fit = post_residual as f64 / bin_capacity as f64; // = 1.0 for empty bin
        // base penalty so a fresh bin loses to any decent fit
        score += 20.0
            - 15.0 * crowded
            - 10.0 * progress
            + (mean_residual / bin_capacity as f64) * 8.0;
        let _ = poor_fit;
    } else {
        // Tightness reward: the smaller post_residual relative to residual, the better.
        let tightness = 1.0 - post_residual as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * tightness;
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (items >= 1, but small gaps < ~10 are effectively dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10.0 - post_residual as f64) * 3.0;
    }
    // Mid-range unusable gaps (10..30) are risky for unknown distributions.
    if post_residual >= 10 && post_residual < 30 {
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // loose bins; consolidate instead.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: penalize bins far looser than the average
    // (they waste space), reward tighter-than-average bins.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item cannot fit in post residual but this bin could have been
    // saved, mild penalty for breaking a potentially useful gap.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early
    // in the stream or when current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize new bin normally; discount penalty when bins are fragmented.
        score += 18.0 + 30.0 * (1.0 - progress) - 25.0 * fragmentation.max(0.0);
        // If no other bin can fit, new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match (post_residual == next_item_size) is gold.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect exact match: strong reward.
        if diff < 0.5 {
            score -= 40.0;
        } else if post_residual as u32 >= next_item_size {
            // Next item still fits: mild reward proportional to tightness.
            score -= 6.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit in the leftover: penalize dead space,
            // worse when the leftover is small-but-unusable.
            score += 4.0 + 8.0 * (1.0 - post_residual as f64 / (bin_capacity as f64 * 0.5).min(50.0)).max(0.0);
        }

        // Chain bonus: current fit tight AND next item fits again => very good.
        if post_residual as u32 >= next_item_size && item_size as f64 >= 0.7 * bin_residual as f64 {
            score -= 5.0;
        }
    } else {
        // Last item: just minimize leftover.
        score += 10.0;
    }

    // Tight fit reward relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 3.0 * (mean_residual - pr) / bin_capacity as f64;
    } else {
        score += 2.0 * (pr - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist;
    // allow it only if this bin's post-fit would be very wasteful.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 0.5 {
            score -= 20.0; // new bin enables a perfect 2-step chain
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Early in stream: keep bins flexible (mild penalty for tiny leftovers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if pr < 10.0 {
        score += (1.0 - progress) * 6.0;
    }

    // Many open bins: prefer consolidation (favor bins with below-average residual).
    if open_bins_count > 4 {
        score -= 1.5 * ((mean_residual - pr) / bin_capacity as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize creating large dead space relative to the smallest possible item (1).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // small-but-nonzero gap is awkward
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - next_fit / bin_capacity as f64);
    }
    // If next item cannot fit the leftover but could fit a fresh bin, penalize slightly.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we prefer
    // reusing open bins, unless the fit is poor or many bins are already open.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Opening a new bin is more attractive late in the stream when open bins are crowded.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 25.0 * progress;
        // If item is huge and next item is also huge, a fresh bin is reasonable.
        if item_size as f64 > 0.6 * bin_capacity as f64
            && next_item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 35.0;
        }
        // If no open bin leaves a good residual, new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Mild preference to fill bins that are already mostly empty (consolidate load).
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    // Slight penalty for proliferating open bins.
    score += 0.3 * open_bins_count as f64;

    // Global-state term: prefer bins whose residual is below mean (fill emptier gaps last).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.98;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item sizes (10..80 step classes) are more reusable.
    let pr = post_residual;
    let mut bonus = 0.0;
    if pr == 0 {
        bonus -= 60.0; // perfect closure
    } else {
        // divisibility rewards across harmonic classes
        for d in [10u32, 20, 25, 40, 50, 80] {
            if pr % d == 0 && pr >= d {
                bonus -= 4.0 + (d as f64) * 0.15;
            }
        }
        // small dead space penalty (unusable slivers)
        if pr < 10 {
            bonus += 25.0;
        } else if pr <= 15 {
            bonus += 8.0;
        }
        // integer-division threshold: pr in [next_item_size, next_item_size+15)
        // means this residual can host the lookahead item
        if next_item_size > 0 && pr >= next_item_size {
            let quotient = pr / next_item_size.max(1);
            if quotient >= 1 {
                bonus -= 10.0 + (pr - next_item_size) as f64 * 0.3;
            }
        }
        // capacity fraction coupling: residual near half-capacity is versatile
        let half = cap / 2.0;
        let frac = (pr as f64 - half).abs() / cap;
        bonus -= (1.0 - frac) * 5.0;
    }

    // Tight fit reward
    let tightness = 1.0 - (post_residual as f64) / cap;
    bonus -= tightness * tightness * 20.0;

    // Last-chance bin urgency
    if fitting_bins_count == 1 {
        bonus -= 15.0;
    } else if fitting_bins_count > 3 {
        bonus += (fitting_bins_count as f64 - 3.0) * 1.5;
    }

    // New-bin candidate: only attractive when open bins are crowded or
    // the fit is very poor elsewhere.
    let is_new = bin_residual == bin_capacity && item_size <= bin_capacity;
    if is_new {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
        let poor_fit = (post_residual as f64 > 0.0 && post_residual < 10) as f64 * 30.0;
        // prefer new bin when mean residual is small relative to item and stream is young
        bonus += 45.0 + crowded * 2.0 - progress * 20.0 - poor_fit;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            bonus -= 10.0; // new bin can host lookahead too
        }
    }

    // mild mean-residual alignment: avoid increasing residual spread
    let spread = (post_residual as f64 - mean_residual).abs();
    bonus += spread * 0.05;

    score += bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (1..100 interface)
    // are wasted forever. Punish gaps in the "unusable" band hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward using bins whose residual is well matched to the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open; but if this is the LAST fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: mild reward for reusing bins as count grows
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Lookahead: if the next item fits exactly in the post residual, big reward;
    // if post residual is smaller than next item (dead end for next), mild penalty
    // unless it fits in another bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Mean residual coupling: placing into a bin with residual far above mean
    // (i.e., an underused bin) is fine; placing into a near-empty bin wastes it.
    if bin_residual as f64 > mean_residual + 20.0 && bin_residual != bin_capacity {
        score += 5.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    // Base penalty keeps it from winning unless open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If no other bin can fit the item, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, slightly less eager to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    score *= 1.0;

    // 2-step lookahead: reward if the NEXT item also fits in the remaining space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: this bin remains productive; reward proportionally.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 + 0.5 * slack;
            // Perfect chain: post_residual exactly equals next item.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item won't fit: penalize leftover dead space, worse when
            // the leftover is small and unusable.
            let leftover = post_residual as f64;
            let next_size = next_item_size as f64;
            let unusability = 1.0 - (leftover / next_size).min(1.0);
            score += 20.0 * unusability;
        }
    } else {
        // Last item: just prefer tightest fit.
        score -= 10.0;
    }

    // Compare against the average residual across open bins: placing into a
    // bin that is already tighter than average concentrates waste efficiently.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.4 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin has full residual. Only prefer
    // it when no open bin offers a decent 2-step chain. Penalize opening a
    // new bin mildly, more so late in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
        // But if next item is large, a fresh bin guarantees a good chain.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Mild penalty when many bins are competing (encourage consolidation).
    score += 0.5 * fitting_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize small dead space nonlinearly (waste potential)
        let pr = post_residual as f64;
        score += (pr / 10.0).powi(2) * 0.5;
    }

    // Lookahead: if next item fits in post residual, reward this bin strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.3 * (next_item_size as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // dead space unusable by next item
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Reward tighter fits relative to bin residual
    if bin_residual > 0 {
        score -= (item_size as f64 / bin_residual as f64) * 15.0;
    }

    // Global state: many open bins -> prefer consolidation into existing bins
    if open_bins_count > 3 {
        score -= 0.8 * open_bins_count as f64;
    }

    // Mean residual coupling: bin far below mean residual is a good dump target
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Time horizon: early stream, be conservative (favor new bins less); late stream, squeeze bins
    let t = step_index as f64 / (total_items.max(1) as f64);
    if t > 0.7 {
        score -= 6.0 * t;
    } else {
        score += 3.0 * (1.0 - t);
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with progress:
    // residual waste becomes increasingly costly as the stream advances.
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let waste_penalty = pr_norm * pr_norm * (1.0 + 3.0 * progress) + pr_norm * progress * progress;
    score += 40.0 * waste_penalty;

    // Reward tight fits (post_residual near zero), stronger late in the stream.
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 1.0 {
            score -= 30.0 * (1.0 + progress);
        } else if nxt <= pr {
            // next item fits but leaves further residual: mild reward, coupled to fit quality
            let fill = nxt / pr.max(1.0);
            score -= 12.0 * fill * fill;
        } else {
            // next item cannot use this residual: penalize proportionally to leftover size
            score += 8.0 * pr_norm * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 + progress);
    }

    // Penalize bins whose residual is far from the mean residual (fragmentation avoidance),
    // with a smooth quadratic coupling.
    let dev = pr - mean_residual.max(0.0);
    score += 0.15 * dev * dev / (mean_residual.max(1.0));

    // New-bin candidate: make it attractive only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, reduced late in stream when consolidation matters less.
        score += 55.0 - 15.0 * progress;
        // If many bins fit, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If the item is large relative to capacity, a fresh bin is more acceptable.
        score -= 20.0 * (item_size as f64 / cap);
    }

    // Mild preference to fill already-open bins as their count grows (bin-count pressure).
    score += 0.05 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: classify post_residual into residue classes mod 10.
    // Gaps that are "harmonically useful" (multiples of 10, or large enough to host common sizes)
    // should be rewarded; awkward tiny gaps penalized.
    let gap = post_residual;
    let gap_class = gap % 10;
    if gap == 0 {
        score -= 40.0; // perfect fit: best possible outcome
    } else if gap_class == 0 {
        score -= 12.0; // round gap: easy to fill later
    } else if gap < 10 {
        score += 25.0; // dead space: nothing (min size 10) can ever use it
    } else if gap_class >= 8 {
        score += 10.0; // nearly-round but wasted sliver
    }

    // Dead-space threshold: gaps below the minimum item size are pure loss.
    if gap > 0 && gap < 10 {
        score += 30.0;
    }

    // Reward gaps that can host the lookahead item (harmonic coupling with next_item_size).
    if next_item_size > 0 {
        if gap >= next_item_size {
            // this bin remains usable for the next item -> chain bonus
            score -= 8.0 + (next_item_size as f64) * 0.15;
        }
        // prefer leaving a gap that exactly matches next item (mod-10 harmonic match)
        if gap >= next_item_size && (gap - next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    }

    // Tightness reward: fill bins as full as possible relative to capacity.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has full residual; make it attractive
    // only when the current fit is poor (large post_residual relative to capacity)
    // or the stream is early and there is slack for future flexibility.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        // opening a new bin costs ~1 bin; only worth it if the leftover gap is big
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_cost = 55.0 - 25.0 * progress; // early stream: cheaper to open bins
        if poor_fit > 0.5 {
            score -= open_cost * (poor_fit - 0.5) * 2.0;
        } else {
            score += open_cost * 0.5; // discourage opening when fit is decent
        }
    }

    // Mild penalty for proliferating open bins when residuals are already large.
    if open_bins_count > 4 && (post_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fit_ratio;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size <= item_size {
        // Next item can't use the dead space we would create: penalize.
        if post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: more open bins -> prefer filling existing ones,
    // but keep new-bin candidate (residual == capacity) as a fallback.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64) * (2.0 + 4.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral-ish baseline; penalize slightly more when many bins open.
        score += 10.0 + pressure * 0.5;
    } else {
        score -= pressure * 0.3;
    }

    // Prefer bins with below-mean residual (compact the most-filled bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Reward bins whose post_residual closely matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_gap = (post_residual as f64 - nxt).abs();
        // Perfect chaining (next item exactly fills leftover) gets a big bonus.
        if post_residual as f64 >= nxt {
            score -= 30.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize dead space relative to gap.
            score += 0.5 * match_gap;
        }
        // Extra reward if next item fits exactly (zero gap).
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: minimize leftover as usual.
        score += 0.1 * post_residual as f64;
    }

    // Relative-to-mean adjustment: prefer bins with residual below mean
    // (tighter bins absorb items, keeping roomy bins flexible).
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize the brand-new empty bin candidate mildly, so it's chosen only
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * item_size as f64;
        // Late in the stream, opening new bins is more acceptable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Slight preference for filling bins that are already well used.
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    // Tie-break: fewer open bins is better; nudge toward consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (quadratic in wasted space).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating tiny unusable dead space (< 10 can hold nothing).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + 0.5 * (next_item_size as f64);
    }
    // If next item just barely misses post_residual, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 0.2 * ((next_item_size as f64) - post_residual as f64).min(30.0);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in stream, new bins are cheaper; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
        // If many open bins with large mean residual, opening new bin is fine.
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual deviates from mean (keep homogeneous residuals).
    score += 0.1 * ((bin_residual as f64) - mean_residual).abs();

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (bin_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr + 0.35 * norm_pr * norm_pr);

    // Tight fits rewarded more as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Lookahead: prefer bins whose residual still fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 5.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Penalize bins far from mean residual (imbalance)
    score += 0.15 * (pr - mean_residual).abs();

    // Mild penalty for too many open bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: prefer it only when post_residual is large and stream is early
    if bin_residual == bin_capacity {
        score -= 3.0 * progress * (1.0 - norm_pr);
        score += 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space by residue mod 10
    let r = post_residual % 10;
    // Residuals that are "usable" for typical small items get rewarded
    match r {
        0 => score -= 6.0,          // perfectly divisible residual
        1 | 2 | 3 => score += 4.0,  // awkward slivers -> dead space penalty
        4 | 5 | 6 => score -= 2.0,  // medium-friendly
        _ => score += 1.0,
    }

    // Integer division threshold: large post_residual means room for future items
    let quarters = post_residual / (bin_capacity / 4);
    score -= 3.0 * quarters as f64;

    // Coupling with next item: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // modulo harmonic match: next item leaves a clean residue
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty if this bin is the only option
            if fitting_bins_count == 1 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing residuals are badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if mean_residual < item_size as f64 + 5.0 || open_bins_count == 0 {
            score -= 8.0;
        } else {
            score += 12.0 + 10.0 * progress;
        }
        let _ = fragmentation;
    }

    // Prefer tight fits overall: penalize proportionally wasted fraction
    score += 8.0 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64);

    // Small tie-breaker against opening many bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are "unusable" for the
    // known item range (min item = 1 here), but tiny slivers waste capacity.
    // Penalize non-zero small gaps super-linearly; reward near-perfect fits.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    } else if post_residual <= 3 {
        // Unusable dead space: heavily penalize.
        score += (4.0 - post_residual as f64) * 12.0;
    } else if post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 3.0;
    }

    // Coupling with tightness: reward filling a large fraction of the bin.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a pointless new-bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bins pressure: as the number of open bins grows, mildly discourage
    // spreading items across many bins unless the fit is genuinely good.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead synergy: if the next item can fit into this bin's post
    // residual, reward; if it cannot, penalize leaving a tempting gap.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 2.0;
        }
    }

    // New-bin candidate: an empty bin should only win when no open bin offers
    // a decent fit. Give it a mild handicap so tight existing fits win, but
    // allow it to win over badly-fitting bins (large post_residual there).
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (1.0 - progress);
    }

    // Slight drift toward consolidation over the stream.
    score += mean_residual * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but punish very small dead space less if it matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        // Perfect 2-step match: fills bin completely over two placements.
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits here; reward proportional closeness.
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here; penalize more if leftover is tiny (dead space).
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0;
        }
    }

    // Relative to mean residual: prefer bins with residuals near mean (balanced), punish outliers.
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff.abs();

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current fit is very poor
    // and next item is large (better to start fresh).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.5 * bin_capacity as f64;
        let big_next = next_item_size > 60;
        if poor_fit && big_next {
            score -= 20.0; // fresh bin is attractive
        } else {
            score += 15.0; // discourage opening new bins generally
        }
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty per open bin pressure: favor filling existing bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual, but heavily penalize large dead space.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open and mean residual is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let waste_pressure = mean_residual / (bin_capacity as f64);
        score += 18.0 + 30.0 * (1.0 - progress) * (1.0 - waste_pressure.max(0.0));
        // If no open bin fits, opening a new bin is necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild penalty when this bin's residual deviates far from the mean (keep residuals balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Small time-decay on perfect-fit reward to stay adaptive across the stream.
    score -= (1.0 - progress) * (post_residual as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Smooth non-linear coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * pr / cap);

    // Quadratic dead-space penalty: small residuals are wasted space.
    score += 0.35 * (1.0 - pr / cap) * (1.0 - pr / cap) * cap * 0.1;

    // Perfect fit reward (smooth, no hard cutoff).
    score -= 25.0 * (-pr as f64 * pr as f64 / 8.0).exp();

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        score -= 12.0 * (-gap * gap / 50.0).exp();
    }

    // New-bin candidate: penalize opening a bin unless it's early or residual is tiny.
    if is_new_bin {
        let urgency = (1.0 - pr / cap) * (1.0 - pr / cap);
        score += 30.0 * urgency * (1.0 - progress) + 10.0 * (1.0 - progress);
        score += open_bins_count as f64 * 0.5;
    }

    // Mild preference for bins tighter than average residual.
    score -= 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does it land in?
    let quarter = bin_capacity / 4;
    let class = match post_residual {
        0 => 0.0,                      // perfect fill
        x if x < quarter => 1.0,       // tiny dead space
        x if x < 2 * quarter => 2.0,
        x if x < 3 * quarter => 3.0,
        _ => 4.0,                      // large residual remains
    };
    // Reward small classes super-linearly (harmonic weighting 1/(class+1))
    score -= 30.0 / (class + 1.0);

    // Exact-fit bonus via modulo arithmetic on residual classes
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0; // residual on a decade boundary is more reusable
    }

    // Penalize dead space that next item cannot use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 * (next_item_size - post_residual) as f64 / cap;
    }
    // Reward residual that exactly or nearly fits the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, less so early or when
    // existing fit would waste a lot (post_residual very small vs item size)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_penalty = if next_item_size > 0 && post_residual < next_item_size {
            0.0 // would-be dead space elsewhere; new bin acceptable
        } else {
            20.0 + 30.0 * (1.0 - progress)
        };
        score += waste_penalty;
    }

    // Coupling with mean residual: prefer bins whose residual is below mean
    // (compact the tight bins, leave roomy bins for large future items)
    score += ((post_residual as f64) - mean_residual) * 0.3;

    // Mild pressure to reuse bins when many are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let progress = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    let mean_res = if mean_residual.is_finite() {
        mean_residual.clamp(0.0, cap)
    } else {
        cap
    };
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post + 0.18 * post * post / cap;

    if post_residual == 0 {
        score -= 10.0 + 0.25 * open + 4.0 * progress;
    }

    if next > 0.0 {
        if post > 0.0 && post < next {
            let dead_weight = 1.55 + 0.02 * open + 0.45 * progress;
            score += (next - post) * dead_weight;
        } else if post >= next {
            score -= 4.0 + 2.0 * progress;
        }
    }

    if is_new_bin {
        let hosts_next = next > 0.0 && post >= next;
        let mut new_cost = 8.0 + 0.60 * open + 4.0 * progress;

        if fitting_bins_count > 0 {
            new_cost += 9.0;

            if hosts_next {
                let pair_need = item + next;
                let pair_deficit = ((pair_need - mean_res) / cap).clamp(0.0, 1.0);
                if pair_deficit > 0.0 {
                    new_cost -= 6.0 + 14.0 * pair_deficit + 3.0 * progress;
                }
            }

            if fitting_bins_count == 1 {
                new_cost += 5.0;
            }
        } else {
            new_cost -= 12.0;
        }

        score += new_cost.max(0.0);
    } else if fitting_bins_count == 1 {
        score -= 4.0 + 2.0 * progress + 0.05 * open;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item exactly fills the post
    // residual, this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize proportionally to leftover dead space
            // after the hypothetical second placement.
            let second_left = post_residual - next_item_size;
            score += 0.25 * second_left as f64;
        } else {
            // Next item cannot use this bin's remainder: penalize dead space.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins that are more filled than average.
    let rel = post_residual as f64 - mean_residual;
    score += 0.10 * rel;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 > 40.0) || (next_item_size > 0 && next_item_size as f64 > mean_residual + 10.0);
        if poor_fit {
            score -= 5.0;
        } else {
            score += 10.0;
        }
    }

    // Slight preference to consolidate into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * (1.0 - progress) * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Penalize dead space: post residuals too small to hold typical items are wasted.
    if post_residual < 10 {
        score -= 15.0; // perfect fill bonus
    } else if post_residual <= 20 {
        score += 5.0; // small awkward gap
    } else {
        score += (post_residual as f64).sqrt() * 2.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0; // next item won't chain here
        }
    }

    // Last-chance bin: avoid opening a new bin if this one fits reasonably.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state: many open bins with slack -> prefer reusing fuller bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 2 {
        score += mean_residual * 0.15 * (1.0 - progress);
    }

    // Time horizon: late in stream, conserve bins aggressively (tighten).
    score -= progress * 10.0 * fit_ratio;

    // New-bin candidate handling: opening a new bin should only win when it's
    // genuinely better than a poor fit; make it moderately attractive by default.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral residual, but discourage if existing bins fit well.
        if fitting_bins_count > 0 {
            let best_possible = (item_size as f64 / bin_capacity as f64) * 25.0;
            if fit_ratio > 0.9 {
                score -= 10.0; // item nearly fills a bin anyway; new bin fine
            }
            let _ = best_possible;
            score += 18.0; // default penalty so open bins are preferred
        }
        if item_size >= 60 {
            score -= 8.0; // big items start fresh bins more readily
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: best-fit core, with a mild non-linear inflation of large leftovers.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth coupling: large residuals become more tolerable early, more costly late.
    score += 1.5 * (pr / cap).powi(2) * (1.0 + 2.0 * progress);

    // Reward near-perfect fits (small post_residual) increasingly as stream progresses.
    let tightness = 1.0 - pr / cap; // 1.0 for perfect fit
    score -= 6.0 * tightness.powi(3) * (0.5 + progress);

    // Lookahead: if the next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = pr - nx;
            score -= 4.0 * (1.0 - gap / cap);
        } else {
            // next item cannot follow here: slight penalty scaled by overshoot
            score += 1.2 * ((nx - pr) / cap);
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are quite full.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / cap;
        let crowding = (open_bins_count as f64).ln().max(1.0);
        score += 20.0 - 18.0 * mean_fill - 2.0 * progress;
        score *= 1.0 + 0.05 * crowding;
    } else {
        // Slight preference for bins already below-average residual (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        } else {
            score += 0.8 * ((bin_residual as f64) - mean_residual) / cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity / 4 quarters
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter;
    // Reward residuals that are exact multiples of the quarter (harmonic fit)
    if class == 0 {
        score -= 8.0;
    } else if class <= 5 {
        score += 4.0; // tiny dead space is wasteful
    }

    // Integer-division thresholds on post_residual
    let k = post_residual / 10; // decades of residual
    score -= 1.5 * (k as f64).ln().max(0.0);

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if next item exactly fills post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // penalize leaving residual that next item can't use well
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score += 3.0;
        }
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score = (bin_capacity as f64) - pressure
            + 10.0 * (step_index as f64 / total_items.max(1) as f64)
            - if open_bins_count == 0 { 15.0 } else { 0.0 };
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 3.0; // tiny gaps are almost useless
    } else if dead == 0.0 {
        score -= 8.0; // perfect fit bonus
    } else if dead >= 10.0 && dead < 25.0 {
        score += (25.0 - dead) * 0.6; // mild penalty for awkward mid gaps
    }

    // Favor bins whose residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else if post_residual > 0 {
            score += 2.0; // kills bin for the lookahead item
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins (penalize the new-bin candidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        score += 12.0 + 4.0 * pressure;
    } else {
        score -= pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Prefer bins tighter than the average residual (good fill).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight preference for larger item into tighter bin (best-fit flavor).
    score += (item_size as f64 / bin_capacity as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose residual after placement
    // closely matches the next item size (perfect two-item chaining).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        // Perfect match: post_residual == next_item_size -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards: reward proportional to tightness.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted residual relative to gap.
            score += 0.3 * gap;
        }
    }

    // Prefer tight fits overall: residual-aware tightness reward.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Penalize bins that deviate from mean residual (keep residual pool balanced),
    // unless this is the only fitting bin (last chance -> strong reward to use it).
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        score += 0.5 * (bin_residual as f64 - mean_residual).abs();
    }

    // Late in the stream, avoid opening new bins; favor using existing capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized later.
        score += 15.0 + 30.0 * progress;
    } else {
        score -= 8.0 * progress;
    }

    // Slight penalty per many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let nxt_fit = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * nxt_fit;
        } else {
            // Next item won't fit here; penalize more if we leave a lot stranded.
            score += 0.3 * post_residual as f64;
        }
        // Perfect chain: post residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // Last item: minimize leftover waste aggressively.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin,
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let badness = (post_residual as f64 / bin_capacity as f64).min(1.0);
        score -= 35.0 * (1.0 - badness);
    }

    // New-bin candidate: make it attractive only when fits are poor or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = 1.0 - fit_ratio.min(1.0);
        score += 30.0 * (1.0 - poor_fit)   // penalize new bin when a good fit exists
               + 20.0 * (1.0 - progress)   // early stream: new bins are cheap
               - 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Dynamic time-horizon term: later in the stream, prefer filling bins tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score += 12.0 * poly * (0.5 + progress);

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - pr_norm;
    score -= 6.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize large dead space non-linearly
    score += 4.0 * pr_norm * pr_norm * pr_norm;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let snug = 1.0 - ((pr - n) / bin_capacity as f64);
            score -= 5.0 * snug * snug;
        } else {
            score += 3.0;
        }
    }

    // Slight preference for consolidating residual mass when many bins are open
    score += 0.05 * (post_residual as f64 - mean_residual).abs() / open_bins_count.max(1) as f64;

    // New-bin candidate: penalize opening a new bin mildly, more early in stream
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction does it fall into?
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // 0..1

    // Classify post_residual into harmonic bins via integer division
    let class = post_residual / (bin_capacity / 4).max(1); // 0..=4 quartile class
    match class {
        0 => score -= 30.0,                 // near-perfect fit: strong reward
        1 => score -= 12.0,                 // good fit
        2 => score -= 0.0,                  // neutral
        3 => score += 10.0,                 // poor fit, lots of dead space
        _ => score += 20.0,                 // almost empty bin wasted on this item
    }

    // Modulo arithmetic on post_residual: residues that are "usable" for common item sizes
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 8.0; // aligns with decade-sized items
    } else if mod10 >= 5 {
        score += 3.0 * (mod10 as f64 - 5.0);
    } else {
        score += 2.0 * mod10 as f64;
    }

    // Coupling with lookahead item: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (post_f - next_item_size as f64) / cap;
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 4.0 * (next_item_size as f64 - post_f) / cap;
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win if no decent open fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.9;
        // cheaper to open a new bin late in the stream or when open bins are fragmented
        score -= (step_index as f64 / total_items.max(1) as f64) * 10.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // pairing large items together in fresh bin is fine
        }
        // penalize new bin if an open bin fits nearly perfectly
        if post_f < cap * 0.25 && fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    // Fragmentation awareness: prefer bins whose residual deviates favorably from mean
    let dev = post_f - mean_residual;
    score -= 0.15 * dev;

    // Progress-scaled tightness pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post_f) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer packing into existing bins,
    // and penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= (open_bins_count.min(20) as f64) * 1.5;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap just below the next item (near-miss dead space).
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(3) && post_residual < next_item_size {
        score += 20.0;
    }

    // Early in the stream, be more willing to open bins; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        score += 10.0 * progress;
    }

    // Prefer bins with residuals close to the item (best-fit flavor).
    score += 0.3 * ((bin_residual as f64 - item_size as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item can also fit here: strong reward, tighter match = better.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit after this placement: penalize dead space.
            score += 8.0 + 0.15 * gap;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (good fits),
    // penalize bins that are unusually loose (wasteful placement).
    let dev = post_residual as f64 - mean_residual;
    score += 0.10 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize near-empty placements in nearly-full bins only when it creates slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable dead space (min item size assumed >= 10)
    }

    // Late in the stream, consolidate: prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when decent fits exist.
        score += 15.0 + 30.0 * progress;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 10.0; // fresh bin gives full lookahead flexibility
        }
    } else {
        score -= 5.0 * progress; // reward using open bins later on
    }

    // Prefer bins with larger residual consumed relative to capacity (denser packing).
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post residual is small.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for any plausible future item.
    if post_residual < 10 {
        score -= 15.0; // perfectly sealed bin is great
    } else if post_residual < next_item_size.max(1) && next_item_size > 0 {
        score += 8.0; // residual unusable by the immediate next item
    }

    // Lookahead coupling: reward bins whose post residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            score -= 12.0 * (1.0 - chain as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when fits are poor or stream is early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.5;
        let many_open = open_bins_count as f64 > 2.0 + 6.0 * progress;
        if poor_fit || many_open {
            score -= 20.0;
        } else {
            score += 35.0; // prefer using existing bins early on
        }
    }

    // Global state: spread load when mean residual is high, consolidate when low.
    if bin_residual < bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Mild consolidation pressure as the stream progresses.
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space non-linearly (quartic dead-space term)
    let mut score = x * x * x * x * cap + 0.35 * pr;

    // Smooth polynomial coupling with stream progress: waste matters more later
    score += 40.0 * progress * (x * (1.0 - x)).powi(2) * cap;

    // Reward tight fits (small post residual) with smooth cubic discount
    score -= 25.0 * (1.0 - x).powi(3);

    // Last-chance bin: strongly favor using it, smoothly scaled by fit scarcity
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    } else {
        score -= 8.0 / (fitting_bins_count as f64);
    }

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        score += 0.4 * gap;
        // bonus if next item fits exactly-ish in post residual
        if pr >= n {
            score -= 15.0 * (1.0 - (gap / cap).min(1.0));
        }
    } else {
        // last item: penalize any leftover
        score -= 20.0 * (1.0 - x);
    }

    // Mild pressure to consolidate into fewer bins
    score += 0.15 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 30.0 * dev * dev;

    // New-bin candidate: penalize opening a bin unless residuals are nearly full
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - (mean_residual / cap);
        score += 45.0 * (1.0 - mean_fullness).powi(2) + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common
    // item granularity (gcd-ish classes of 10) are more reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward placements that leave residuals in "usable" harmonic classes.
    // Classes: multiples of 10 (highly reusable), then multiples of 5, then 2.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 6.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        } else if post_residual % 2 == 0 {
            score -= 1.0;
        } else {
            score += 2.0; // odd dead space is least reusable
        }
    }

    // Perfect fit: overwhelmingly favored.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit: leftover smaller than the smallest plausible next item.
    if post_residual < 10 && post_residual > 0 {
        score -= 8.0;
    }

    // Harmonic pairing: if next item exactly consumes post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits here: mild reward, scaled by leftover slack
        let slack = (post_residual - next_item_size) as f64;
        score -= 4.0 * (1.0 - slack / cap);
    }

    // Integer-division threshold: bin "wasted fraction" classes.
    // Penalize bins whose residual fraction is in a bad harmonic band.
    let residual_frac = bin_residual as f64 / cap;
    let band = (residual_frac * 4.0).floor() as u32; // quarters of capacity
    match band {
        0 => score += 5.0,   // nearly full bin: fine, little choice
        1 => score -= 2.0,   // 25-50% residual: sweet spot for filling
        2 => score += 0.5,
        _ => {}              // mostly empty bin: neutral
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter ones (post_residual term
        // already does this); add small penalty to discourage hoarding.
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: reserve it for cases where no open bin fits well.
    // Penalize opening a new bin unless the item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += scarcity;
        // If next item is small, a fresh bin keeps flexibility: slight discount.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 3.0;
        }
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * (1.0 - progress);
    }

    // Mean-residual coupling: when average slack across bins is high,
    // prefer to consolidate into existing bins rather than spread.
    if mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 1.5 * (mean_residual / cap);
    }

    // Late stream: squeeze existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be
    // usable by typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin.
        score -= 60.0;
    } else {
        // Larger usable residuals: mild superlinear penalty to prefer
        // bins where the item fills a bigger fraction of the space.
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 15.0 * fill_ratio;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            score += 10.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure proportional
        // to number of open bins and mean residual availability.
        score += 25.0 + 4.0 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            score += 20.0; // an open bin could have absorbed it reasonably
        }
        // Late in the stream, opening bins wastes capacity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        // Mild reward for keeping bins busy as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match is highly desirable: subtract a big bonus
        if diff < 0.5 {
            score -= 60.0 + 20.0 * (1.0 - progress);
        } else {
            // Penalize residuals that can't fit the next item (dead space risk)
            if (post_residual as f64) < nxt {
                score += 8.0 + 12.0 * (nxt - post_residual as f64) / 100.0;
            } else {
                // Mild reward if next item still fits comfortably
                score -= 4.0 * (1.0 - diff / 100.0);
            }
        }
    } else {
        // Last item: prefer tightest fit
        score -= 30.0;
    }

    // Compare against mean residual: favor bins with below-average residual (tighter bins)
    score += 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving very small unusable slivers (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: neutral-ish score tied to mean residual so it wins only
    // when all open bins fit poorly
    if bin_residual == bin_capacity {
        score = mean_residual.max(0.0) + 5.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Slight preference to fill bins with more items already packed (fewer open bins)
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward near-perfect fills (small dead space is superlinearly good).
    if post_residual > 0 {
        score += 12.0 / post_residual as f64;
    } else {
        score -= 25.0; // perfect fit
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; leftover is dead space unless tiny
            if post_residual < 10 {
                score -= 5.0; // small enough to be acceptable
            } else {
                score += 0.15 * post_residual as f64 * (0.5 + 0.5 * t);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    } else if fitting_bins_count > 1 && !is_new_bin {
        // Among many candidates, prefer tightest fit (already via post_residual),
        // slight extra nudge toward bins well below mean residual usage.
        score += 0.1 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);
    }

    // New-bin candidate: penalize unless it yields a tight fill or alternatives are poor.
    if is_new_bin {
        score += 35.0;
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 45.0 * tightness * tightness; // big items justify fresh bins
        if fitting_bins_count == 1 {
            score -= 30.0; // only alternative is a badly used old bin
        }
        if open_bins_count > 12 {
            score += 3.0 * (open_bins_count as f64 - 12.0); // too many open bins
        }
    }

    // Early stream: mild preference to consolidate into few bins.
    score += 5.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth polynomial shaping over progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear coupling: quadratic residual penalty grows as stream progresses
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Tight fits rewarded (small post_residual) more strongly late in stream
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Lookahead: reward if next item fits into post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 + 3.0 * (pr - next_item_size as f64) / cap;
    } else if next_item_size > 0 {
        // penalize residual that next item cannot use
        score += 2.0 * (1.0 - (next_item_size as f64 - pr) / cap);
    }

    // Slight preference for bins below mean residual (consolidating fuller bins)
    score += 0.3 * (pr - mean_residual);

    // New-bin candidate: penalize mildly unless post-residual is large enough
    // to serve future items (encouraged when current bin fits are poor)
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Residuals in "useful" classes (able to hold
    // common small items) are penalized less; tiny unusable slivers are
    // penalized heavily.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0.0 .. 1.0

    // Integer-division thresholds on post_residual (harmonic classes):
    // class 0: 0 (perfect fit)  class 1: 1..=10 (dead sliver)
    // class 2: 11..=25 (small item fits) class 3: 26..=50 (medium)
    // class 4: 51..=100 (large space)
    let class: u32 = match post_residual {
        0 => 0,
        1..=10 => 1,
        11..=25 => 2,
        26..=50 => 3,
        _ => 4,
    };
    let class_penalty: f64 = match class {
        0 => -12.0,           // perfect fit: strongly reward
        1 => 18.0,            // dead sliver: strong penalty
        2 => -2.0,            // usable for small items
        3 => 0.0,
        _ => 3.0,             // large leftover suggests poor packing
    };
    score += class_penalty;

    // Modulo-arithmetic bonus: residuals divisible by common item granularities
    // (10s and 5s) are more likely reusable by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Coupling with next item: if the next item fits exactly into the
    // post-residual, this is a two-item perfect chain — big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            // next item fits but leaves another residual: mild reward scaled
            // by how tight the chain is.
            let chain_left = post_residual - next_item_size;
            score -= 6.0 - (chain_left as f64 / cap) * 6.0;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size as f64 - pr) / cap * 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + (item_size as f64 / bin_residual as f64) * 10.0;
    }

    // Tightness reward: reward filling a large fraction of the bin.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * fill * 10.0;

    // New-bin candidate handling: empty bin should win only when no open bin
    // offers a decent fit. Penalize the fresh bin mildly by default, scaled
    // with stream progress and the number of open bins.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 14.0 + 6.0 * progress + (open_bins_count as f64).sqrt() * 2.0;
        // If the mean residual across open bins is large, opening new bins is
        // wasteful — penalize the new-bin option more.
        if mean_residual > 25.0 {
            score += (mean_residual - 25.0).min(40.0);
        }
        // But if the item is huge relative to typical residual, allow new bin.
        if (item_size as f64) > mean_residual + 15.0 {
            score -= 20.0;
        }
    }

    // Mild preference to spread load when many bins are open and this bin is
    // far below mean residual (balances residual distribution).
    if bin_residual != bin_capacity {
        let dev = mean_residual - pr;
        if dev > 0.0 {
            score += dev * 0.05;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. Anything below the minimum item size (1) is pure
    // waste; gaps in the "unusable small" band (1..=12) are penalized extra.
    if post_residual == 0 {
        score -= 40.0; // perfect fill is ideal
    } else if post_residual < 12 {
        score += (12 - post_residual) as f64 * 3.0; // unusable dead space
    } else if post_residual <= 25 {
        score += 6.0; // awkward mid-gap
    }

    // Reward bins whose residual was already small (tight packing direction).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.15;

    // Lookahead: if the next item fits exactly in the post residual, strongly
    // favor this bin; if next item cannot fit here, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a
    // new bin unless the fit would create terrible dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new one is relatively cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (1.0 - progress);

    // New-bin candidate: make it attractive only when fit is poor elsewhere.
    if bin_residual == bin_capacity {
        score -= 5.0;
        // Penalize opening a new bin when a decent fit exists in open bins.
        if post_residual > 0 && fitting_bins_count > 0 {
            score += mean_residual * 0.3 + 10.0;
        }
    }

    // Small nudge toward bins close to the mean residual (balanced closing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus proportional to how snugly the next item fits afterwards.
            let after_next = post_residual - next_item_size;
            score -= 30.0 + (after_next as f64).min(20.0);
        } else {
            // Penalize leaving a gap that the next item cannot use.
            score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Small dead space is nearly as good as a perfect fit.
        score -= 40.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize very sparse packing states early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 8 && progress < 0.5 {
        score += 5.0;
    }

    // New-bin candidate: make it unattractive unless it is genuinely needed
    // (large item with no good fit elsewhere is handled by the last-chance bonus above).
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if next item is huge and this bin would hold both, allow opening.
        if next_item_size > 0 && post_residual >= next_item_size && item_size > 60 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit bonus: strongly reward zero waste
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty for small dead space relative to capacity
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste_frac * waste_frac;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0;
        } else if post_residual >= next_item_size {
            // mild reward: bin stays usable for next item
            score -= 0.3 * next_item_size as f64;
        } else {
            // dead space blocks the next item: penalize proportionally to unusable gap
            let gap = post_residual as f64;
            score += 0.5 * gap * (1.0 + progress);
            // extra penalty if next item would fit nowhere else (this bin's waste is final)
            if gap < next_item_size as f64 && gap < 10.0 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless current
    // alternatives are all poor fits. Penalize the empty-bin candidate.
    if bin_residual == bin_capacity {
        // base opening cost
        score += 120.0;
        // cheaper to open bins early in the stream (amortization over future items)
        score -= 80.0 * (1.0 - progress);
        // if many bins are open and none fit well, opening is more acceptable
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        // don't proliferate bins when existing ones have large residuals
        if mean_residual > item_size as f64 + 15.0 {
            score += 60.0;
        }
    } else {
        // Slight preference for tighter existing bins (best-fit flavor)
        score -= 0.2 * (bin_capacity - bin_residual) as f64;
        // Reward using bins with residual close to the item (tight fit)
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= 25.0 * tightness;
    }

    // Global pressure: when many bins are open with high mean residual,
    // encourage consolidating into existing bins
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Discard trivially tiny residuals late in the stream (they rarely get used)
    if post_residual > 0 && post_residual < 5 {
        score += 10.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - progress) + 0.5 * pr_norm * progress;
    score += 40.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 20.0 * (1.0 - pr_norm) * (0.5 + progress);

    // Penalize dead space relative to mean residual of open bins
    score += 0.3 * (pr - mean_residual) * (1.0 - progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: bonus if next item fits the resulting post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / cap);
        } else {
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress * pr_norm;

    // New-bin candidate: neutral baseline with slight progress-dependent cost
    if bin_residual == bin_capacity {
        score = cap * (0.5 + 0.5 * progress) + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual (capacity fraction buckets)
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let class = (post_residual * 4 / bin_capacity) as u32; // 0..3 quarter classes

    // Reward exact or near-perfect packing
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Reward when lookahead item fits exactly into the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // small residual gap => good chaining
            let gap = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - gap / cap);
        } else {
            // lookahead cannot fit here: penalize creating dead space
            score += 0.5 * ((next_item_size - post_residual) as f64);
        }
    }

    // Harmonic class penalties: quarter-class residuals of 25/50/75 are
    // more reusable than odd residuals; odd (non-multiple of 5) residuals are worst
    if post_residual % 10 == 0 {
        score -= 40.0;
    } else if post_residual % 5 == 0 {
        score -= 20.0;
    } else {
        score += 15.0;
    }

    // Quarter-class shaping
    match class {
        0 => score -= 60.0,           // nearly full bin: excellent
        1 => score -= 10.0,           // ~25 residual: moderately useful
        2 => score += 5.0,            // ~50 residual: neutral
        _ => score += 10.0,           // mostly empty: weak placement
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when no good fit exists among open bins
    if bin_residual == bin_capacity {
        // penalize opening new bins mildly; the open-bin bonuses above usually win
        score += 80.0;
        // but if mean residual of open bins is too small for the item, new bin is fine
        if mean_residual < item_size as f64 {
            score -= 150.0;
        }
        // late in the stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Slight preference for tighter bins overall (compare against mean residual)
    score -= 0.3 * (mean_residual - post_f);

    // Tie-break: favor filling bins with more content already
    score -= 0.1 * (bin_residual as f64 - post_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Dead space is worse if the next item cannot use the leftover gap.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 6.0;
    }
    // Reward a residual that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidation into
    // existing bins over spreading; penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        score += 15.0 + pressure;
    } else {
        score -= 2.0 + pressure * 0.1;
    }

    // Last-chance bin: strongly prefer using it before a new bin opens.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild preference toward bins with tighter residuals (dense bins).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit after placement: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (chains two items perfectly).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Partial lookahead reward: next item still fits in the leftover space.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.0;
    }
    // Dead space: leftover too small for the next item is wasted unless tiny.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (post_residual as f64) * 1.5;
    }

    // Reward tight fits relative to current bin residual (small waste ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 50.0;

    // Prefer bins with residuals below the mean (consolidate emptier space usage).
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is huge
    // and stream is early (many items remain to fill the fresh bin).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let new_bin_penalty = 150.0 - (item_size as f64) * 0.8 - (1.0 - progress) * 60.0;
        score += new_bin_penalty.max(-100.0);
    }

    // Slight preference to fill bins with more items already (fewer partially
    // filled bins lingering) as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity - bin_residual) as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize leaving small, hard-to-use slivers (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins, penalize new-bin tendency.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.05);
    score += 0.4 * crowding * (0.5 + 0.5 * progress);

    // Late in the stream, prefer tighter packing overall (closer to mean residual).
    score += 0.3 * (post_residual as f64 - mean_residual).abs() * progress;

    // New-bin candidate: penalize opening a fresh bin unless existing bins are truly bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 8.0; // pairing large items together is fine later
        }
        if fitting_bins_count <= 1 {
            score -= 35.0; // no real alternative, allow new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);

    // Base: minimize wasted space, non-linearly shaped.
    let mut score = pr * (1.0 + 0.02 * pr / cap);

    // Tight-fit reward: quadratic bonus for small post_residual.
    let tightness = 1.0 - pr / cap;
    score -= 30.0 * tightness * tightness * tightness;

    // Stream-progress coupling: penalize large residuals more as stream ends,
    // since late dead space is less likely to be filled.
    let late = progress * progress;
    score += 20.0 * late * (pr / cap);

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize leaving mid-range gaps.
        score += 6.0 * (pr / cap) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: with many open bins, prefer filling existing ones.
    let crowd = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).ln();
    score += 5.0 * crowd * (pr / cap);

    // Mean-residual coupling: if this bin is below-average residual (tighter),
    // favor placing here.
    score -= 8.0 * ((mean_residual - pr) / cap).tanh();

    // New-bin candidate: penalize opening a fresh bin unless residual waste
    // would be severe or stream is early with room to consolidate.
    if bin_residual == bin_capacity {
        let waste_severity = (pr / cap).max(0.0);
        let early_bonus = 1.5 * (1.0 - progress);
        score = 15.0 + 40.0 * (1.0 - waste_severity) - early_bonus
            + 10.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes (e.g. 10, 20, 25, 50) are "reusable" classes; penalize
    // awkward odd residues that become dead space.
    let r = post_residual;
    if r == 0 {
        score -= 25.0; // perfect fit
    } else {
        let mut bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            if r % m == 0 { bonus += 4.0; }
        }
        if r % 5 == 0 { bonus += 1.5; }
        score -= bonus;
        // Odd residuals (not divisible by 2 or 5) are poor classes
        if r % 2 == 1 && r % 5 != 0 { score += 3.0; }
        // Small unusable slivers
        if r < 10 { score += 12.0; }
    }

    // Integer-division threshold: does the next item fit into the post-residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // harmonic check: post_residual - next_item_size lands on a good class
        let r2 = post_residual - next_item_size;
        if r2 % 10 == 0 { score -= 3.0; }
        if r2 == 0 { score -= 4.0; }
    } else if next_item_size > 0 {
        // next item cannot follow here; if this bin is the last chance, use it anyway
        if fitting_bins_count == 1 && bin_residual >= item_size {
            score -= 8.0;
        }
        score += 2.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tight = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // prefer new bin when mean residual is large (existing bins are fragmented)
        score = 15.0 + 40.0 * (1.0 - tight) - 25.0 * pressure;
    } else {
        // last-chance bin reward
        if fitting_bins_count == 1 { score -= 10.0; }
        // prefer tighter fits relative to mean residual
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    // Late-stream consolidation: favor filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 12) are dead space; penalize heavily.
    if post_residual < 12 {
        score += 40.0 + (12 - post_residual) as f64 * 3.0;
    }

    // Penalize "almost dead" gaps that next_item_size cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward perfect/near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual >= 12 {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 2.0 + mean_residual * 0.1;
    } else {
        // Slight preference for tighter bins (smaller residual before placing).
        score += (bin_residual as f64) * 0.05;
    }

    // Late in the stream, consolidate: avoid spreading across new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 / (1.0 + diff);
        // Perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize post_residual slightly below next item (dead space blocking lookahead)
        if post_residual > 0 && post_residual < next_item_size {
            score += 25.0;
        }
        // Bonus if the next item would also fit after this placement (2-chain)
        if post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    let res = post_residual as f64;
    score += 0.35 * (res - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Penalize wasteful near-full leftovers less if many bins open (encourage consolidation)
    if open_bins_count > 3 {
        score -= 8.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when item is large relative to residual
    if bin_residual == bin_capacity {
        let tight_fit = (item_size as f64 / bin_capacity as f64) > 0.7;
        if tight_fit && next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 20.0; // fresh bin supports a clean chain
        } else {
            score += 15.0; // generally discourage opening new bins
        }
    }

    // Progression: as stream advances, prioritize filling existing bins more tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space is exponentially costly).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 60.0 + 10.0 * (6 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize leaving large residuals that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // awkward dead zone
    }
    if post_residual > 70 {
        score += 15.0; // still flexible, mild penalty vs medium gaps
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: reward placements that let the next item fit exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += 5.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Global pressure: when many open bins exist, prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 8.0 * pressure;
    } else {
        // New-bin candidate: penalize more when open bins already exist and mean residual is large.
        score += 30.0 + 6.0 * pressure + 0.3 * mean_residual;
    }

    // Time horizon: early in the stream be more open to new bins; late, consolidate.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 40.0 * t;
    } else {
        score -= 15.0 * t;
    }

    // Mild preference for bins with residual close to mean residual (balanced packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to stream progress.
    // Late in the stream, residual space matters more (less time to fill it).
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize awkward mid-range residuals via smooth quartic centered on half capacity.
    let dev = fit - 0.5;
    score += 30.0 * dev * dev * (1.0 + progress);

    // Reward tight fits (small post_residual relative to capacity) with a smooth decay term.
    score -= 25.0 * (-pr / (0.25 * cap)).exp();

    // Last-chance bonus: strongly favor using a scarce fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // Mild penalty when many bins compete, smoothed by open bin count.
        score += 5.0 * (fitting_bins_count.min(10) as f64) / 10.0;
    }

    // Lookahead: reward residuals that can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (-slack / (0.35 * cap)).exp();
    } else if next_item_size > 0 {
        score += 6.0 * progress;
    }

    // Dampen preference for very full bins when mean residual is high (bins are plentiful).
    score += 0.15 * mean_residual * fit;

    // Slight penalty for opening new bins early in the stream.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) * (1.0 + (open_bins_count as f64).ln().max(0.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (quarters, fifths, tenths)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward post_residuals that are "harmonic" divisors of capacity -> highly reusable
    let harmonic_bonus: f64 = if post_residual == 0 {
        -40.0 // perfect fit is best
    } else if bin_capacity % post_residual == 0 && post_residual <= bin_capacity / 2 {
        -25.0 // exact divisor of capacity (50, 25, 20, 10...)
    } else if post_residual % 10 == 0 {
        -12.0 // decile residual
    } else if post_residual % 5 == 0 {
        -6.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize small dead space (< 10 cannot fit any item) unless zero
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Coupling with next item: reward if next item fits exactly or well in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 18.0 - (slack as f64) * 0.3; // lookahead fit bonus
            if post_residual % next_item_size == 0 {
                score -= 10.0; // harmonic division: next item splits residual cleanly
            }
        } else {
            score += 8.0; // next item won't reuse this bin
        }
    } else {
        // Last item: only zero residual matters
        if post_residual > 0 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // but allow it when item is large and no bin fits harmonically
    if bin_residual == bin_capacity {
        let good_fit_exists = mean_residual >= item_size as f64 && fitting_bins_count > 0
            && (mean_residual - item_size as f64) >= 10.0;
        if good_fit_exists {
            score += 35.0;
        } else {
            score += 10.0 * frac; // mild penalty; large items may still open new bins
        }
    }

    // Stream progression: early on, be greedy about tight fits; later, consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (bin_residual - post_residual) as f64 * 0.15; // reward fill amount early
    score += progress * (open_bins_count as f64) * 0.5; // later, prefer fewer-bin consolidation pressure

    // Mean residual coupling: if this bin is far below mean residual, it's a "ragged" bin; prefer filling it
    if (mean_residual - bin_residual as f64).abs() > 25.0 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest future item (<= 1..10) are pure waste. Penalize
    // the "unusable gap" region super-linearly.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: heavily reward closing a bin exactly.
        score -= 60.0;
    }

    // Reward tight fits relative to residual (low waste ratio).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fill_ratio * fill_ratio;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use this residual: if post residual is small,
            // it becomes dead space for the lookahead too.
            if post_residual < next_item_size {
                score += 8.0;
            }
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidation
    // (penalize spreading); with few bins, opening new bins is cheap.
    let bin_pressure = open_bins_count as f64;
    score += 0.8 * bin_pressure;

    // Last-chance bin: if this is the only bin that fits, avoid forcing
    // a bad fit unless the fit is actually good.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual as f64 <= mean_residual {
            score -= 25.0; // decent fit in the only option
        } else {
            score += 15.0; // poor fit; let a new bin win instead
        }
    }

    // New-bin candidate handling: an empty bin should win only when the
    // item is large relative to capacity or fits elsewhere are terrible.
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin; slightly encourage when item
        // is big (few future chances to pack it tightly).
        score -= 5.0 + (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Mean-residual coupling: bins far below mean residual are "fresher";
    // prefer filling bins with residual above the mean first.
    let res = post_residual as f64;
    if res > mean_residual {
        score += 0.3 * (res - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - res);
    }

    // Mild stream-progression term: late in the stream, avoid leaving
    // scattered small residuals since fewer items remain to fill them.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }

    // Post-residual can still hold the next item: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space relative to the lookahead item: penalize unusable remainder.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.6 * dead;
    }

    // Very tight fit (small post_residual) is generally good unless it blocks the next item.
    if post_residual <= 10 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving residual far from the mean (fragmentation signal).
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev.abs();

    // Relative fill bonus: fuller bins preferred over emptier ones.
    score -= 20.0 * (1.0 - (bin_residual as f64 / bin_capacity as f64));

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., few fitting bins and current bin is empty).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 45.0 + 5.0 * fitting_bins_count as f64;
        }
    }

    // Late in the stream, consolidate: penalize opening extra bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement sets up a perfect chain — reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 3.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are fragmented (high mean residual spread) or late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Base reluctance to open new bins when few are open.
        score += 15.0 + 0.5 * open_bins_count as f64;
        // But if existing bins are poor fits (large mean residual vs item), relax.
        score -= 10.0 * (mean_residual / bin_capacity as f64);
        // Late in the stream, avoid opening bins that will stay nearly empty.
        score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);
        // If many bins can fit the item elsewhere, discourage new bin.
        if fitting_bins_count > 1 {
            score += 10.0;
        }
        let _ = fragmentation;
    }

    // Mild global pressure: when many bins are open, consolidate into emptier ones.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Slight time-horizon term: early on, be greedy about filling; late, be conservative.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling: post_residual shaped by stream progress
    let shape = norm_pr * norm_pr * (1.0 + progress) - norm_pr * (0.5 + 0.5 * progress);
    score += 20.0 * shape;

    // Tight-fit reward, amplified late in the stream
    let tight = (bin_residual as f64 - item_size as f64) / cap;
    score -= 15.0 * (1.0 - tight).powi(3) * (0.5 + progress);

    // Penalize dead space relative to mean residual
    score += 5.0 * (pr - mean_residual).abs() / cap * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - fit_ratio);
    }

    // Lookahead: reward bins whose post residual could host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 4.0 * progress * (1.0 - norm_pr);
    }

    // Mild penalty for many open bins early
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: reward residuals that are
    // "friendly" sizes (multiples of small divisors of capacity), penalize
    // awkward leftovers via a modulo-based dead-space detector. ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Harmonic classes: residuals near multiples of 25 (capacity/4) or 50
    // (capacity/2) are more reusable by typical item sizes.
    let h25 = (post_residual % 25) as f64;
    let h50 = (post_residual % 50) as f64;
    let h10 = (post_residual % 10) as f64;

    // Distance to nearest "harmonic" grid point (multiples of 25).
    let d25 = h25.min((25 - h25) as f64);
    let d50 = h50.min((50 - h50) as f64);
    let d10 = h10.min((10 - h10) as f64);

    // Reward alignment with the coarse grid, extra reward for fine grid.
    score -= 6.0 * (1.0 - d25 / 12.5);
    score -= 2.0 * (1.0 - d10 / 5.0);
    if d50 < 1.0 {
        score -= 4.0; // exact half-capacity residual is very valuable
    }

    // Integer-division thresholds on post_residual: class bins.
    let pr_class = post_residual / 10; // 0..=10
    match pr_class {
        0 => score += 8.0,             // tiny leftover: near-perfect fill
        1 | 2 => score -= 5.0,         // sweet spot 10..=29
        3 | 4 => score -= 2.0,         // decent
        5 => score -= 6.0,             // exactly half-full: very reusable
        6 | 7 => score -= 1.0,
        _ => {}                        // large residual: neutral, base term dominates
    }

    // --- Lookahead coupling: if the next item fits exactly into the
    // post_residual, strongly favor this bin. ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward tight next-fits, penalize large slack after the next item.
            score -= 10.0 * (1.0 - slack / cap).max(0.0);
            // Harmonic check: does the pair leave a harmonic residual?
            let pair_res = post_residual - next_item_size;
            if pair_res % 25 == 0 || pair_res % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; mild penalty grows with how close it is,
            // since a near-miss suggests this residual is awkward.
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 20.0 {
                score += 3.0 * (1.0 - miss / 20.0);
            }
        }
    }

    // --- Last-chance logic: if this is the only bin that fits, prefer using it
    // unless the fit is terrible. ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        // But if post_residual would be a very awkward tiny sliver, soften reward.
        if post_residual > 0 && post_residual < 5 {
            score += 6.0;
        }
    }

    // --- New-bin candidate handling: the empty bin has bin_residual == capacity,
    // so post_residual == capacity - item_size. Give it a baseline so that open
    // bins with good fits beat it, but allow it to win when fits are bad. ---
    if bin_residual == bin_capacity {
        // Neutral baseline: raw post_residual already large; add a mild bias
        // that shrinks as the stream progresses (late stream: prefer closing bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 - 4.0 * progress;
        // Opening new bins when many are already open and mean residual is high
        // is wasteful; penalize.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 4.0;
        }
    } else {
        // Prefer tighter fits among open bins: reward small post_residual
        // relative to mean residual across open bins.
        if pr < mean_residual {
            score -= 3.0 * (1.0 - pr / mean_residual.max(1.0));
        }
    }

    // --- Progress modulation: early in the stream, keep bins flexible
    // (penalize very small residuals slightly less); late, pack tightly. ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        // Late stream: aggressive compaction.
        score -= 2.0 * (1.0 - frac);
    } else if progress < 0.2 {
        // Early stream: slight penalty for leaving tiny unusable residuals.
        if post_residual < 10 && post_residual > 0 {
            score += 2.0;
        }
    }

    // Item-size harmonic class: large items placed into large-residual bins
    // (mod-20 classes) keep the structure tidy.
    if item_size % 20 == 0 && post_residual % 20 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Prefer tighter fits: relative fill ratio bonus.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    // (i.e., this bin would leave large dead space or item barely fits nothing).
    if bin_residual == bin_capacity {
        // Baseline competitiveness for a fresh bin.
        score = (bin_capacity - item_size) as f64;
        // If many bins fit, prefer using an existing one.
        if fitting_bins_count > 0 {
            score += 10.0 + 5.0 * fitting_bins_count as f64;
        }
        // Lookahead: if next item could combine with current item in a fresh bin,
        // opening a new bin is more attractive.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0;
        }
        // Late in stream, avoid opening new bins.
        score += 20.0 * (step_index as f64 / total_items as f64);
    }

    // Lookahead: if post_residual exactly matches next item, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it's a good consolidation target.
    let this_residual = bin_residual as f64;
    if this_residual < mean_residual {
        score -= 0.5 * (mean_residual - this_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep it neutral-to-attractive only if no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55;
        if fitting_bins_count <= 1 {
            score -= 40.0; // prefer opening a new bin over a last-chance bad fit
        }
        return score;
    }

    // --- 2-step lookahead: how well does post_residual match the next item? ---
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;

        if post_residual >= next_item_size {
            // Next item fits exactly -> huge reward.
            let diff = (pr - ns) as f64;
            if diff < 1.0 {
                score -= 60.0;
            } else {
                // reward proportional to tightness of the follow-up fit
                score -= 25.0 * (1.0 - diff / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: penalize dead space left behind.
            score += 15.0 + pr * 0.25;
        }
    } else {
        // Last item: pure best-fit behavior.
        score -= 30.0;
    }

    // Reward tight fits relative to mean residual across open bins.
    let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 20.0;

    // Penalize bins far above mean residual (wasteful large holes).
    if (post_residual as f64) > mean_residual {
        score += ((post_residual as f64) - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 3 {
        // Many options: be pickier, prefer the tightest.
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Early in stream: slightly favor consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += tightness * 120.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leftover after it matters
            let chain_waste = post_residual - next_item_size;
            score -= 40.0 - chain_waste as f64 * 0.5;
        } else {
            // next item won't fit here; mildly penalize bins leaving awkward residuals
            score += 10.0;
        }
    }

    // Penalize creating dead space smaller than the smallest plausible item (<= ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // New-bin candidate logic: an empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open new bin early in stream or when many bins already open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // if existing bins are fragmented (high mean residual but item doesn't fit well), new bin attractive
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if mean_residual > 0.0 && (bin_residual as f64 - item_size as f64) > mean_residual {
            score -= 10.0;
        }
    }

    // Mild preference for filling bins with lower residual relative to the mean (consolidation)
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Slight time pressure: as stream ends, prefer closing out bins (reduce open bin count)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.9 && bin_residual < bin_capacity {
        score -= 15.0 * (progress - 0.9) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, residual waste is more forgivable; late in the stream,
    // wasting space is penalized super-linearly.
    let t = progress * (progress - 1.0); // negative in (0,1), smooth
    score += pr * pr / cap * (1.0 + 2.0 * (1.0 - progress)) - 3.0 * t * pr;

    // Reward tight fits: normalized fill ratio coupling.
    let fill = item_size as f64 / cap;
    score -= fill * fill * cap * 0.5;

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 10.0 * (1.0 - (pr - nxt).abs() / cap);
        } else {
            // next item won't fit here: slight penalty proportional to leftover
            score += 2.0 * (pr / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening bins when many bins are already open relative to progress
    // (encourages consolidation), but only for the brand-new-bin candidate.
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * (open_bins_count as f64) * (1.0 - progress);
        // If existing bins fit poorly (high mean residual mismatch), opening new is fine.
        let mismatch = (mean_residual - pr).abs();
        score -= mismatch * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base tightness reward: quadratic in post_residual (favor near-perfect fills).
    score += 0.015 * (post_residual as f64).powi(2) / cap;

    // Harmonic class of post_residual: residual classes mod 10.
    // Residuals that are multiples of 10 are "harmonic" — likely reusable by
    // common item sizes; odd fragments are dead-space prone.
    let pr = post_residual;
    let class = pr % 10;
    let class_bonus = match class {
        0 => -6.0,
        1 | 9 => 4.0,
        2 | 8 => 1.0,
        3 | 7 => 2.0,
        _ => 0.0,
    };
    score += class_bonus;

    // Integer-division threshold: post_residual bucketed by quarters of capacity.
    let quarter = bin_capacity / 4;
    if pr >= 3 * quarter {
        score -= 3.0; // large residual is flexible
    } else if pr < quarter {
        score += 2.0 * (quarter as f64 - pr as f64) / cap; // tiny sliver penalty
    }

    // Exact fit is golden.
    if pr == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && pr >= next_item_size {
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 18.0;
        } else if gap % 10 == 0 {
            score -= 5.0;
        } else {
            score += 0.05 * gap as f64;
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's residual: penalize slightly more when residual small
        score += 1.0 + (next_item_size as f64 - pr as f64).max(0.0) * 0.02;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate (pristine): make it unattractive unless existing bins are
    // badly fragmented and open_bins_count is large.
    if bin_residual == bin_capacity {
        let frag = (mean_residual - (bin_capacity - item_size) as f64).abs();
        let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64);
        score = cap as f64 + 0.10 * frag + pressure * 2.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is correct
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // pair large items together in fresh bins
        }
    }

    // Mild preference to fill older/scarce bins when many are open.
    score += 0.15 * open_bins_count as f64 * (bin_residual as f64 / cap);

    // Stream progression: late in stream, tighten more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (pr as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance: small unusable gaps are heavily penalized ---
    if post_residual > 0 && post_residual < 10 {
        // Gap too small for any item (min size 1..100 unknown, but treat <10 as near-dead)
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual > 0 && post_residual < 5 {
        // Truly dead space: extra escalating penalty
        score += 60.0;
    }

    // --- Reward tight fits (small post_residual relative to item size) ---
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // --- Last-chance pressure: if this is the only fitting bin, strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // --- Open-bins pressure: discourage spreading across many open bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // New bin is attractive if current open bins have large unusable residuals,
        // or if the item would leave dead space in an existing bin.
        let dead_in_existing = post_residual > 0 && post_residual < 20;
        if dead_in_existing {
            score -= 55.0; // prefer fresh bin over creating dead space
        } else {
            score += 30.0 + 5.0 * open_bins_count as f64; // keep using open bins otherwise
        }
        // If next item is large, a fresh bin with full capacity is valuable
        if next_item_size > 0 && next_item_size >= 50 && post_residual < next_item_size as u32 {
            score -= 20.0;
        }
    }

    // --- Lookahead: penalize placing item if it blocks the next item ---
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // reward leaving room for the next item
    }

    // --- Mean residual coupling: bins far below mean residual are worth filling ---
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but with a non-linear penalty
    // for large waste so that tiny post_residuals are strongly favored.
    score = (post_residual as f64).powf(1.35);

    // 2-step lookahead: strongly reward bins whose post_residual can host the
    // next item exactly or nearly; penalize when next item barely misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            // Reward chains: perfect chain (slack 0) gets big discount.
            score -= 30.0 * (1.0 - slack / pr.max(1.0));
            // Extra bonus if next item fills the bin completely after chaining.
            if slack == 0.0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            let over = (nxt - pr) / bin_capacity as f64;
            score += 15.0 * over;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight"
    // bins; using them for a good fit preserves loose bins. Reward placing into
    // tighter-than-mean bins when the fit is good.
    let tightness = (mean_residual - bin_residual as f64) / bin_capacity as f64;
    if tightness > 0.0 {
        score -= 8.0 * tightness.min(1.0);
    } else {
        score += 4.0 * (-tightness).min(1.0);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        // But if post_residual becomes dead space (< smallest plausible item ~ 1..100),
        // relax the discount so we don't hoard a doomed bin.
        if post_residual < 10 {
            score += 18.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer reusing open
    // bins unless their fit is bad. Penalize the fresh bin mildly, scaled by how
    // many open bins exist and stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 10.0 * (open_bins_count as f64).ln1p() + 15.0 * (1.0 - progress);
        // Exception: if item is large relative to capacity, a fresh bin is natural.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Slight penalty for leaving residual in the awkward mid-range (hard to fill).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 25.0 {
        score += 6.0 * (1.0 - pr / 25.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = fit_ratio < 0.6;
        if poor_fit && fitting_bins_count >= 1 {
            score -= 10.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            score += 20.0 + 30.0 * progress;
        }
    }

    // Global pressure: many open bins with large mean residual -> prefer consolidating.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 4.0;
    }

    // Discourage wasting a nearly-full bin on a tiny item.
    if bin_residual < bin_capacity && item_size < 20 && post_residual > 60 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: tight fit (low post residual) is good.
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tolerate larger residuals (keep flexibility); late, punish dead space harder.
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score += progress_weight * (post / cap) * (post / cap) * 20.0;

    // Reward near-perfect fills with a smooth cubic term.
    let tightness = 1.0 - post / cap;
    score -= 15.0 * tightness * tightness * tightness;

    // Last-chance bin: strong bonus if this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * tightness;
    }

    // If the next item would fit exactly in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 1e-9 {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size as f64 <= post {
        // Next item fits but not perfectly: mild reward scaled by slack left after both.
        let after_next = post - next_item_size as f64;
        score -= 10.0 * (1.0 - after_next / cap);
    } else if next_item_size > 0 {
        // Next item will NOT fit here: penalize leaving a medium-sized unusable gap.
        let gap_ratio = post / cap;
        score += 12.0 * gap_ratio * (1.0 - gap_ratio) * 4.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        // Cost of opening a new bin decreases as stream progresses (fewer future chances to amortize).
        let open_cost = 40.0 * (1.0 - 0.5 * progress);
        // Attractive if mean residual of open bins is small (open bins are nearly full).
        let mean_tight = 1.0 - (mean_residual / cap);
        score = post + open_cost - 20.0 * mean_tight * mean_tight;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Slight penalty for spreading across many open bins (encourage consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * (post / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (1/4, 1/3, 1/2, 3/4 of capacity).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Dead-space penalty: residuals that cannot host typical items are wasted.
    // Class boundaries via integer division thresholds.
    let class = post_residual / (bin_capacity / 4); // 0..=4 harmonic class
    match class {
        0 => score += 30.0,                     // <25% left: near-dead bin
        1 => score -= 2.0,                      // 25-50%: useful slot
        2 => score -= 6.0,                      // 50-75%: very useful
        3 => score -= 4.0,                      // 75-100%: good but loose
        _ => score -= 8.0,                      // exact fit / empty-ish
    }

    // Perfect-fit resonance: post_residual divisible by small harmonics
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 5.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
    } else {
        score -= 25.0; // exact fill is ideal
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // harmonic match: next item aligns with residual class
        let nclass = next_item_size / (bin_capacity / 4);
        if nclass == class && post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // last item: strongly prefer tightest fill
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 12.0 + 10.0 * (1.0 - frac);
    }

    // New-bin candidate handling: an empty bin has high raw residual; make it
    // attractive only when open bins are fragmented or the fit is bad.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted when many bins already open
        score = cap * 0.55 - (open_bins_count as f64).min(20.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin can host a follow-up large item
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    // Mild tightness term relative to mean residual: prefer bins tighter than average
    score += (mean_residual - pr) * 0.1;

    // Stream-phase modulation: late in the stream, consolidate aggressively.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= phase * (cap - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot accommodate even the minimum item (size 1) is pure waste,
    // and gaps in the "awkward" mid-range (too small for typical items) are dead space.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // Dead-space zone: gaps below a mid threshold are quadratic-penalized.
        if post_residual < 10 {
            score += 60.0 + (10.0 - pr) * 8.0;
        } else if post_residual < 30 {
            score += (30.0 - pr) * 3.0;
        }
    }

    // Perfect fit reward: strongly favor zero residual.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Exact fit to a known next item: huge bonus (lookahead pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 5 {
        score -= 10.0; // near-perfect two-item packing
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate and any bin less urgently).
    let pressure = (open_bins_count as f64) * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless open bins are few and this item is large.
        score += 40.0 + pressure;
        if item_size > bin_capacity / 2 && open_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Favor placing into tighter existing bins (best-fit coupling).
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Stream progression: later in the stream, closing bins tightly matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.1;

    // Mean residual coupling: if average residual is high, prioritize compacting bins.
    score += (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual), with quadratic pressure.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits into the residual left behind -> strong bonus.
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.4; // exact match (slack=0) gets -30
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to the overflow.
        let overflow = (next_item_size - post_residual) as f64;
        score += overflow * 0.35;
    }

    // Compare against mean residual: bins already tighter than average are
    // good targets; bins looser than average should be preserved.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.25;
    } else {
        score += (res - mean_residual) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline, penalized unless current
    // open bins would waste a lot of space.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: its full residual, discounted slightly
        // so it only wins when existing bins create large dead space.
        score = bin_capacity as f64 * 0.9;
        // If next item is small, a fresh bin is flexible.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 8.0;
        }
        // Fewer open bins -> opening one is cheaper.
        score -= open_bins_count as f64 * 1.5;
    }

    // Early stream: be slightly more willing to open bins to build a good spread.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize small post-residuals that are too small for the smallest future item (dead space),
    // but reward exact or near-exact closure.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    } else if post_residual == 0 {
        score -= 10.0; // perfect closure
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let nfit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 4.0 * nfit;
        } else {
            // post residual cannot host next item: penalize proportionally to wasted space
            score += 0.05 * (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a new bin, softened late in the stream
        // and when open bins have little usable room on average.
        let mut new_penalty = 20.0 - 8.0 * progress;
        let avg_room = mean_residual / bin_capacity as f64;
        if avg_room < item_size as f64 / bin_capacity as f64 {
            new_penalty -= 10.0; // open bins are cramped; new bin is reasonable
        }
        if open_bins_count == 0 {
            new_penalty = -5.0; // must open a bin
        }
        // New bin should not win when the item fits an open bin decently.
        score += new_penalty;
    }

    // Mild global pressure: many open bins -> prefer consolidating into existing ones.
    score += 0.3 * open_bins_count as f64 * (1.0 - fit_ratio).max(0.0);

    // Deviation from mean residual: prefer bins whose residual is close to the item,
    // i.e., avoid dumping large items into already-loose bins unnecessarily.
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;
    let mut score = r;

    // Smooth non-linear coupling: post-residual scaled by progress-dependent polynomial
    let progress_weight = 0.5 + 0.5 * t * t;
    score += progress_weight * (rn * (1.0 - rn)) * cap * 0.3;

    // Penalize large residual more as stream progresses (dead space matters later)
    score += t * r * r / cap * 0.05;

    // Reward tight fits (small post_residual) with smooth exponential bonus
    score -= 20.0 * (-r / 15.0).exp();

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post-residual
    if next_item_size > 0 {
        let fits_next = (r >= next_item_size as f64) as i32 as f64;
        score -= fits_next * 10.0 * (1.0 - t);
    }

    // Encourage consolidation when many bins open
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - rn);

    // Deviation from mean residual: prefer bins near mean to keep balance
    score += ((r - mean_residual) / cap).abs() * 5.0;

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty reduction as post_residual shrinks.
    let tight = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 14.0 * tight * tight;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic class logic: classify residual into capacity-fraction classes.
    // Items whose size falls in the same "class" as the residual waste less.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let item_class = if item_size > half { 3 } else if item_size > quarter { 2 } else { 1 };
    let resid_class = if bin_residual > half { 3 } else if bin_residual > quarter { 2 } else { 1 };
    if item_class == resid_class {
        score -= 8.0; // same harmonic class => natural fit
    } else if item_class > resid_class {
        score += 6.0; // item bigger than residual class => poor coupling
    }

    // Integer-division threshold on post_residual: dead space that no
    // plausible item (>=1) can use should be penalized less harshly than
    // awkward small remainders. Remainders in (0, 10) are the worst.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Modulo arithmetic on post_residual: multiples of small item sizes
    // (common in streams) are reusable remainders.
    for m in [5u32, 10, 20, 25, 50] {
        if post_residual >= m && post_residual % m == 0 {
            score -= 3.0 + (m as f64) * 0.1;
        }
    }

    // Lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= 10.0 - 0.15 * lookahead_fit.min(30.0) as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use leftover; mild penalty scaled by waste.
        score += 0.08 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin wastes all existing
    // residual space. Penalize it unless open bins are nearly full on
    // average and this bin would be the fresh one.
    if bin_residual == bin_capacity {
        // Fresh bin: base cost of one capacity unit of waste.
        score = bin_capacity as f64 * 0.9;
        // At stream start, opening bins is fine.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If existing bins are fragmented (mean residual low), new bin is ok.
        score -= (mean_residual / bin_capacity as f64).max(0.0).min(1.0) * 10.0;
        // If item is large, fresh bin keeps big residual for future big items.
        if item_size > half {
            score -= 6.0;
        }
    }

    // Mild preference for fewer open bins when many are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps are risky if the next item cannot use them.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Reward placements that still fit the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Tight-fit coupling: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: with many open bins, avoid spreading; with few bins,
    // tolerate looser fits rather than opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 2.0 * bin_pressure;

    // Penalize bins whose residual deviates far above the mean (fragmented state).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using the only bin that can fit the item,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open a bin early when few bins are open.
        score -= 1.5 * open_bins_count as f64;
        // If the current bin would leave a large dead gap, new bin becomes viable.
        if post_residual >= 40 {
            score -= 45.0;
        }
        // If the item nearly fills a fresh bin, opening is excellent.
        if fill_ratio > 0.8 {
            score -= 30.0;
        }
        // Never open a new bin when a perfect fit exists elsewhere.
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: residual after placement exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match bonus scaled by how close post_residual is to next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (30.0 / (1.0 + slack)).min(30.0);
    }
    // Penalize leaving dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward tight fits (small post_residual) more strongly as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (100.0 - post_residual as f64) * (0.3 + 0.4 * progress);

    // Relative-to-mean-residual coupling: prefer bins with residual below mean (already fragmented),
    // keep larger residual bins for future items.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.1;
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // When many bins fit the item, mild penalty to prefer consolidation into fuller bins.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening a new bin unless the item is large relative to
    // what open bins would leave behind, or there are no open bins yet.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 200.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin promises a good 2-step match
        } else {
            score += 40.0 + 0.3 * mean_residual;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (best-fit core).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space if next item can't fit here.
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global pressure: many open bins with small mean residual -> consolidate.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score -= 0.6 * pressure * (1.0 - tightness);

    // Time horizon: early in stream, be pickier (penalize loose fits more);
    // late in stream, accept decent fits to avoid opening bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 8.0 * tightness;
    score -= t * 5.0 * tightness;

    // New-bin candidate: only attractive when no good fit exists
    // (large residual spread / few fitting bins / item large relative to mean residual).
    if bin_residual == bin_capacity {
        let desperate = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let item_heavy = item_size as f64 / bin_capacity as f64;
        let spread = (mean_residual - bin_residual as f64).abs();
        let base = 55.0 - 25.0 * desperate - 20.0 * item_heavy - 0.3 * spread - 10.0 * t;
        score += base.max(2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping
    let mut score = x * (1.0 + 0.9 * x + 0.6 * x * x);

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter more
    let tightness = 1.0 - x;
    score -= 12.0 * tightness * tightness * progress;

    // Perfect-fit reward, amplified by progress
    if post_residual == 0 {
        score -= 20.0 + 15.0 * progress;
    }

    // Penalize waste relative to mean residual across open bins (smooth divergence term)
    let dev = (mean_residual - pr) / cap;
    score += 1.5 * dev * dev * cap * 0.1;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate: baseline score, adjusted by how well the item
    // would pair with the lookahead item (smooth interaction)
    if bin_residual == bin_capacity {
        let pair_waste = if next_item_size > 0 {
            ((cap - item_size as f64 - next_item_size as f64).max(0.0)) / cap
        } else {
            x
        };
        score = 6.0 + 10.0 * pair_waste * (1.0 - progress) - 4.0 * progress;
    }

    // Lookahead synergy: reward leaving exactly (or near) the next item's size
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score += 5.0 * gap * gap;
        if (pr as u32) == next_item_size {
            score -= 6.0;
        }
    }

    // Mild congestion penalty: prefer consolidating when many bins are open
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let class = post_residual / 10; // integer division: decile of dead space

    // Penalize dead space non-linearly; small residuals (<10) are "perfect" fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 100.0 + post_f * 2.0;
    } else {
        // Quadratic penalty on the decile class (harmonic weighting)
        score += (class as f64).powi(2) * 1.5;
    }

    // Reward filling bins whose residual is "harmonically compatible" with the item:
    // residual mod item_size small => future item could exactly fill remainder later.
    if item_size > 0 {
        let m = bin_residual % item_size;
        score -= (10 - m.min(10)) as f64 * 2.0;
    }

    // Lookahead coupling: if the next item exactly matches post_residual, huge reward.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits after this placement: mild reward
        score -= 15.0;
    } else if next_item_size > post_residual {
        // placement strands the next item: penalize proportional to leftover
        score += post_f * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: prefer keeping new bins closed unless open bins are fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; reduced when open bins have large mean residual
        // (fragmentation) or many bins already exist late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + mean_residual * 0.4 - progress * 20.0;
        if post_residual > 40 {
            score += 30.0; // opening a bin for a small item wastes capacity
        }
        if fitting_bins_count == 1 {
            score += 120.0; // never open when a last-chance bin exists
        }
    }

    // Slight pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to be useful are heavily penalized.
    // Treat gaps below a "usefulness" threshold as dead space.
    let dead_threshold: f64 = 10.0; // smallest typical item footprint
    if (post_residual as f64) < dead_threshold {
        // Quadratic dead-space penalty scaled by how close to zero the gap is.
        let gap = post_residual as f64;
        score += (dead_threshold - gap) * (dead_threshold - gap) * 2.0;
    }

    // Reward tight fits: the smaller post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual == 1 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (which would waste this bin's residual entirely).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: mild reward proportional to how well it uses the gap
        score -= 6.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this gap -> gap likely becomes dead space
        score += 10.0;
    }

    // Open-bin pressure: penalize adding bins when many are already open;
    // encourage filling existing bins as open_bins_count grows.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln() * 3.0;
    } else {
        // New bin: penalize more when many bins already open and mean residual is large.
        score += (open_bins_count as f64) * 2.0 + mean_residual * 0.15;
    }

    // Stream progression: early on, be more tolerant of opening bins; late in the
    // stream, strongly prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 15.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean (already tight),
    // prefer it; if above the mean, mild penalty (it's a wasteful bin to add to).
    let bin_res_f = bin_residual as f64;
    if bin_residual != bin_capacity {
        score -= (mean_residual - bin_res_f).max(0.0) * 0.5;
        score += (bin_res_f - mean_residual).max(0.0) * 0.2;
    }

    // Penalize leaving a residual that no plausible item (>=1) can use efficiently:
    // very small non-zero gaps get an extra nudge toward being avoided.
    if post_residual > 0 && post_residual < 3 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item exactly
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    }
    // Penalize leaving a leftover that is too small for the next item (dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 60.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward leftover that can at least fit the next item
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 30.0 + 0.2 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Mild penalty for opening new bins when stream is early and few bins exist
    if bin_residual == bin_capacity {
        score += 40.0 + 10.0 * open_bins_count as f64;
        // But new bin is fine if no open bin gives a decent fit
        if next_item_size > 0 && bin_residual - item_size >= next_item_size {
            score -= 20.0;
        }
    }

    // Progress-based tightening: later in the stream, waste is costlier
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.5 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space: residuals too small to ever be useful (below min item size 1..100 unknown, use ~10).
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // nearly perfect fill
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early in the stream
    // and when open bins have large mean residual (fragmentation would grow).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 30.0 * (1.0 - progress);
        score += 0.5 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0; // existing bins have room; don't open new one
        }
        // But if item is huge and mean residual can't hold it, allow new bin softly.
        if item_size as f64 > mean_residual + 5.0 {
            score -= 25.0;
        }
    }

    // Prefer filling bins whose residual is close to the item (best-fit flavor).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 10.0 * tightness * (bin_residual != bin_capacity) as i32 as f64;

    // Mild global pressure: many open bins -> consolidate into existing ones.
    score += 0.15 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress) + 15.0 * (norm_pr * norm_pr) * (1.0 - progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize when this bin could also serve the lookahead item
    if next_item_size > 0 && next_item_size <= post_residual {
        let waste = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - waste / cap) * (1.0 - progress);
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: prefer it only when residuals are large and stream is early
    if bin_residual == bin_capacity {
        score -= 12.0 * (1.0 - progress) * (1.0 - norm_pr);
        score += 10.0 * progress;
    }

    // Coupling with mean residual: avoid bins far from the mean late in stream
    score += 5.0 * progress * ((pr - mean_residual).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "coarse" residue classes (multiples of 10) are more reusable.
    let res_class = post_residual % 10;
    let res_quot = post_residual / 10;
    let class_bonus = match res_class {
        0 => 6.0,
        5 => 3.0,
        _ => 0.0,
    };
    score -= class_bonus * (1.0 + res_quot as f64 / 10.0);

    // Penalize tiny dead space (waste) nonlinearly.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += (20 - post_residual) as f64 * 0.8;
    }

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose residual can exactly host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 30.0;
        } else {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual too small for lookahead item: dead space penalty.
        score += (post_residual as f64) * 0.5;
    }

    // Harmonic threshold on next_item_size: big next items favor keeping
    // large residuals intact (prefer small bins for small items).
    if next_item_size >= 50 {
        score += (item_size as f64) * 0.3;
    }

    // Last-chance bin: strong reward to use the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: baseline cost of opening a bin, softened when
    // stream is early or many bins already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 40.0 * progress - 3.0 * (open_bins_count as f64).min(10.0);
        // If item nearly fills a fresh bin, opening is attractive.
        if item_size >= 80 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0;
        }
        return score;
    }

    // Tightness coupling: prefer bins where item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Mean residual coupling: when open bins are generally roomy, prefer
    // consuming the tightest bin even more.
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Medium gaps (10..20) are semi-dead for typical item sizes.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0 + 0.5 * (20 - post_residual) as f64;
    }

    // Reward tight fits (exact fills are ideal).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit
    // or when open-bin pressure is high.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        if post_residual > 0 && post_residual < 10 {
            score += 50.0; // opening a fresh bin for a near-full item is fine
        }
        // If the next item could pair with the remainder, opening is more OK.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage packing.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: penalize leaving a remainder the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.4 * (next_item_size - post_residual) as f64;
    }
    // Reward remainders that exactly accommodate the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Late in the stream, residual waste matters more (less time to fill it).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets strong discount.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tight * tight;

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        let match_quality = 1.0 - gap / cap;
        score -= 25.0 * match_quality * match_quality;
    } else if next_item_size > 0 {
        // Next item can't use the leftover: penalize dead space proportionally.
        score += 8.0 * (post_residual as f64) / cap;
    }

    // Relative to mean residual: prefer bins that are already more filled than average.
    let rel = (bin_residual as f64 - mean_residual) / cap;
    score -= 10.0 * rel;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless this is a bad fit elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference for bins that could still fit a typical mid-size item afterwards.
    if post_residual >= 10 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward small post_residual relative to capacity
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * tight * 30.0;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0 - 2.0 * post_residual as f64;
    }

    // Penalize leaving dead space that the next item could not use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            // next item can still fit here: bonus for keeping usable space
            score -= 8.0 * (1.0 - (post_residual as f64 - nx) / bin_capacity as f64);
        } else {
            // dead space for the known next item: penalty scaled by dead amount
            let dead = (post_residual as f64) / nx.max(1.0);
            score += 10.0 * dead;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Coupling with global mean residual: prefer bins whose residual is close to the mean
    // (keeps bin pool balanced) but penalize bins far below mean residual (wasteful holes)
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff.abs();

    // Early in the stream: be more willing to spread items across bins (exploration);
    // late in the stream: consolidate tightly.
    score -= (1.0 - progress) * 3.0 * (open_bins_count as f64).ln().max(0.0);
    score += progress * 2.0 * post_residual as f64 * 0.05;

    // New-bin candidate handling: only attractive when no good open fit exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin
        score += 40.0;
        // If few bins fit the item, opening fresh space is reasonable
        score -= 15.0 * fitting_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin avoids fragmentation
        score -= 0.2 * item_size as f64;
        // Late stream: prefer reusing existing bins
        score += 25.0 * progress;
        // If next item is large, a fresh bin gives flexibility
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild penalty on very fragmented small residuals that nothing (10..80) can use
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_n = pr / cap;
    let item_n = item_size as f64 / cap;
    let next_n = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_n * pr_n * (1.0 - pr_n) * (0.5 + progress) + pr_n * progress * progress;
    score += 20.0 * poly;

    // Reward tight fits, more strongly late in the stream
    score -= (1.0 - pr_n) * (1.0 - pr_n) * (1.0 + 2.0 * progress) * 30.0;

    // Lookahead: reward bins whose post-residual matches the next item
    if next_item_size > 0 {
        let gap = (pr - next_n * cap).abs();
        score -= 15.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
    }

    // Penalize fragmenting a bin when many bins can fit the item
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * pr_n * 5.0;
    } else {
        // Last-chance bin: strongly favor using it
        score -= 25.0 * (1.0 - pr_n);
    }

    // Mean residual context: prefer bins near the mean to keep flexibility
    score += ((pr - mean_residual) / cap).abs() * 10.0 * (1.0 - progress);

    // New-bin candidate handling: only attractive for very large items early
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - item_n) * (1.2 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are worthless
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 10 {
        score += 25.0; // unusable dead space penalty
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Reward tight fits scaled by item size
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; prefer filling existing
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (1.0 - progress) * 4.0;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize unless it beats a poor fit
        score += 15.0 + pressure * 2.0;
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.5 {
            score -= 10.0; // big item coming, fresh bin may help
        }
    }

    // Lookahead: if next item fits into post_residual, reward
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 12.0;
    }

    // Prefer bins with below-mean residual (keeps a spread of usable bins)
    if bin_residual < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            // Perfect pairing: next item exactly fills this bin afterwards.
            score -= 60.0;
        } else {
            // Penalize mismatch scaled by how far off the pairing is.
            score += (diff as f64).powf(1.3) * 0.25;
        }
        // If the next item also fits after this placement, mild bonus.
        if next_item_size <= post_residual {
            score -= 8.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 40.0;
    }

    // Penalize dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible (post_residual near capacity).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // But if the next item exactly matches what this item leaves (post_residual),
        // opening a fresh bin is attractive.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 50.0;
        }
    }

    // Small reward for very tight fits (small absolute residual).
    if post_residual <= 10 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: strongly reward tight fits.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // Penalize leaving residuals that no typical item can use (dead space).
    let dead = (post_residual as f64) / (bin_capacity as f64);
    score += 30.0 * dead * dead;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward;
    // if post-residual is too small for the next item, penalize the wasted sliver.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if nx <= pr {
            let gap = pr - nx;
            if gap == 0.0 {
                score -= 35.0; // chain of perfect fits
            } else {
                score -= 10.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // residual too small for next item: penalize proportionally to unusability
            score += 8.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // Global state coupling: when mean residual is high, prefer packing into
    // existing bins (avoid bin proliferation); when low, new bins are cheap.
    let mean_gap = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score += 6.0 * mean_gap;

    // Many open bins -> discourage opening new ones implicitly by favoring fills.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and time.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 + 2.0 * (open_bins_count as f64) + 10.0 * progress;
        // Opening a new bin is acceptable if this item is large (little waste risk later).
        score -= 0.15 * (item_size as f64);
    }

    // Mild time-horizon modulation: early on, be conservative with tight fits
    // (keep flexible space); late, squeeze hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    let poly = 1.0 + 0.8 * progress * x - 0.5 * x * x + 0.3 * progress * x * x * x;
    score *= poly;

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (cap - pr) * 0.15 * (1.0 + progress);

    // Penalize dead space that is too small to be useful (below ~item range floor)
    let dead = x - (x * x) * 0.5;
    score += dead * 20.0 * (1.0 - progress * 0.5);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 0.1 * (next_item_size as f64 - pr).abs();
    }

    // Mean residual coupling: prefer bins deviating from mean when mean is high
    score += 0.2 * (mean_residual - pr).abs() * (1.0 - progress);

    // Mild penalty for proliferating bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    // Class 1: small leftover (1..=10) -> good, likely still fillable.
    // Class 2: medium leftover (11..=30) -> moderate.
    // Class 3: large leftover (>30) -> wasteful, penalize.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score -= 5.0;
    } else {
        score += (post_residual as f64 - 30.0) * 0.15;
    }

    // Harmonic subdivision: leftover divisible nicely by typical item sizes
    // (multiples of 10 classes). If post_residual % 10 == 0, the space is
    // reusable by the common item granularity.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual > 0 && post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover will be reduced again
            let rem = post_residual - next_item_size;
            score -= 15.0 - (rem as f64) * 0.1;
        } else {
            // next item cannot use this bin's leftover: dead space risk
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // would leave very fragmented space. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; relax late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 - 15.0 * progress;
        // If many bins are open and mean residual is high, new bin is fine.
        if open_bins_count > 3 && mean_residual > 40.0 {
            score -= 20.0;
        }
    }

    // Slight preference for fuller bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Integer-division threshold: bins whose residual is in the "awkward"
    // range (residual / 2 < smallest useful item ~ 10) are nearly dead.
    if bin_residual > item_size && (bin_residual - item_size) < 10 {
        score -= 12.0; // near-perfect fill, excellent
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space super-linearly.
    // A residual that is too small for the smallest plausible item (>=1, but
    // practically gaps < ~15 are near-dead) should be heavily punished.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 2.0;
    } else {
        // Mild reward for keeping moderately usable residual space.
        score -= 3.0;
    }

    // Perfect fit bonus: strongly favor bins where the item nearly fills the bin.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Next-item lookahead: if the next item fits exactly into post_residual,
    // reward this placement (creates a chained perfect fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else if gap <= 10 {
            score -= 8.0;
        }
    }
    // If next item would be blocked by this placement, add small penalty.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: penalize spreading across many bins when few
    // fitting bins exist; encourage consolidation.
    let pressure = (open_bins_count as f64).ln() * 2.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., tighter bins) to keep large residuals available for large items.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: an empty bin has high residual; make it
    // attractive only when no open bin offers a good fit (high post_residual
    // penalty elsewhere will push its score down naturally). Add slight
    // penalty so we prefer reusing open bins when fits are decent.
    if bin_residual == bin_capacity {
        score += 6.0;
        // But if many bins are open and this item is small, opening fresh
        // bins is wasteful; scale penalty with open bins count.
        score += open_bins_count as f64 * 0.5;
    }

    // Stream progression: late in the stream, be slightly more conservative
    // about opening new bins (prefer filling existing ones).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain match: big reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item fits: reward proportional to tightness of chain.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space left behind.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
        // Extra small bonus when post_residual plus next item nearly fills bin.
        let two_step_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        if two_step_fill > 0.9 {
            score -= 15.0 * (two_step_fill - 0.9);
        }
    } else {
        // Last item: prefer minimal residual.
        score += 2.0 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual far above mean are better targets
    // for large items (consume the fat), bins below mean get penalized.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid wasting it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }
    // Many fitting bins: prefer the tightest (post_residual already handles that),
    // but add mild penalty to spread preference away from versatile bins.
    if fitting_bins_count > 2 {
        score += 3.0;
    }

    // New-bin candidate handling: only open a new bin when item is large and
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let best_open = if fitting_bins_count > 0 { (bin_residual - item_size) as f64 } else { f64::MAX };
        // Encourage new bin for big items early/mid stream; discourage late when
        // consolidation matters.
        let open_bonus = 40.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);
        score = (bin_capacity as f64) - open_bonus;
        // If a fitting bin exists with small post-residual, keep using it instead.
        if best_open < 20.0 {
            score += 100.0;
        }
        let _ = best_open;
    }

    // Slight penalty for leaving awkward tiny residuals (<10) that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: tightness of fit (lower post_residual is better), non-linearly emphasized.
    let mut score = post * (1.0 + 0.8 * fit_frac) + (post / cap).powi(3) * 40.0;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tolerate larger residuals less (dead space costs more).
    let progress_coupling = (post / cap) * (post / cap) * (0.5 + 2.0 * progress * (1.0 - progress + 0.5));
    score += progress_coupling * 30.0;

    // Last-chance bin: strongly reward using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            let gap = (post - next) / cap;
            score -= 18.0 * (1.0 - gap * gap);
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += 4.0 * ((next - post) / cap);
        }
    }

    // New-bin candidate: penalize opening a bin, but relax when item is large
    // or no good fits exist (fitting_bins_count small) or mean residuals are tiny.
    if bin_residual == bin_capacity {
        let openness = (fit_frac * fit_frac) * 20.0
            + (mean_residual / cap) * 10.0
            + (fitting_bins_count as f64) * 6.0;
        score += 45.0 - openness.min(40.0);
    } else {
        // Mild bonus for using an already-open bin, stronger when many bins are open.
        score -= 2.0 + 0.15 * open_bins_count as f64;
    }

    // Reward near-exact fits with smooth exponential term.
    score -= 10.0 * (-(post / cap * 6.0)).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes capture "pairing potential"
    let cls = post_residual % 10;
    // Residuals that are exact multiples of 10 pair perfectly with 10-multiple items
    if cls == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Dead-space classes: residuals of 1..9 are hard to fill (items >= 10... but sizes 1..100 allowed)
    if cls != 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Integer-division thresholds: post_residual in [50,100) means bin is half-full -> good
    let half = post_residual / (bin_capacity / 2);
    if half == 0 && post_residual > 0 {
        score -= 5.0; // post residual < 50 : bin more than half used, good packing
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect pair
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 12.0 * (1.0 - gap as f64 / 40.0).max(0.0);
            // harmonic class match between next item and post residual
            if post_residual % 10 == next_item_size % 10 {
                score -= 4.0;
            }
        } else {
            // next item cannot use leftover; penalize proportional to leftover size
            score += (post_residual as f64) * 0.35;
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive if current bin would leave a bad harmonic class
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let bad_class = (post_residual < 10 && post_residual > 0)
            || (next_item_size > 0 && next_item_size > post_residual && post_residual > 0);
        if bad_class {
            score -= 18.0; // open new bin instead of creating dead space
        } else {
            score += 10.0 + 0.05 * open_bins_count as f64; // discourage opening bins unnecessarily
        }
    }

    // Mean residual alignment: prefer bins near the mean (balanced packing)
    score += ((post_residual as f64) - mean_residual).abs() * 0.15;

    // Early stream: be more aggressive about tight fits; late stream: conserve bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_residual - post_residual) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Dead space penalty scaled by how much of the residual is wasted.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 80.0 * waste * waste;

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    // (penalize opening new bins); when few bins are open, less pressure.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 15.0 + 25.0 * progress;
    score += new_bin * (pressure + 5.0 * open_bins_count as f64);

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; penalize leaving a gap that is nearly-but-not usable.
            if post_residual > 0 && post_residual < next_item_size {
                score += 8.0;
            }
        }
    }

    // Prefer bins with residuals close to the mean (balanced packing) mildly.
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), but punish unusably tiny leftovers.
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0; // strong reward: this bin becomes perfectly full next step
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Slack after next item would be post_residual - next_item_size
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack_after_next / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize proportionally to how much is stranded
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / (bin_capacity as f64);
    }

    // Reward matching against the mean residual landscape: bins whose post_residual
    // stays close to the mean keep the bin family "usable" for future items.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * deviation;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    } else if fitting_bins_count > 1 {
        // mild penalty for crowding a popular bin, keeps alternatives open
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Early in the stream, prefer consolidating into existing bins (small penalty
    // for opening new bins is implicit via the new-bin candidate having max post_residual).
    score -= 5.0 * progress;

    // Penalize leaving very small dead space (< 10) that likely no item can use,
    // unless it's exactly the next item's size (already rewarded above).
    if post_residual > 0 && post_residual < 10 && !(next_item_size > 0 && post_residual == next_item_size) {
        score += 12.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): it should only win when
    // no open bin offers a decent fit; its base score is already high (post_residual = 100),
    // add a mild extra penalty so it loses to any reasonable existing-bin fit.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: penalize residuals that cannot host the next item,
    // reward residuals that can host it snugly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack * 0.15; // snug future fit preferred
        } else {
            score += 8.0; // dead space relative to lookahead
        }
        // If next item is huge, keeping larger residual matters more.
        if next_item_size >= 50 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins could reasonably absorb it.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count > 0 {
            let avg_fit_waste = mean_residual.max(0.0);
            if (item_size as f64) <= avg_fit_waste + 5.0 {
                score += 25.0; // an open bin fits almost as well
            }
        }
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Favor filling bins with larger residual (larger waste to reclaim).
        score -= (bin_residual as f64) * 0.05;
    }

    // Mild penalty when residual diverges badly from mean residual
    // (keeps bin population homogeneous for future packing).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    // Slight preference for bins with many alternatives to spread load.
    if fitting_bins_count > 3 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted residual, with non-linear growth for tiny dead space.
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, small residuals become more valuable (tight packing matters).
    let pr_norm = pr / cap;
    let tightness = (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 12.0 * tightness * (0.5 + 0.5 * progress);

    // Quadratic interaction: prefer residuals that leave room for the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            // lookahead fits: reward, strongest when gap is small (smooth quadratic)
            let g = gap / cap;
            score -= 8.0 * (1.0 - g) * (1.0 - g) * (0.4 + 0.6 * progress);
        } else {
            // lookahead doesn't fit: mild penalty scaled by shortfall
            let d = (-gap) / cap;
            score += 4.0 * d * d * cap;
        }
    }

    // Last-chance bin: smooth reward for using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Global context coupling: penalize bins far from mean residual (smooth cubic-ish term).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Cubic saturation of residual: very large residuals are less attractive mid-stream.
    score += 3.0 * pr_norm * pr_norm * pr_norm * (1.0 - progress);

    // New-bin candidate handling: empty bin gets neutral-ish score with progress-based drift,
    // so late in the stream we prefer reusing open bins.
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.45 * progress);
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            score -= 2.0 * (1.0 - (nxt / cap)) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on residual space.
    let pr = post_residual;
    let class = pr % 10; // fine-grained harmonic class
    let coarse = (pr / 10) % 10; // decade class

    // Reward residuals that are "harmonically aligned" with typical small items.
    if pr > 0 {
        // Residuals divisible by common item sizes leave less dead space.
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else if class == 1 || class == 9 { score -= 1.5; }
        else { score += (class as f64) * 0.3; }
    }

    // Dead-space penalty grows quadratically for tiny unusable residuals.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * (10 - pr) as f64 * 0.4;
    }

    // Integer-division threshold on decade class: mid-range residuals are valuable.
    match coarse {
        0 => score += 4.0,   // nearly full bin: fine if it was a perfect fit
        1..=2 => score -= 5.0, // small residual, good packing
        3..=6 => score -= 2.0, // mid residual, flexible
        _ => score += 1.0,     // large residual: wasted opportunity
    }

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= pr {
            score -= 8.0 + nxt * 0.05; // chain placement possible
            // Harmonic bonus: next item lands post residual into a nice class
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 3.0; }
        } else {
            score += (next_item_size as f64 - pr as f64) * 0.15; // next item won't fit here
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 10.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // New-bin candidate: open a fresh bin only when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = (open_bins_count as f64).sqrt();
        score = cap * 0.55 + openness * 2.0 - progress * 5.0;
        if fitting_bins_count == 0 { score -= 25.0; }
        if fitting_bins_count == 1 { score += 18.0; } // keep the last-chance bin alive
        if mean_residual > 35.0 { score += 6.0; } // plenty of slack already open
    }

    // Slight preference to fill bins with lower mean residual (tighten the fleet).
    score += (mean_residual - post_residual as f64) * 0.05;

    // Progress-based tie-break: later in stream, favor consolidation.
    score -= (step_index as f64 / total_items.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest possible item (1) are pure waste; residuals below a usable
    // threshold relative to typical item sizes are heavily penalized.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 40.0;
    } else if post_residual < 10 {
        // Unusable dead space: heavy penalty.
        score += 60.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual < 25 {
        // Small gap: moderately penalize, worse if next item can't use it.
        let mut gap_pen = (25 - post_residual) as f64 * 1.5;
        if next_item_size > 0 && next_item_size > post_residual {
            gap_pen += 8.0;
        }
        score += gap_pen;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // If the next item fits exactly into the post residual, big reward
    // (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // residuals are still large; encourage consolidation.
    if open_bins_count > 0 {
        let avg_use = 1.0 - mean_residual / bin_capacity as f64;
        // If this bin is below average fullness, penalize slightly to
        // prefer filling fuller bins first.
        let bin_use = 1.0 - bin_residual as f64 / bin_capacity as f64;
        if bin_use < avg_use {
            score += 6.0 * (avg_use - bin_use);
        } else {
            score -= 3.0 * (bin_use - avg_use);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // bins would leave large unusable gaps.
    if bin_residual == bin_capacity {
        // Base neutral score for a fresh bin.
        score = bin_capacity as f64 * 0.5;
        if fitting_bins_count == 0 {
            // No open bin fits: fresh bin is the only option.
            score -= 100.0;
        } else if post_residual < 10 {
            // Placing here wastes almost nothing at start; mild bonus.
            score -= 5.0;
        }
        // Early in the stream, fresh bins are cheaper (more future items
        // to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, strongly favor
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit: penalize leftover dead space
            score += 0.3 * post_residual as f64;
        }
    }

    // Compare post_residual against mean residual: keep residuals balanced/uniform
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when item is large and open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        score = 40.0 + 30.0 * fragmentation + 20.0 * (1.0 - progress) - (item_size as f64 / 4.0);
        if next_item_size > item_size {
            score -= 10.0;
        }
    }

    // Mild penalty for wasting large residual capacity on tiny items
    if post_residual > 0 && (item_size as f64) < 0.4 * bin_residual as f64 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 8.0;

    // Penalize small unusable leftovers (dead space) with a nonlinear bump.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current best fit is poor or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = (mean_residual - item_size as f64).abs();
        // If an open bin fits well (small waste), discourage new bin.
        if fitting_bins_count > 0 && post_residual > 0 {
            score += 6.0 + 0.05 * (post_residual as f64);
        }
        // Large items early in stream: new bins are cheap-ish.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 4.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);
        // If no open bin fits well, new bin looks better.
        score -= poor_fit_penalty * 0.03;
        // Many open bins: discourage proliferation.
        score += 0.3 * open_bins_count as f64;
    }

    // Lookahead: if next item could fill this bin's post-residual, reward placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }
    // If next item exactly fills the leftover, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }
    // If next item is huge and this bin would leave a sliver, penalize slightly.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 4.0;
    }

    // Slight preference for bins with larger residuals when mean residual is high
    // (keeps many mid-size bins usable).
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 0.02 * (bin_residual as f64 - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to stream progress.
    // Early on, prefer tight fits (low post_residual); later, weight residual less so we
    // keep filling existing bins rather than opening new ones.
    let progress_weight = 0.35 + 0.65 * progress * progress;
    let mut score = pr * (1.0 + 0.8 * progress_weight * (1.0 - norm_pr) * (1.0 - norm_pr));

    // Non-linear penalty on large leftover space, modulated by progress (dead space
    // matters more as the stream nears its end).
    score += 12.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Perfect-fit reward: smooth quadratic bonus centered at post_residual = 0.
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Lookahead coupling: reward bins whose post residual matches the next item size,
    // with a smooth cosine-shaped affinity.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 6.0 * (0.5 + 0.5 * (std::f64::consts::PI * diff).cos()) * (1.0 - diff.abs().min(1.0));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty when many bins are open relative to progress: discourage bin sprawl.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // Alignment with mean residual: penalize bins far above mean residual (fragmented),
    // smooth quadratic coupling.
    score += 0.15 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // New-bin candidate handling: empty bin gets a moderate default score that is
    // beaten only by good fits into existing bins.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) + 20.0 * (1.0 - (next_item_size as f64 / cap).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common item sizes
    // (10, 20, 25, 50) are more reusable; penalize odd / prime-ish leftovers.
    let reusable = (post_residual % 10 == 0) as f64 * 6.0
        + (post_residual % 20 == 0) as f64 * 4.0
        + (post_residual % 25 == 0) as f64 * 4.0
        + (post_residual % 50 == 0) as f64 * 3.0;
    score -= reusable;

    // Dead space: tiny unusable leftovers (below the minimum plausible item size)
    if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64;
    } else if post_residual <= 15 {
        score += 6.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit: post residual small relative to capacity
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits: mild reward proportional to leftover after next
        let after_next = post_residual - next_item_size;
        score -= 10.0 * (after_next as f64 / bin_capacity as f64);
        if after_next % 10 == 0 {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here: penalize leaving moderately-sized waste
        score += 5.0;
    }

    // New-bin candidate logic: only prefer a fresh bin when the current bin would
    // be left with awkward waste or the fit is very loose.
    if bin_residual == bin_capacity {
        let loose = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is attractive for small items when many bins are open
        // with slack, but bad when it's the last chance to fill an existing bin.
        score = 40.0 + 30.0 * loose;
        if fitting_bins_count <= 1 {
            score += 80.0; // don't open a new bin if existing bins barely fit
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress); // early on, slightly favor consolidation
        if mean_residual > item_size as f64 + 20.0 {
            score += 15.0; // plenty of slack exists in open bins
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - (post_residual as f64) * 2.0; // gap of 1 => +38, gap of 9 => +22
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is highly desirable
    }

    // Reward using bins whose residual was already small (tight packing).
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0; // enables a near-perfect follow-up placement
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate: mildly penalize so we only open when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 12.0 + 1.5 * open_bins_count as f64;
        // If mean residual across open bins is small, opening a fresh bin is attractive.
        if mean_residual < 15.0 {
            score -= 18.0;
        }
    }

    // Late-stream consolidation: near the end, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if leftover can host the next item exactly / well
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack * 0.5; // perfect chain match gets the biggest bonus
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else if next_item_size > 0 {
        // leftover cannot host the next item: penalize dead space, worse for small leftovers
        let dead = post_residual as f64;
        score += dead * 0.8;
        if dead < 10.0 {
            score += 40.0; // tiny unusable slivers are very bad
        }
    }

    // Compare post_residual to mean residual: leaving above-average residual is wasteful
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 150.0;
    }

    // Penalize opening a new bin, more early in the stream when open bins exist
    if is_new_bin {
        if open_bins_count > 0 {
            score += 120.0 + 80.0 * (1.0 - progress);
        }
        // but if no open bin fits at all, new bin is inevitable; neutralize
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
    }

    // Prefer tighter bins (small residual before placement) among comparable options
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    score
}
